      'Twoje ciało zaczyna się dostosowywać, gdy poziom dopaminy zaczyna się stabilizować. Możesz doświadczyć zmęczenia, zmiany nastroju, i silne skurcze, ale układ sercowo – naczyniowy już zaczyna odzyskiwać.';

  @override
  String get cocaineMilestone3Title => 'Dzień 3 - Szczytowe wyzwanie';

  @override
  String get cocaineMilestone3Description =>
      'Objawy odstawienne często szczytowe w tym czasie. Możesz doświadczyć intensywnych rzeźni, drażliwość, anxietyty. to jest tymczasowe - twój mózg pracuje ciężko, aby przywrócić równowagę.';

  @override
  String get cocaineMilestone7Title =>
      'Jeden tydzień - Fizyczna regeneracja zaczyna się';

  @override
  String get cocaineMilestone7Description =>
      'Twoje serce i ciśnienie krwi stabilizują się. Podczas gdy psychologiczne pragnienia mogą utrzymywać się, twoje ciało jest uzdrawiające.';

  @override
  String get cocaineMilestone14Title =>
      'Dwa tygodnie - znalezienie stabilności';

  @override
  String get cocaineMilestone14Description =>
      'Wiele osób zaczyna czuć się bardziej stabilny. poziom energii są improwizacja, i ostre objawy odstawienne. Twoje zdrowie układu sercowo – naczyniowego nadal znacznie się poprawia.';

  @override
  String get cocaineMilestone60Title =>
      'Dwa miesiące - Uśpiony i nastrojowy Popraw';

  @override
  String get cocaineMilestone60Description =>
      'Jakość snu jest zauważalnie lepsza, jak chemia mózgu nadal normalizująca. Możesz czuć się bardziej wypoczęty i doświadczania bardziej stabilnych nastrojów przez cały dzień.';

  @override
  String get cocaineMilestone90Title => 'Trzy miesiące - Przywracanie mózgu';

  @override
  String get cocaineMilestone90Description =>
      'Koncentracja, podejmowanie decyzji i kontrola emocjonalna są znacznie lepsze, a myślenie jest jasne.';

  @override
  String get cocaineMilestone180Title => 'Sześć miesięcy - jaśniejsze myślenie';

  @override
  String get cocaineMilestone180Description =>
      'Skanowanie mózgu pokazuje regenerację z przodu mózgu, obszar, który wspiera planowanie i samokontroli. Pamięci, kontroli impulsowej, i jasne myślenie nadal wzmacniać.';

  @override
  String get cocaineMilestone365Title =>
      'Rok - Zdrowie układu sercowo – naczyniowego';

  @override
  String get cocaineMilestone365Description =>
      'Twoje serce i układ sercowo – naczyniowy mają niezwykłą rekonwales. ciśnienie krwi i częstość akcji serca są normalizowane. Ryzyko zawału serca i udaru zmniejszył się znacznie. Twoje ciało jest uzdrawiające.';

  @override
  String get cocaineMilestone730Title => 'Dwa lata - Trwała windykacja';

  @override
  String get cocaineMilestone730Description =>
      'Uzdrowienie mózgu kontynuuje się z trwałą poprawą w zapamiętywaniu, skupieniu i regulacji emocjonalnych.Twoje ścieżki nerwowe znacznie się zreorganizowały, wspierając zdrowsze wzorce i lepsze ogólne samopoczucie.';

