  @override
  String get alcoholMilestone1Title => 'Jakość snu zaczyna poprawiać';

  @override
  String get alcoholMilestone1Description =>
      'Cykle snu REM zaczynają się normalizować w ciągu pierwszego dnia. Podczas gdy alkohol może pomóc zasnąć początkowo, zakłóca głęboki sen i cykli REM przez całą noc, powodując rozdrobniony sen.';

  @override
  String get alcoholMilestone3Title =>
      'Dzień 3: Ostry zespół odstawienny osiąga szczyt';

  @override
  String get alcoholMilestone3Description =>
      'Trzy dni to ogromny kamień milowy: objawy odstawienia alkoholu często osiągają szczyt około 72. godziny. Drżenie, bezsenność, pobudzenie, poty, szybkie tętno i wysokie ciśnienie mogą być teraz najsilniejsze. Ciężkie odstawienie może pojawić się także później, w tym majaczenie między 3. a 8. dniem po odstawieniu.';

  @override
  String get alcoholMilestone7Title => 'Wzmacnia układ immunologiczny';

  @override
  String get alcoholMilestone7Description =>
      'Nawet pojedyncza dawka ciężkiego picia może zaburzać odporność do 24 godzin, a przewlekłe picie znacząco osłabia zdolność organizmu do walki z infekcjami.';

  @override
  String get alcoholMilestone14Title =>
      'Przywracanie głośności mózgu rozpoczyna się';

  @override
  String get alcoholMilestone14Description =>
      'Objętość mózgu zaczyna się poprawiać w ciągu pierwszych dwóch tygodni.';

  @override
  String get alcoholMilestone30Title => 'Ciśnienie krwi normalizuje';

  @override
  String get alcoholMilestone30Description =>
      'Regularne spożywanie alkoholu podnosi ciśnienie krwi, ale abstynencja przez około miesiąc może pomóc przywrócić ciśnienie krwi do zdrowszego poziomu.';

  @override
  String get alcoholMilestone60Title => 'Poprawia czynność wątroby';

  @override
  String get alcoholMilestone60Description =>
      'Wątroba wykazuje wymierną poprawę funkcji. Ten narząd regeneracyjny może uleczyć się znamiennie po uszkodzeniu wywołanym przez alkohol, z enzymami wątrobowymi i nagromadzeniem tłuszczu wykazującym poprawę w ciągu 2 miesięcy abstynencji.';

  @override
  String get alcoholMilestone90Title =>
      'Myślenie i poprawianie pamięci wyraźnie';

  @override
  String get alcoholMilestone90Description =>
      'Pierwsze trzy miesiące przyniosły znaczne korzyści w zakresie pamięci, koncentracji i podejmowania decyzji, a ożywienie gospodarcze będzie kontynuowane w kolejnych miesiącach.';

  @override
  String get alcoholMilestone180Title =>
      'Objętość mózgu i funkcja Kontynuuj odzyskiwanie';

  @override
  String get alcoholMilestone180Description =>
      'Sześć miesięcy trzeźwości daje mózgowi trwały czas do odzyskania. Objętość mózgu i umiejętności myślenia nadal poprawić.';

  @override
  String get alcoholMilestone365Title =>
      'Redukcja ryzyka raka może się rozpocząć';

  @override
  String get alcoholMilestone365Description =>
      'Rok abstynencji może zacząć zmniejszać ryzyko zachorowania. podczas gdy alkohol wyraźnie zwiększa ryzyko dla kilku nowotworów złośliwych, piersi, jelita grubego, przełyku, badania nad harmonogramem zmniejszenia ryzyka jest nadal pojawiający się i różni się w zależności od rodzaju nowotworu.';

  @override
  String get smokingMilestone1Title => 'Przecieki z monotlenku węgla';

  @override
  String get smokingMilestone1Description =>
      'Twoja krew oddycha ponownie! W ciągu 24 godzin, poziom tlenku węgla spada do normy i poziom tlenu wzrasta. Twoje serce nie musi pracować nadgodziny już pompować zatrutą krew wokół ciała.';

  @override
  String get smokingMilestone3Title => 'Nikotyna Szczyty wycofujące';

  @override
  String get smokingMilestone3Description =>
      'Potwór nikotynowy jest w swoim gniewie, ale wygrywasz bitwę! Cała nikotyna opuściła swój system. Najgorsze pragnienia się teraz, ale one również bilet do wolności po drugiej stronie.';

  @override
  String get smokingMilestone7Title => 'Smak zapach Dramatycznie poprawić';

  @override
  String get smokingMilestone7Description =>
      'Jedzenie stanie się przygodą ponownie! Palenie niszczy kubki smakowe i zapach receptorów. tydzień w, i ponownie odkrywanie smaków zapomniałeś istnieć. przygotować się na poważne uznanie żywności!';

  @override
  String get smokingMilestone14Title => 'Ulepszenie cyrkulacji';

  @override
  String get smokingMilestone14Description =>
      'Twoje nogi dziękują ci z każdym krokiem! Przekrwienie krwi poprawia dramatycznie, czyniąc spacery i ćwiczenia zauważalnie łatwiejsze. Te schody nie wyglądają tak zastraszające więcej, są one?';

  @override
  String get smokingMilestone30Title => 'Zwiększona funkcja płuc';

  @override
  String get smokingMilestone30Description =>
      'Twoje płuca rzucają comeback party! Cilia odrastają i zamiatają lata smoły i brudu. Płuca zdolność zwiększa znacząco, i że kaszel smokerhos jest historią.';

  @override
  String get smokingMilestone90Title => 'Heart Attack Risk Drops Znacznie';

  @override
  String get smokingMilestone90Description =>
      'Twoje serce wysyła listy miłosne! Trzy miesiące wolne od dymu i twoje ryzyko sercowo – naczyniowe już spadła znacznie. Twój układ sercowo – naczyniowy goi się szybciej, niż myślisz, że możliwe.';

  @override
  String get smokingMilestone180Title =>
      'Komórki odpornościowe płuc wracają do formy';

  @override
  String get smokingMilestone180Description =>
      'Sześć miesięcy bez palenia to prawdziwy sukces dla odporności płuc. W badaniu okołooperacyjnym odpowiedź przeciwbakteryjna makrofagów pęcherzykowych po 3–12 miesiącach bez papierosów była bliższa wzorcowi osób nigdy niepalących niż po dwóch miesiącach. Pierwsza linia obrony płuc miała miesiące na regenerację.';

  @override
  String get smokingMilestone365Title =>
      'Ryzyko uderzenia zmniejsza się znacząco';

  @override
  String get smokingMilestone365Description =>
      'Jeden pełny rok wolności! Twoje ryzyko udaru zmniejszył się znacznie, a naczynia krwionośne są goją się pięknie.';

  @override
  String get smokingMilestone1825Title =>
      'Ryzyko części nowotworów gwałtownie spada (5–10 lat)';

  @override
  String get smokingMilestone1825Description =>
      'Pięć lat zwycięstwa! Wchodzisz w okres 5–10 lat, w którym dodatkowe ryzyko nowotworów jamy ustnej, gardła i krtani spada o połowę, a ryzyko udaru nadal maleje. Długoterminowe korzyści właśnie nabierają rozpędu.';

  @override
  String get marijuanaMilestone1Title => 'Objawy odstawienne';

  @override
  String get marijuanaMilestone1Description =>
      'Mózg przystosowuje się do życia bez THC! W ciągu 24 – 48 godzin, może wystąpić drażliwość, ból, lub zaburzenia snu. To jest całkowicie normalne - receptory kannabinoidowe zaczynają się przesiedlać.';

  @override
  String get marijuanaMilestone3Title => 'Objawy fizyczne Szczyt';

  @override
  String get marijuanaMilestone3Description =>
      'Jesteś w najtrudniejszym punkcie, ale to wszystko jest pod górę stąd! Dni 2- 6 zazwyczaj zobaczyć szczytowe objawy odstawienia, w tym głowy, wyzyskiwanie, i zmiany nastroju. Twoje ciało ciężko pracuje, aby przywrócić równowagę.';

  @override
  String get marijuanaMilestone7Title => 'Wzory snu Popraw';

  @override
  String get marijuanaMilestone7Description =>
      'Słodkie sny są comeback! Po tygodniu bez cannabis, naturalna architektura snu zaczyna normalizować. REM snu odbicia, co prowadzi do bardziej żywych marzeń i lepszej jakości odpoczynku.';

  @override
  String get marijuanaMilestone14Title => 'Ostre końce odstawienne';

  @override
  String get marijuanaMilestone14Description =>
      'Burza minęła! Większość fizycznych objawów odstawienia znacznie zmniejsza się po dwóch tygodniu. twój nastrój stabilizuje się i codzienne funkcjonowanie staje się znacznie łatwiejsze. Najtrudniejsza część jest za tobą.';

  @override
  String get marijuanaMilestone30Title => 'Poprawia funkcję pamięci';

  @override
  String get marijuanaMilestone30Description =>
      'Twój mózg mgła jest clearing! Badania pokazują, że nauka słowna i pamięć zaczynają znacznie się poprawiać po zaprzestaniu używania konopi. Hippocampussy, kluczowe dla formacji pamięci, zaczyna działać lepiej.';

  @override
  String get marijuanaMilestone60Title => 'Stężenie Sharpens';

  @override
  String get marijuanaMilestone60Description =>
      'Modele skupienia: aktywowane! Dwa miesiące bez marihuany i zdolność do koncentracji i zachowania uwagi pokazuje znaczącą poprawę. Zadania w pracy i nauka stają się zauważalnie łatwiejsze do zarządzania.';

  @override
  String get marijuanaMilestone90Title => 'Powroty stabilności nastrojów';

  @override
  String get marijuanaMilestone90Description =>
      'Trzy miesiące bez cannabis przynosi mocniejszy nastrój, mniej niepokój, i lepsza kontrola stresu.';

  @override
  String get marijuanaMilestone180Title =>
      'Planowanie i podejmowanie decyzji - Recover';

  @override
  String get marijuanaMilestone180Description =>
      'Sześć miesięcy bez marihuany przynosi duże zyski w planowaniu, podejmowaniu decyzji i rozwiązywaniu problemów.';

  @override
  String get marijuanaMilestone365Title => 'Przywracanie struktury mózgu';

  @override
  String get marijuanaMilestone365Description =>
      'Rok bez cannabis daje obszary pamięci związane z mózgiem znaczny czas na odzyskanie. Nauka i poprawa pamięci są teraz częścią nowej normy.';

  @override
  String get opioidMilestone1Title => 'Ostry początek odstawienia';

  @override
  String get opioidMilestone1Description =>
      'Najtrudniejsza część zaczyna się teraz, ale nie jesteś sam. Ostre objawy odstawienne szczyt w pierwszych 24- 72 godziny. to twoje ciało rozpoczyna proces gojenia. Profesjonalne wsparcie medyczne jest kluczowe w tym faz. a';

  @override
  String get opioidMilestone7Title =>
      'Objawy fizyczne Szczyt Rozpoczyna się obniżanie';

  @override
  String get opioidMilestone7Description =>
      'Przeszedłeś przez sztorm! Najgorsze fizyczne objawy odstawienne zazwyczaj szczytują około dni 3- 5 i zaczynają maleć do dnia 7. Twoje ciało ciężko pracuje, aby przywrócić swój naturalny bilans.';

  @override
  String get opioidMilestone14Title => 'Wzory snu zaczynają się poprawiać';

  @override
  String get opioidMilestone14Description =>
      'Słodkie sny robią comeback! Dwa tygodnie w, naturalnej architektury snu zaczyna się restaurować. Opioidy zakłócają REM sen, ale twój mózg uczy się marzyć naturalnie ponownie.';

  @override
  String get opioidMilestone30Title =>
      'Myślenie i pamięć Rozpoczynają odzyskiwanie';

  @override
  String get opioidMilestone30Description =>
      'Mgła mózgowa rośnie! Miesiąc czystości i pamięci, podejmowania decyzji i jasne myślenie ulegają poprawie, gdy przednia część mózgu odzyskuje się z zmian związanych z opioidami.';

  @override
  String get opioidMilestone60Title => 'Poprawki w rozporządzeniu emocjonalnym';

  @override
  String get opioidMilestone60Description =>
      'Twoje emocje znajdują swój naturalny rytm ponownie. Dwa miesiące w rekonwalescencji i twój system nagród mózgu zaczyna reagować na codzienne przyjemności.';

  @override
  String get opioidMilestone90Title => 'Funkcja dopaminy znacząco odzyskuje';

  @override
  String get opioidMilestone90Description =>
      'Twój system nagradzania mózgów organizuje imprezę welcome- back! Trzy miesiące czyste i dopaminy funkcji znacznie poprawiła. Naturalne działania zaczynają czuć się satysfakcjonujące ponownie - jedzenie, muzyka, relacje.';

  @override
  String get opioidMilestone180Title => 'Wzmacnia układ immunologiczny';

  @override
  String get opioidMilestone180Description =>
      'Twój system odpornościowy jest z powrotem na patrolu duty! Sześć miesięcy rekonwalescencji i ciała naturalne obronne znacznie wzmocnione. Jesteś lepiej wyposażony, aby zwalczyć zakażenia i choroby.';

  @override
  String get opioidMilestone365Title =>
      'Neural Plasticity Brain Structure Ulepszenie struktury mózgu';

  @override
  String get opioidMilestone365Description =>
      'Twój mózg był zajęty renowacją! Pełen rok rekonwalescencji pokazuje znaczącą poprawę struktury mózgu i plastyczności neuronowej. Zmiany w przewlekłym zażywaniu opioidów są piękne gojenie.';

  @override
  String get opioidMilestone730Title =>
      'Długoterminowa stabilność odzysku 2 lata)';

  @override
  String get opioidMilestone730Description =>
      'Dwa lata siły i trwałości! Zbudowałeś nowe ścieżki neuronowe, radzenie sobie ze strategiami i wzorcami życia. Badania pokazują, że osiągnięcie tego kamienia milowego dramatycznie zmniejsza ryzyko nawrotu.';

  @override
  String get socialMediaMilestone1Title => 'Digital Detox Day!';

  @override
  String get socialMediaMilestone1Description =>
      'Badania pokazują, że nawet myślenie o sprawdzaniu mediów społecznościowych wyzwala te same ścieżki nerwowe co uzależnienie.';

  @override
  String get socialMediaMilestone3Title => 'Bardziej jak FOO – NO!';

  @override
  String get socialMediaMilestone3Description =>
      'Po trzech dniach niepokojące myśli typu „co mnie omija?” zaczynają słabnąć. Uczysz mózg na nowo, że prawdziwe życie jest znacznie ciekawsze niż starannie dobrany strumień treści!';

  @override
  String get socialMediaMilestone7Title => 'Uwaga Span: Złote ryby → Ludzkie';

  @override
  String get socialMediaMilestone7Description =>
      'Tydzień pierwszy zakończony! Zdolność do skupienia się bez sprawdzania telefonu co kilka minut jest już improwizowana. Badania pokazują, że nasze mózgi pragną trafień dopaminy z powiadomień - ale uczysz swój znaleźć nagrody gdzie indziej!';

  @override
  String get socialMediaMilestone14Title => 'Sen jak dziecko nie Zombiee)';

  @override
  String get socialMediaMilestone14Description =>
      'Dwa tygodnie bez przewijania przed łóżkiem = lepsza jakość snu! Niebieskie światło z ekranów tłumi produkcję melatoniny, ale naturalne rytmy snu odbijają się z powrotem pięknie.';

  @override
  String get socialMediaMilestone30Title =>
      'Prawdziwi przyjaciele udają, że lubią';

  @override
  String get socialMediaMilestone30Description =>
      'Miesiąc offline = znaczne zmniejszenie samotności i depresji! Badania dowodzą, że ograniczenie mediów społecznościowych powoduje znaczącą poprawę zdrowia psychicznego.';

  @override
  String get socialMediaMilestone60Title => 'Porównanie Trap: ESCAPED!';

  @override
  String get socialMediaMilestone60Description =>
      'Dwa miesiące bez stałego porównania społecznego = pewność siebie poprzez dach! Badania konsekwentnie pokazują, że media społecznościowe używają koreluje ze zmniejszoną samooceną, zwłaszcza z porównania społecznego w górę.';

  @override
  String get socialMediaMilestone90Title => 'Hobby Collector Level: Ekspert';

  @override
  String get socialMediaMilestone90Description =>
      'Trzy miesiące = mniej więcej 270+ godziny rekonwalescencji! To wystarczająco dużo czasu, aby nauczyć się umiejętności, przeczytać 15+ książki, lub dostać się głęboko w hobby. Twój mózg wzmacnia nawyki, które powtarzają, więc te offline rutyny stają się łatwiejsze i bardziej automatyczne.';

  @override
  String get socialMediaMilestone180Title =>
      'Zdrowie psychiczne Glow- Up Kompletne';

