      'Sześć miesięcy pozwala na znaczne dostosowanie systemów serotoniny i noradrenaliny. Oś HPA, która SNRI wpływa przez noradrenaliny jest normalizująca. Wiele osób donosi o szczególnie zwiększonej odporności na codzienne stresery w tym momencie.';

  @override
  String get snriMilestone365Title => 'Jeden rok: Odzyskiwanie osiągnięte';

  @override
  String get snriMilestone365Description =>
      'Rok oznacza pełny cykl podwójnego serotoniny – noradrenaliny odzyskiwania. Badania konsekwentnie pokazuje, że ludzie, którzy z powodzeniem zaprzestać SNRI pod nadzorem medycznym i przy pomocy wsparcia psychologicznego utrzymać dobre wyniki w jednym roku.';

