  @override
  String get tcaMilestone3Title => 'Dzień 3: Odbicie cholinergiczne';

  @override
  String get tcaMilestone3Description =>
      'Odstawienie TCA może wywołać rzeczywisty zespół odstawienny, a nadaktywność cholinergiczna jest jednym z proponowanych mechanizmów. Nudności, biegunka, ból brzucha, bezsenność, lęk, pobudzenie i ból głowy mogą pojawić się wcześnie, szczególnie po nagłym odstawieniu lub zbyt szybkim zmniejszaniu dawki. Dzień 3 to kamień milowy; moment wystąpienia i nasilenie objawów są różne.';

  @override
  String get tcaMilestone7Title => 'Tydzień: Pierwszy etap za Tobą';

  @override
  String get tcaMilestone7Description =>
      'Objawy odstawienne zwykle zaczynają się w ciągu kilku dni i często trwają kilka tygodni. Po tygodniu nadal mogą występować nudności, pocenie się, problemy ze snem, kołatanie serca i zawroty głowy. Siedem dni to realny postęp, a poprawa może postępować w różnym tempie.';

  @override
  String get tcaMilestone14Title =>
      'Dwa tygodnie: ostry etap odstawienia zwykle słabnie';

  @override
  String get tcaMilestone14Description =>
      'Typowe objawy odstawienia leków przeciwdepresyjnych, takie jak nudności, bezsenność, zaburzenia równowagi, objawy czuciowe i nadmierne pobudzenie, zwykle trwają od jednego do dwóch tygodni. W 14. dniu wiele osób dociera do końca tej ostrej fazy.';

  @override
  String get tcaMilestone30Title =>
      'Jeden miesiąc: ostry zespół odstawienny zwykle ustąpił';

  @override
  String get tcaMilestone30Description =>
      'Typowe objawy odstawienia leków przeciwdepresyjnych trwają zwykle od jednego do dwóch tygodni. Po 30 dniach większość osób ma już za sobą tę ostrą fazę; objawy grypopodobne, nudności, zaburzenia równowagi, bezsenność, zaburzenia czucia i nadmierne pobudzenie zwykle wyraźnie słabną lub ustępują.';

  @override
  String get tcaMilestone90Title =>
      'Trzy miesiące: ostry zespół odstawienny daleko za tobą';

  @override
  String get tcaMilestone90Description =>
      'Typowe objawy odstawienia leków przeciwdepresyjnych trwają zwykle od jednego do dwóch tygodni. Po 90 dniach jesteś ponad dziesięć tygodni za górną granicą tego typowego ostrego okna; objawy grypopodobne, nudności, zaburzenia równowagi, bezsenność, zaburzenia czucia i nadmierne pobudzenie zwykle dawno już osłabły lub ustąpiły.';

  @override
  String get tcaMilestone180Title => 'Sześć miesięcy: większość bez nawrotu';

  @override
  String get tcaMilestone180Description =>
      'Wśród osób odstawiających leki przeciwdepresyjne po leczeniu dużej depresji metaanaliza 35 badań wykazała łączny odsetek nawrotów 34,8% po sześciu miesiącach — około 65% osób pozostało bez nawrotu. To ogromny odcinek stabilności.';

  @override
  String get tcaMilestone365Title => 'Rok: większość pozostała bez nawrotu';

  @override
  String get tcaMilestone365Description =>
      'Wśród osób odstawiających leki przeciwdepresyjne po leczeniu dużej depresji metaanaliza 35 badań wykazała łączny odsetek nawrotów 45,12% po 12 miesiącach — około 55% pozostało bez nawrotu przez pełny rok. To ważny kamień milowy długoterminowej stabilności.';

