  @override
  String get maoiMilestone3Title =>
      'Dzień 3: Najwyższa faza ryzyka w zakresie nadzoru medycznego';

  @override
  String get maoiMilestone3Description =>
      'IMAO niesie ze sobą najpoważniejsze ryzyko przerwania stosowania leków przeciwdepresyjnych. Nagłe zaprzestanie leczenia szczególnie fenelzyną i tranylcyprominą może spowodować ciężkie pobudzenie, splątanie, omamy, mioklony i hipertermia. W przypadku wystąpienia tych objawów, należy natychmiast zwrócić się o pomoc medyczną. IMAO pracy poprzez trwale unieszkodliwiające enzymy MAO; regeneracja wymaga, aby organizm syntetyzował nowe enzymy, proces trwa około 14 dni.';

  @override
  String get maoiMilestone7Title =>
      'Jeden tydzień: MAO Synteza enzymy w trakcie';

  @override
  String get maoiMilestone7Description =>
      'IMAO trwale niszczyć enzymy MAO; odzysk wymaga syntezy całkowicie nowego enzymu. w ciągu jednego tygodnia, około 50% normalnej aktywności MAO może odzyskać. Ciężkie objawy ostrego zaprzestania majaczenia, mioklony, hipertermia) są znacznie zredukowane. Ścisły nadzór medyczny pozostaje ważne.';

  @override
  String get maoiMilestone14Title =>
      'Dwa tygodnie: aktywność enzymu MAO znacząco odzyskana';

  @override
  String get maoiMilestone14Description =>
      'Dwa tygodnie to standardowy okres kliniczny dla regeneracji enzymu MAO po przerwaniu leczenia. W przybliżeniu do dnia 14. aktywność MAOA i MAO- B jest w dużej mierze przywrócona i prawidłowy metabolizm tyraminy jest przywrócony. Ograniczenia dietetyczne wymagane podczas leczenia MAOI mogą być zwykle zrelaksowane w porozumieniu z lekarzem.';

  @override
  String get maoiMilestone30Title =>
      'Jeden miesiąc: Brain – Chemical Systems Rebalansowanie';

  @override
  String get maoiMilestone30Description =>
      'Miesiąc po zaprzestaniu stosowania IMAO enzym IMAO jest aktywny, a mózg radzi sobie z serotoniną, noradrenaliną, dopaminą i tyraminą naturalną. specjalny okres interakcji pokarmowej i narkotykowej został zakończony, choć nadal należy powiedzieć lekarzom przepisującym wcześniej IMAO.';

  @override
  String get maoiMilestone90Title =>
      'Trzy miesiące: Normalizacja chemii mózgowej';

  @override
  String get maoiMilestone90Description =>
      'Trzy miesiące daje nastrojów mózgowych i systemów energetycznych znaczny czas na przeczytanie zaraz po MAOIS. Mood. energia, i jasne myślenie stabilizują się, gdy mózg radzi sobie z tymi chemikaliami naturalnie ponownie.';

  @override
  String get maoiMilestone180Title =>
      'Sześć miesięcy: Długoterminowe odzyskiwanie';

  @override
  String get maoiMilestone180Description =>
      'Sześć miesięcy stanowi istotny okres naturalnej funkcji monoamin. Serotonina, norepinefryna, i receptory dopaminy populacje są normalizowane. Fenetyloaminy PEA) szlaki również dotknięte przez IMAO powróciły do naturalnych poziomów, co często pomija aspekt regeneracji, który przyczynia się do normalizacji emocjonalnej.';

  @override
  String get maoiMilestone365Title => 'Jeden rok: Odzyskiwanie osiągnięte';

  @override
  String get maoiMilestone365Description =>
      'Rok po zatrzymaniu IMAO daje mózgowi i organizmowi pełny rok bez narkotyku. Mood. energiczny, jasne myślenie, i normalna regulacja mózg – chemiczna miały znaczny czas, aby uregulować i odzyskać.';

