  @override
  String get adderallReferenceDay1 =>
      'Amphetamina Withdrawal: Co się dzieje wcześnie\n\nŹródło: MedlinePlus (U.S. National Library of Medicine)\n\nCo to są amfetaminy?\nAmfetaminy są lekami pobudzającymi, które obejmują zarówno nielegalne substancje, takie jak prędkość ulicy ) i leki na receptę stosowane w leczeniu ADHD i narkolepsja takich jak Adderall i VyvanseZGEND. One gwałtownie zwiększyć dopaminy i noradrenaliny, które mogą tworzyć intensywne skoncentrowanie, energiczny, i euforia. Z regularnym, intensywnym użyciem, mózg dostosowuje się do tych powtarzających się operacji, więc zatrzymanie może zostawić mood, energia, i motywacja tymczasowo niskie.\n\nCzęsto Objawy odstawienne\nMedlinePlus podaje je jako typowe w przypadku zaprzestania zażywania amfetamin:\n• Silne pragnienie narkotyku\n• Huśtawki nastrojów od depresji do pobudzenia do lęku\n• Uczucie zmęczenia przez cały dzień\n• Nie można się skoncentrować\n• Omamy, widzenie lub słyszenie rzeczy, które nie istnieją )\n• Reakcje fizyczne, takie jak ból głowy, ból i ból brzucha, zwiększona apetyt, i nie śpi dobrze\n\nCzy wycofanie jest niebezpieczne?\nMedlinePlus nie opisuje wycofywania amfetaminy jako niebezpiecznej medycznie w sobie, ale zauważa, że poważne objawy mogą wymagać żywej w programie leczenia, oraz że nastrój i problemy emocjonalne związane z zażywaniem amfetaminy, w tym depresja, mogą być poważne i wymagają wsparcia.\n\nUzyskanie pomocy\nMedlinePlus doradza skontaktować się z lekarzem, jeśli ty lub ktoś, kogo znasz jest uzależniony od amfetaminy i potrzebuje pomocy, aby przestać używać. Jeśli masz myśli o samoszkodliwości, kieruje czytelników do kryzysowych zasobów, takich jak 988 lub 911.';

  @override
  String get adderallReferenceDay3 =>
      'Zarządzanie wycofaniem amfetaminy: dzień 3\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nGdzie jest 3 – go dnia\nW wytycznych WHO stwierdza się, że objawy odstawienia stymulantów zaczynają się w ciągu 24 godzin od ostatniego zastosowania stymulantów i trwają 3 dni. Dzień trzeci jest zaledwie wewnątrz tej ostrej fazy zazwyczaj wśród najtrudniejszych dni, zanim objawy zaczynają się ustawiać.\n\nObjawy\nW przypadku środków pobudzających o typie amfetaminy wytyczne zawierają listę:\n• Agitacja i drażliwość\n• Depresja\n• Zwiększone zasypianie i apetyt\n• Bóle mięśni\nU pacjentów ciężkich mogą wystąpić również objawy psychotyczne, takie jak paranoja, zaburzenia myślenia lub halucynacje.\n\nGłównie psychologiczne wyzwanie\nW przeciwieństwie do alkoholu lub opioidów z drawal. pobudzające wycofanie nie powoduje wymiotów, drżenia, lub drgawki. dominującą trudnością jest psychologiczna domina, utrata przyjemności, i pragnienie napędzane przez umysł pozbawiony dopaminy.\n\nPodejście do zarządzania\nWytyczne WHO zalecają opiekę wspomagającą:\n• Picie co najmniej 2 litrów wody dziennie\n• Suplementy wielowitaminowe z witaminami grupy B i witaminą C\n• Objawowe leki przeciwbólowe i lękowe\n• W przypadku ciężkiej agitacji, najpierw strategie behawioralne, z sedacją diazepamu tylko w razie potrzeby\n\nPoza fazą ostrą\nWytyczne mówią, że najcięższe wycofanie trwa tylko kilka dni, po czym następuje łagodniejszy okres regeneracji, który może trwać od jednego do dwóch miesięcy.';

  @override
  String get adderallReferenceDay7 =>
      'Tydzień bez AdderallZ: Najgorszy przechodzi\n\nŹródło: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), on PubMed Central\n\nRozwiązania dotyczące ostrej fazy\nPrzegląd ten opisuje psychostymulanty wycofania w fazach. W ostrym fazie, objawy szczytowe szczytowe po pierwszych 2 – dniowych 3 dni.Is i poważne dyskomfort z tych objawów zwykle ustępuje w ciągu 4 – 7 dni.Is Do końca pierwszego tygodnia, najtrudniejsza część katastrofy jest za większością ludzi energia i apetyt zaczynają stabilizować, a sen zaczyna regulować.\n\nCo będzie dalej\nW siódmym dniu rekonwalescencja jest już bardzo niska.\n\nCo jeszcze jest obecne w dniu 7\nObjawy psychologiczne zwykle przewyższają fizyczne:\n• Niska motywacja i utrata przyjemności\n• Trudności z koncentracją\n• Nastrój, który jest nadal poniżej normy\nOdzwierciedlają one układ dopaminy, który przywraca prawidłową, tymczasową część odzysku.\n\nSygnał odzyskiwania\nŻaden z leków zatwierdzonych przez FDA nie leczy stymulantów z drawal. więc opieka wspomagająca, struktura, senność, odżywianie i wsparcie psychologiczne są przez ten etap.';

  @override
  String get adderallReferenceDay14 =>
      'Dwa tygodnie przed AdderallZ: Do fazy Dłuższego Odzyskiwania\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nPrzeszłość fazy ostrej\nWHO stawia najcięższe pobudzające wycofanie na około trzy do pięciu dni, następnie łagodniejszy okres regeneracji trwający około jednego do dwóch miesięcy. W dwa tygodnie, katastrofa jest dobrze za tobą.\n\nJak wygląda dłuższa faza odzyskiwania\nCiężkie senność, pobudzenie i bóle mięśni w dużej mierze się zagoiły. Co pozostaje zwykle łagodniejsze: niski lub zmieniający się nastrój, zmniejszona motywacja, i ciągłe pragnienie, jak system nagród mózgów wraca.\n\nSen i przekąski\nZwiększony sen i apetyt fazy ostrej są normalizujące. Jak sen stałe, nastrojenie, koncentracja, i energia mają tendencję do naśladowania.\n\nRyzyko nawrotu choroby i ADHD\nJest to nadal okres podwyższonego ryzyka, zwłaszcza jeśli objawy ADHD są związane z powrotem bez leczenia. Wytyczne WHO podkreślają wsparcie psychologiczne i umiejętności prewencyjne; dla osób, które przyjęły Adderall dla ADHDZ, jest to dobry czas na przedyskutowanie strategii niestymulujących lub alternatywy z lekarzem.';

  @override
  String get adderallReferenceDay30 =>
      'Jeden miesiąc AdderallZZ: Większość objawów za tobą\n\nŹródło: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), on PubMed Central\n\nGdzie jest jeden miesiąc\nW przeglądzie stwierdzono, że większość objawów odstawiennych zanikają w ciągu pierwszych dwóch do trzech tygodń. do 30 dni, większość z nich złagodziły i nastrój i motywacja są zazwyczaj znacznie lepsze niż w pierwszym tygodniu.\n\nFaza regeneracji późniejszej\nOd jednego do sześciu miesięcy, zapamiętywanie, planowanie, skupienie się i podejmowanie decyzji nadal się poprawia. W ciągu jednego miesiąca, katastrofa jest skończona i te zyski są już w toku.\n\nNastroje i motywacja\nGłęboka utrata przyjemności z wypadku w dużej mierze zniesiona do teraz. Działania, które czuły się bezradne w pierwszym tygodniu zaczynają czuć się satysfakcjonujące ponownie, jak naturalne sygnalizacja dopaminy odzyskuje.\n\nDla osób z ADHD\nJeśli Adderall został przepisany dla ADHDZ, objawy mogą być bardziej widoczne teraz. Praca z lekarzem na strategii niestymulujących lub alternatywy jest ważne w tym etapie.';

  @override
  String get adderallReferenceDay60 =>
      'Dwa miesiące przed AdderallZ: Dłuższa faza odzyskiwania wiał w dół\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nGdzie są dwa miesiące.\nWHO opisuje łagodniejszy okres rekonwalescencji, trwający około jednego do dwóch miesięcy po początkowym okresie. Po 60 dniach, jesteś na końcu tego okna i utrzymujące się objawy są w dużej mierze rozwiązujące.\n\nCo poprawia\nAgitacja, depresja, zaburzenia snu i apetyt, lista wytycznych dotyczących pobudzającego wycofywania, dla większości osób, ustaliła się w sposób zasadniczy:\n• Zwykły nastrój jest bardziej stabilny, z mniejszą ilością huśtawek wczesnego powrotu do zdrowia\n• Sen i apetyt znormalizowały się\n• System nagradzania bardziej łatwo reaguje na codzienne przyjemności foodfoods, exercise, connection\n\nSygnał odzyskiwania\nWyższe dawki i dłuższe stosowanie mogą spowodować, że powrót do zdrowia będzie trwał dłużej, podczas gdy abstynent będzie się dobrze bawił, motywował i jasno myślał, poruszając się w kierunku normy w ciągu następnych miesięcy.\n\nZdrowie fizyczne\nEfekt pobudzający na tętnicę, apetyt i łatwość ważenia, gdy lek ustępuje z codziennego życia, i układu sercowo – naczyniowego ze stosowania stymulantów jest zwalczany.';

  @override
  String get adderallReferenceDay90 =>
      'Trzy miesiące Off AdderallZ: Przez najgorsze, wciąż uzdrawiając\n\nŹródło: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), on PubMed Central\n\nGdzie 90 Dni\nW ciągu trzech miesięcy wczesne objawy już dawno minęły, podczas gdy zapamiętywano, planowano, skupiano się, podejmowano decyzje, a system nagród nadal się poprawia.\n\nMyślenie i pamięć Rekonwalescencja\nW przeglądzie stwierdzono, że zapamiętywanie, planowanie, koncentrowanie się i podejmowanie decyzji dotyczących ryzyka może być w dalszym ciągu ulepszane w miesiącach. W 90 dni koncentracja i pamięć nadal poruszają się we właściwym kierunku z ciągłym abstynencją.\n\nDlaczego to okno wciąż ma znaczenie\nŻaden lek zatwierdzony przez FDA nie jest specjalnie ukierunkowany na pobudzanie do rozwoju, więc struktura, terapia, ćwiczenia, sen i wsparcie są narzędziami, które przenoszą ożywienie poprzez ten faz. budowanie tych nawyków teraz jest tym, co prowadzi do ożywienia.\n\nWiększy obraz\nTrzy miesiące to prawdziwe osiągnięcie, które zapewnia, że najcięższe fizyczne i emocjonalne rozciągnięcia są za tobą, a trajektoria stąd, z ciągłym abstynencją, jest jedną z stałych ulepszeń.';

  @override
  String get adderallReferenceDay180 =>
      'Sześć miesięcy Off AdderallZZ: Dobrze za trudną część\n\nŹródło: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nCo StatPearls mówi o stymulantach\nTo kliniczne odniesienie opisuje ożywienie bodźców jako katastrofę, a następnie stopniowej poprawy. Wspólne problemy obejmują depresję, spanie dużo, zwiększony głód, niski nastrój, i wolniejsze ruchy i myśli. Depresja może trwać kilka tygodni, z łagodniejszym ożywienie nadal poza tym.\n\nGdzie siedzi sześć miesięcy\nPo sześciu miesiącach jesteś daleko po obu ostrych okresie i separal- tygodni depresji fazy StatPearls opisuje. Powolne ożywienie odnosi się do miał znaczny czas na postęp, a dla większości ludzi zwykle moode, snu, apetyt, i motywacja są stałe i niezawodne do teraz.\n\nSygnał odzyskiwania\nStatPearls opisuje stopniową rekonwalescencję po początkowym tygodniu. Przez sześć miesięcy, ostra katastrofa i separatywna faza depresyjna są daleko za tobą, z stabilnym nastroju, snu, apetytu i motywacji teraz dominujący wzór.\n\nZwiązek z ADHD\nDla osób, które przyjmowały Adderall dla ADHDZ, sześć miesięcy abstynencji jest dobrym punktem dla jasnomyślnej oceny z lekarzem aktualnych objawów i czy nie – stymulant zbliża się do wykonywania, snu, struktury, terapeuty, lub leki alternatywne są spełnione potrzeby.';

  @override
  String get adderallReferenceDay365 =>
      'Jeden rok Off AdderallZZ: Znaczne Recovery, Szczerze Oprawione\n\nŹródło: Berman et al., \"Potential Adverse Effects of Amphetamine Treatment on Brain and Behavior: A Review,\" Molecular Psychiatry (2008), on PubMed Central\n\nO tym przeglądzie\nPrzegląd ten pokazuje, jak wysokie dawki lub długotrwałe narażenie na amfetaminę może wpłynąć na mózg i dokumenty mierzalne ożywienie podczas abstynencji.\n\nCo mówi o regeneracji?\nW przeglądzie udokumentowano poprawę przepływu krwi w mózgu i w białkach, które po długotrwałym abstynencji przetwarzają dopaminę. Niektóre obszary mózgu odzyskują szybciej niż inne, ale ogólny kierunek jest jasny: mózg leczy się po przerwaniu stosowania.\n\nDługoterminowy zwrot\nW dokumentach z przeglądu mierzalne odzyskanie przepływu krwi mózgowej i recyklingu dopaminy po długotrwałym abstynencji. W jednym roku, te systemy mózgowe miały cały rok na przebudowę.\n\nCo to oznacza w ciągu jednego roku?\nDla większości osób szczególnie tych, którzy przyjęli Adderall w przepisanych dawkach na rok przerwy oznacza nagrodzenie, uwagę, i systemy motywacyjne działają dobrze dzień po dniu. Cięższe lub dłuższe stosowanie może zająć więcej czasu, ale kontynuację. ryzyko nawrotu jest znacznie niższe niż we wczesnym odzyskiwaniu.';

  @override
  String get alcoholReferenceDay1 =>
      'Co się dzieje z twoim snem, kiedy przestajesz pić?\n\nŹródło: \"Alcohol and the Sleeping Brain\" (Colrain, Nicholas & Baker), Handbook of Clinical Neurology — peer-reviewed, NIH-hosted\n\nArchitektura alkoholowa i senna\nAlkohol jest sedating, więc skraca czas, który trwa, aby zasnąć i zwiększa głęboką powolną falę snu w pierwszej połowie nocy. Ale to przychodzi na koszt: alkohol tłumi REM przyspieszone ruchu oka ) sen w fazie regeneracyjnej związane z konsolidacją pamięci i emocjonalnej regulacji i fragmenty spać w drugiej połowie nocy, jak jest metabolizowany.\n\nPierwsza noc bez alkoholu\nPonieważ alkohol tłumi sen REM, pierwsze noce bez niego często przynoszą rebound REM: żywe sny i lekki, złamany sen podczas normalnego snu powrót. Jest to normalna, tymczasowa część odzyskiwania.\n\nOdzyskiwanie rozpoczyna się\nW miarę jak mózg ponownie się dostosowuje w ciągu następnych dni i tygodni, REM i ogólna jakość snu poprawia. Zaburzenia snu jest jednym z najbardziej uporczywych objawów związanych z drawall, ale tendencja do normalnego z trwałym abstynencji.\n\nNotatka na temat ciężkiego picia\nW przypadku ciężkich lub długotrwałych napojów dziennych, pierwsze 24 godziny mogą również przynieść objawy odstawiennicze, uczucie zmęczenia, drżenie, nużące. Ciężkie odstawienie może być niebezpieczne, jeśli byłeś pił intensywnie każdego dnia, należy porozmawiać z lekarzem przed zaprzestaniem abstynencji.';

  @override
  String get alcoholReferenceDay3 =>
      'Dzień trzeci: Okno szczytu odstawienia\n\nŹródło: \"Alcohol Withdrawal\", StatPearls — recenzowane, NIH National Library of Medicine\n\nOkoło 72 godzin\nObjawy odstawienia alkoholu mogą rozpocząć się w ciągu kilku godzin i często osiągają szczyt około 72. godziny. StatPearls wymienia drżenie, bezsenność, pobudzenie, poty, wysokie ciśnienie, szybkie tętno i napady drgawkowe jako oznaki tego stanu nadmiernego pobudzenia.\n\nTrzy mocne dni\nDotarcie do 72 godzin to ogromny kamień milowy, bo wypada dokładnie w udokumentowanym oknie szczytu wielu ostrych objawów.\n\nCiężkie odstawienie może pojawić się później\nMajaczenie alkoholowe (delirium tremens) może wystąpić 3–8 dni po odstawieniu i może być śmiertelne. Ciężkie odstawienie jest stanem nagłym. Osoby pijące dużo codziennie oraz osoby z wcześniejszymi napadami drgawkowymi lub majaczeniem odstawiennym powinny zasięgnąć porady medycznej zamiast nagle odstawiać alkohol bez wsparcia.';

  @override
  String get alcoholReferenceDay7 =>
      'Jak układ immunologiczny odzyskuje\n\nŹródło: \"Alcohol and the Immune System\" (Sarkar, Jung & Wang), Alcohol Research: Current Reviews — peer-reviewed, NIH-hosted\n\nJak alkohol osłabia odporność\nAlkohol osłabia układ odpornościowy na kilka sposobów. Nawet jedna ciężka sesja alkoholowa może zmniejszyć zdolność do walki z infekcjami do 24 godzin. Długotrwałe stosowanie zmniejsza liczbę białych krwinek, zakłóca sygnały immunologiczne, a uszkodzenia jelit i płuc obronność, zwiększając ryzyko zakażeń i powolne gojenie ran.\n\nUsuwanie obrażeń\nWiele z tych efektów poprawia się po odejściu alkoholu. Białe krwinki i sygnalizacja immunologiczna zaczynają odzyskiwać się, podczas gdy jelita i drogi oddechowe zaczynają naprawiać. W pierwszym tygodniu, twój układ odpornościowy nie jest już powalony codziennie i odporność na częste zakażenia zaczyna się poprawiać.\n\nProces stopniowy\nPełna regeneracja immunologiczna trwa dłużej niż tydzień, a stopień naprawy zależy od tego, jak ciężkie i długotrwałe było picie alkoholu, ale pierwszy tydzień bez alkoholu jest tam, gdzie zaczyna się odbudowa.';

  @override
  String get alcoholReferenceDay14 =>
      'Wczesna regeneracja mózgu w abstynencji\n\nŹródło: Bartsch AJ et al., \"Manifestations of early brain recovery associated with abstinence from alcoholism,\" Brain (2007) — peer-reviewed\n\nPomiar odzysku\nW badaniu tym zastosowano rezonans magnetyczny do obserwacji osób niedawno detoksykowanych z uzależnieniem od alkoholu przez pierwsze tygodnie abstynencji, porównując je ze zdrowymi kontrolami.\n\nObjętość mózgu\nPrzewlekłe spożywanie alkoholu zmniejsza mózg częściowo poprzez odwracalne zmniejszenie wielkości komórek, nie tylko stałe. Z abstynencji, badacze mierzą średni globalny przyrost objętości mózgu o prawie 2%, skoncentrowany wokół móżdżku, mózgu, komór i przednich regionów. Większość z tej regrinth dzieje się naprawdę, w ciągu pierwszych kilku tygodni po alkoholu.\n\nCerebellum i uwaga\nOdnowa była szczególnie wyraźna w obszarach mózgu używanych do poruszania się i uwagi. Marker zdrowia komórek mózgowych wzrosła wraz z wymierną poprawę uwagi, więc uzdrowienie fizyczne przyszedł z realnych korzyści w myśleniu.\n\nZałożenie, nie koniec\nWyższe funkcje, takie jak złożone rozumowanie, są stopniowo odzyskiwane, ale pierwsze dwa tygodnie stanowią, że mózg szybko się goi po usunięciu alkoholu.';

  @override
  String get alcoholReferenceDay30 =>
      'Ciśnienie krwi spada, gdy wycinasz alkohol\n\nŹródło: Roerecke et al., \"The effect of a reduction in alcohol consumption on blood pressure: a systematic review and meta-analysis,\" Lancet Public Health (2017) — peer-reviewed\n\nDowody\nTa metaanaliza zebrała 36 randomizowanych badań na około 2865 uczestników ) testujących, co dzieje się z ciśnieniem krwi, gdy ludzie piją mniej.\n\nJak duża jest ta effectowa?\nLudzie, którzy pili dwa lub mniej napojów dziennie nie zauważyli znaczącej zmiany ciśnienia krwi od cięcia tylko. powyżej tego młódka, efekt był zależny od dawki: był najsilniejszy u osób pijących sześć lub więcej napojów na dobę, którzy obcięli spożycie o około połowę, gdzie skurczowe ciśnienie krwi spadła o około 5,5 mmHg i rozkurczowe o około 4,0 mmHg średnio. Zmniejszenie tego rozmiaru jest klinicznie znaczące porównywalny z niektórymi lekami ciśnienia krwi i wystarczająco do zmniejszenia długotrwałego udaru i ryzyka choroby serca.\n\nDlaczego jeden miesiąc ma znaczenie\nAlkohol podnosi ciśnienie krwi poprzez aktywację reakcji na stres, zwiększenie kortyzolu i usztywnienia naczyń krwionośnych. Badania w tej recenzji pokazują korzyści pojawiają się w ciągu tygodni trwałego zmniejszenia, więc o około miesiąc abstynencji, cięższe ciśnienie krwi pijące miał czas, aby ustatkować się w kierunku zdrowszego poziomu.\n\nEfekt progowy\nPrzegląd znalazł jasny młód: korzyść była skoncentrowana w ludziach pijących więcej niż dwa napoje dziennie, i rosły stopniowo większe wcześniejsze picie. Jeśli byłeś lżejszy pijąc, nie oczekuj tego specyficznego ciśnienia krwi korzyści, ale cięższe pijących uzyskać really, mierzalne sercowo – naczyniowe wypłata z zatrzymania.';

  @override
  String get alcoholReferenceDay60 =>
      'Odzyskiwanie wątroby po zakończeniu picia\n\nŹródło: National Institute on Alcohol Abuse and Alcoholism (NIAAA), \"Alcohol\'s Effects on the Body\"\n\nJak alkohol niszczy wątrobę\nWątroba przetwarza większość alkoholu, który pijesz, i zajmuje otarcie się z niwe. NiAAA opisuje postęp alkoholowej związanej z wątrobą: zaczyna się od tłuszcz stłuszczenie wątroby nagromadzenie tkanki tłuszczowej w komórkach wątroby, może przejść do alkoholowego zapalenia wątroby i przedłużonego intensywnego stosowania do zwłóknienia i marskość wątroby bliznowacenie.\n\nWcześniejsze etapy są odwracalne.\nKluczową kwestią jest to, że wątroba jest bardzo regenerowalny, a wczesne etapy tego uszkodzenia mogą poprawić się po spożyciu. Grubość wątroby, zwłaszcza często ustępuje z trwałym abstynencji. W ciągu około dwóch miesięcy bez alkoholu, wątroba miała prawdziwy czas na oczyszczenie tłuszczów, spokojne zapalenie, i przywrócić zdrowsze funkcje zazwyczaj odzwierciedlone w spadku poziomu enzymów wątrobowych ALT i ASTIONT.\n\nPoza wątrobą\nNIAAA zauważa, że alkohol również szczepi serce, trzustkę i układ odpornościowy. Dając organizmowi trwałe przerwy od alkoholu pozwala te systemy odzyskać zbyt dużo przyczyniając się do twardszej energii i lepszego ogólnego zdrowia wielu ludzi zauważyć w tym etapie.';

  @override
  String get alcoholReferenceDay90 =>
      'Myślenie i pamięć po trzech miesiącach trzeźwości\n\nŹródło: Systematic review of neuropsychological recovery following abstinence from alcohol (PubMed Central, 2024) — peer-reviewed\n\nCo dowód pokazuje\nTa recenzja połączone badania, które śledziły, jak myślenie i pamięć odzyskać po ludzie przestać pić. Większość umiejętności poruszać się w kierunku normalnej w ciągu około sześciu do dwunastu miesięcy, a niektóre poprawić wcześniej.\n\nCo poprawia pierwszy\nDwie specyficzne umiejętności wyróżniają się jako odzyskiwanie wcześniej niż reszta: podstawowa szybkość przetwarzania w przeglądzie okazało się, że zazwyczaj odzyskuje się o około jeden miesiąc, choć dokładność na bardziej złożonych zadań pozostaje w tyle ) i aktualizacji pamięci pracy. Przez około trzymiesięczny marker, wiele osób już zauważyć te ożywienie.\n\nCo trwa dłużej?\nUwaga, planowanie, podejmowanie decyzji, kontrolowanie impulsów, postrzeganie i pamięć poprawiają się w ciągu 6 do 12 miesięcy.\n\nCo wpływa na odzyskanie\nW przeglądzie stwierdza się, że odzyskiwanie jest kształtowane przez takie czynniki jak wiek, stan palenia i premorbiczne zdolności, ale, co ciekawe, nie konsekwentnie przez całkowitą kwotę wcześniej pijany. Odzysk jest oczekiwanym trajektorii.\n\nDlaczego to ma znaczenie?\nCzystsze myślenie jest praktyczne: lepsza uwaga i podejmowanie decyzji pomaga ludziom pozostać w leczeniu i unikać nawrotów.';

  @override
  String get alcoholReferenceDay180 =>
      'Odzyskiwanie mózgu w 6 miesiącach Sobriety\n\nŹródło: Peer-reviewed review of structural and functional brain recovery during abstinence from substance use (PubMed Central)\n\nOdzyskiwanie utrzymuje się\nWczesny powrót objętości mózgu w pierwszych tygodniach jest dopiero początkiem. Ten przegląd dokumentuje, że z trwałą abstynencją mózg nadal odzyskuje strukturalnie i funkcjonalnie szarą materię odzyskuje i uszkodzone szlaki materii białej, które koordynują komunikację między regionami mózgu naprawy przez miesiące.\n\nFront mózgu\nOdzyskiwanie jest szczególnie ważne w przedniej części mózgu, który obsługuje osądy, planowanie, i samokontroli. Jak to leczy, podejmowania decyzji i kontroli impulsowej wzmocnienie.\n\nPrzeokablowanie mózgu i funkcja\nOprócz naprawy fizycznej, funkcje mózgu i połączeń również odzyskać. Mózg może ponownie okablować i ponownie się, co sprawia, że długotrwała abstynencja potężny czas na terapię i nowe mieszkańców.\n\nSygnał odzyskiwania\nPrzez sześć miesięcy, struktura mózgu i funkcje wyraźnie poruszają się w kierunku zdrowszej normy. Staying abstynent daje, że rekonwalescencja więcej czasu na budowę.';

  @override
  String get alcoholReferenceDay365 =>
      'Alkohol, ryzyko zachorowania na raka i zatrzymanie\n\nŹródło: National Cancer Institute (NCI), \"Alcohol and Cancer Risk\"\n\nAlkohol Powoduje raka\nNCI stwierdza, że istnieje silny konsensus naukowy, że picie alkoholu może powodować raka. Alkohol jest związany z nowotworami jamy ustnej jamistość gardła, krtani throathroathoats, krtani głos boxtagon, przełyk, wątroba, piersi, i jelita grubego i odbytnicy. Im więcej osoba pije i dłużej pić tym wyższe ryzyko.\n\nJak alkohol napędza raka\nMechanizmy obejmują aldehyd octowy, toksyczny produkt rozpadu alkoholu, który niszczy DNA; stres oksydacyjny i zapalenie; zaburzenie wchłaniania ochronnych składników odżywczych; oraz, w przypadku raka piersi, podwyższony poziom estrogenów.\n\nRyzyko spada po zatrzymaniu\nCo istotne, NCI donosi, że rzucenie picia wiąże się z niższym ryzykiem z upływem czasu badania wskazują na zwiększone ryzyko raka jamy ustnej i przełyku zmniejsza się po zatrzymaniu, choć może to trwać lata, aby zbliżyć się do ryzyka kogoś, kto nigdy nie wysycha. Jeden rok alkoholu jest znaczący krok na tej ścieżce.\n\nSkładanie korzyści\nOsiągnięcie roku również blokuje się w sercowo – naczyniowych i wątrobowych przyrost abstynencji wstrzemięźliwość ciśnienie krwi, zmniejszona arytmia ryzyka, i dalsze gojenie wątroby wraz z upadku ryzyka raka.';

  @override
  String get benzodiazepineReferenceDay7 =>
      'Odstawienie benzodiazepin: pierwszy tydzień\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings\", Światowa Organizacja Zdrowia (2009), NCBI Bookshelf\n\nBezpieczeństwo przede wszystkim\nOdstawienie benzodiazepin może wywołać napady drgawkowe. WHO wskazuje, że najbezpieczniejsze postępowanie polega na stopniowym zmniejszaniu dawki benzodiazepiny; łagodzi to objawy odstawienne i pomaga zapobiegać napadom. Po długotrwałym stosowaniu nie odstawiaj leku nagle — zmniejszaj dawkę z pomocą personelu medycznego.\n\nKiedy zaczyna się odstawienie\nWedług WHO czas zależy od długości działania leku:\n• Krótko działające (oxazepam, alprazolam, temazepam): zwykle 1–2 dni po ostatniej dawce, przez 2–4 tygodnie lub dłużej\n• Długo działające (diazepam, nitrazepam): zwykle 2–7 dni po ostatniej dawce, przez 2–8 tygodni lub dłużej\nPierwszy tydzień obejmuje typowe okno początku objawów także dla długo działających benzodiazepin.\n\nJak mogą wyglądać objawy\nWHO wymienia lęk, bezsenność, niepokój ruchowy, pobudzenie lub drażliwość, problemy z koncentracją lub pamięcią oraz napięcie lub bóle mięśni.\n\nMonitorowanie\nNasilenie objawów może znacznie się wahać. WHO zaleca regularne monitorowanie objawów i powikłań; w protokole dla placówek zamkniętych personel rozmawia z pacjentem co 3–4 godziny, uspokaja go i w razie potrzeby wyjaśnia objawy.';

  @override
  String get benzodiazepineReferenceDay14 =>
      'Odstawienie benzodiazepin: dwa tygodnie\n\nŹródło: Poyares i wsp., \"Chronic benzodiazepine usage and withdrawal in insomnia patients\", Journal of Psychiatric Research (2004), PubMed\n\nRzeczywisty sygnał poprawy po około dwóch tygodniach\nBadacze obserwowali osoby z przewlekłą bezsennością, które przez lata przyjmowały benzodiazepiny każdej nocy, i ponownie zbadali ich sen 15 dni po stopniowym odstawieniu. W porównaniu z okresem przewlekłego stosowania benzodiazepin poprawiły się sen wolnofalowy, aktywność delta w EEG snu oraz zgłaszana jakość snu.\n\nGłęboki sen wraca\nSen wolnofalowy jest najgłębszym etapem snu NREM. Do 15. dnia zwiększyły się sen wolnofalowy i aktywność delta, a sen NREM w stadium 2 zmniejszył się w kierunku wzorca obserwowanego u zdrowych osób z grupy kontrolnej.\n\nWczesna poprawa potwierdzona pomiarem\nU uczestników, którzy ukończyli odstawianie, sen pogorszył się bezpośrednio po odstawieniu, ale do kontroli w 15. dniu poprawiły się obiektywne wskaźniki głębokiego snu i zgłaszana jakość snu. Dzięki temu dwa tygodnie są rzeczywistym, zmierzonym kamieniem milowym regeneracji.';

  @override
  String get benzodiazepineReferenceDay60 =>
      'Benzodiazepiny: funkcjonowanie w dzień po ośmiu tygodniach\n\nŹródło: Tsunoda i wsp., \"Effects of discontinuing benzodiazepine-derivative hypnotics on postural sway and cognitive functions in the elderly\", International Journal of Geriatric Psychiatry (2010), PubMed\n\nMierzalny sygnał poprawy po ośmiu tygodniach\nBadacze obserwowali dorosłych w wieku 60 lat i starszych mieszkających w domu opieki, którzy stosowali nasenne benzodiazepiny. Dawki stopniowo zmniejszano do odstawienia przez trzy tygodnie, a pod koniec ósmego tygodnia ponownie wykonano testy poznawcze i równowagi.\n\nSkupienie i pamięć poszły w górę\nWśród 26 osób, które ukończyły badanie, istotnie poprawiły się wyniki pamięci bezpośredniej, uwagi i języka. To konkretne, zmierzone korzyści w funkcjonowaniu dziennym po odstawieniu benzodiazepin.\n\nPewniej na nogach\nIstotnie poprawiły się też pomiary wychyleń postawy przy zamkniętych oczach. Autorzy uznali, że odstawienie nasennych benzodiazepin w tej starszej grupie wiązało się z lepszą stabilnością ciała i poprawą dziennych funkcji poznawczych.\n\nSen pozostał stabilny\nOsoby, które ukończyły badanie, nie zgłaszały subiektywnego pogorszenia snu w zastosowanym kwestionariuszu. W ósmym tygodniu badanie wykazało mierzalne korzyści w ciągu dnia bez zgłaszanego pogorszenia jakości snu.';

  @override
  String get benzodiazepineReferenceDay90 =>
      'Trzy miesiące po benzodiazepinach: szybsze myślenie, mniej sedacji\n\nŹródło: Rickels et al., \"Psychomotor performance of long-term benzodiazepine users before, during, and after benzodiazepine discontinuation,\" Journal of Clinical Psychopharmacology (1999), on PubMed\n\nMierzalny sygnał poprawy po 12 tygodniach\nBadacze testowali osoby długotrwale stosujące benzodiazepiny przed stopniowym odstawianiem oraz 5 i 12 tygodni później. Dane z 12. tygodnia były dostępne dla 77 osób, a u osób, które skutecznie odstawiły lek, brak benzodiazepin potwierdzano cotygodniowymi badaniami krwi.\n\nSzybsze wykonywanie zadań poznawczych\nOsoby, które skutecznie odstawiły benzodiazepiny, szybciej wykonywały zadania kopiowania symboli i zastępowania cyfr symbolami niż uczestnicy nadal przyjmujący benzodiazepiny. Różnica pozostawała istotna po uwzględnieniu wieku, wykształcenia i wyników wyjściowych.\n\nMniej sedacji psychicznej i fizycznej\nOsoby po skutecznym odstawieniu zgłaszały też mniejszą sedację psychiczną i fizyczną niż osoby nadal przyjmujące benzodiazepiny.\n\nJak mogą wyglądać trzy miesiące\nW tej grupie skutecznego odstawienia 12 tygodni po taperze odnotowano mierzalną poprawę szybkości przetwarzania i mniejszą sedację psychiczną oraz fizyczną. Myślenie było szybsze, a uczucie otępienia słabło.';

  @override
  String get benzodiazepineReferenceDay180 =>
      'Myślenie i pamięć w sześciu miesiącach: Wymierne korzyści\n\nŹródło: Tata et al., \"Lack of cognitive recovery following withdrawal from long-term benzodiazepine use,\" Psychological Medicine (1994), on PubMed\n\nCo badania zrobiły\nW badaniu tym zbadano 21 długoterminowych pacjentów z benzodiazepiną przed rozpoczęciem leczenia, tuż po zakończeniu leczenia, a następnie ponownie po sześciu miesiącach abstynencji, porównując je z dopasowanymi kontrolemi. jest to jeden z najbardziej znanych punktów w literaturze regeneracji benzo.\n\nCo znalazł\nPrzed zatrzymaniem pacjenci mieli problemy z nauką słowną, pamięcią, prędkością ruchu, koordynacją wizualną i uzasadnieniem wizualnym. Zaraz po zatrzymaniu nie było żadnych zmian.\n\nCo to oznacza?\nW ciągu sześciu miesięcy, słowne uczenie się, zapamiętywanie, szybkość ruchu i koordynacja wizualna były wymiernie odzyskiwalne. Poprawa była już jasne i miał miejsce.\n\nWiększy obraz\nJeśli czujesz się mglisty w sześciu miesiącach, to badania mówią: to jest oczekiwane, i ciągłość abstynencji jest ścieżką do. Długoterminowe badania pokazują, że rekonwalescencja trwa znacznie dalej niż ten punkt mózgu utrzymuje uzdrowienie.';

  @override
  String get benzodiazepineReferenceDay365 =>
      'Rok po benzodiazepinach: Myślenie i pamięć\n\nŹródło: Barker et al., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), on PubMed\n\nNajmocniejsze dowody jakie mamy\nNaukowcy połączyli badania, w których po co najmniej sześciu miesiącach leczenia ponownie badano długotrwałych użytkowników benzodiazepin. Połączony wynik pokazuje wyraźną regenerację myślenia i pamięci po drawalu.\n\nDobre wieści\nPołączone badania wykazały, że znaczna poprawa w kilku obszarach myślenia i pamięci po drawaniu. około jednego roku, ożywienie jest szerokie i oczywiste w porównaniu z aktywnym wykorzystaniem.\n\nKontynuacja odzyskiwania\nPołączone badania znalazły szerokie ożywienie w myśleniu i pamięci. W ciągu jednego roku, jesteś dobrze na trendzie ożywienia, który był już mierzalny w sześciu miesiącach.\n\nCo to oznacza w ciągu jednego roku?\nSpodziewaj się znacznego ożywienia w myśleniu, pamięci i jasności przez rok, większość ludzi czuje się znacznie ostrzejszy niż podczas użytkowania. Ale jeśli niektóre obszary nadal pozostaje, to jest zgodne z dowodami, a nie znak masz stalle. Recovery kontynuuje, a rok abstynencji jest głównym, wartym uwagi kamieniem milowym na tej drodze.';

  @override
  String get benzodiazepineReferenceDay540 =>
      '18 miesięcy po benzodiazepinach: powolne, ale prawdziwe ożywienie\n\nŹródło: Ashton, \"Protracted withdrawal syndromes from benzodiazepines,\" Journal of Substance Abuse Treatment (1991), on PubMed\n\nDlaczego Benzo Recovery trwa tak długo?\nBenzodiazepiny działają na GABA, główny system uspokajający mózg. długotrwałe stosowanie zmienia jak silnie, że system reaguje, a zmiany te mogą trwać miesiące, aby odwrócić. Dlatego benzo regeneracji mierzy się w miesiącach, a nie w tygodniu.\n\nGdzie jest 18 miesięcy.\nAshton opisuje długotrwałe objawy odstawienne, które mogą zająć miesiące. W ciągu 18 miesięcy, najgorsze jest znacznie za większością ludzi i utrzymujące się niepokój, zmiany sensoryczne i mgła mózgu mają znacznie się ustać. a co więcej, w ciągu 18 miesięcy, najgorzej jest w stosunku do większości ludzi, a utrzymujące się niepokój, zmiany sensoryczne i mgła mózgowe.\n\nPowoli odwracalne\nCo najważniejsze, Ashton określa zmiany leżące u podstaw tego procesu jako powoli odwracalne zmiany funkcjonalne w ośrodkowym systemie nerwowym.Slow, ale odwracalne zmiany w długim okresie czasu odzwierciedlają głębokość adaptacji benzodiazepin, a nie trwałe uszkodzenia u większości ludzi.\n\nSygnał odzyskiwania\nW ciągu 18 miesięcy, mózgi uspokajające system GABA miały długi czas na rozstrzygnięcie i dominującym kierunkiem jest kontynuowanie powrotu do normy.';

  @override
  String get benzodiazepineReferenceDay730 =>
      'Dwa lata po benzodiazepinach: Większość, Trwający postęp\n\nŹródło: Barker et al., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), on PubMed\n\nZnak orientacyjny w procesie odzyskiwania\nDwa lata to ważny kamień milowy, zwłaszcza po długim okresie z drawalem. Wczesne i utrzymujące się fazy objawowe są długie, a zyski z pierwszego roku miały kolejny rok na wzmocnienie.\n\nCo dowody wspierają\nPołączone badania pokazują poprawę w wielu obszarach po drawaniu. przez dwa lata, większość ludzi zgłaszają niepokój na lub poniżej poziomu przedbenzo, niezawodny sen bez leczenia, bardziej stabilne emocje i jaśniejsze myślenie niż podczas użytkowania.\n\nSygnał odzyskiwania\nPołączone badania wskazują na ożywienie wielu obszarów myślenia i pamięci. W ciągu dwóch lat, trwałe ożywienie jest dowodem potwierdzonym oczekiwaniami.\n\nUtrzymanie perspektywy\nDwa lata daje sen, nastrój, pamięć, i jasne myślenie długie okno rekonwalescencji. Dowody wskazują na znaczną poprawę we wszystkich czterech, z gojenia nadal stąd.';

  @override
  String get benzodiazepineReferenceDay1095 =>
      'Trzy lata po benzodiazepinach: Długoterminowe leczenie\n\nŹródło: Barker et al., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), on PubMed\n\nDługi widok\nTrzy lata znajduje się na końcu okresu regeneracji benzo. Dla większości ludzi, nawet po poważnych długotrwałych z drawall, objawy destrukcyjne są dobrze za nimi i jakość życia jest przekształcana w porównaniu z aktywnym wykorzystaniem.\n\nCo Meta- Analiza Znaleziono\nPołączone badania długoterminowych użytkowników wykazują poprawę w wielu obszarach po drawaniu. przez lata abstynencji, dominująca historia jest szeroka regeneracja w thinking, memory, and day – to – day functions.\n\nSygnał odzyskiwania\nDługoterminowe badania pokazują poprawę wielu obszarów myślenia i pamięci. Do trzech lat, wczesne i utrzymujące się fazy wycofania są daleko za tobą i te zyski miały lata do wzmocnienia.\n\nWiadomość o nadziei\nPodróż benzo rekonwalescencja jest jednym z najbardziej wymagających w medycynie, a trzy lata długotrwałego uzdrawiania jest głębokim osiągnięcia.Dowody są jasne: mózg leczy się w sposób zasadniczy, większość ludzi odzyskuje swoją klarowność, sen i rangę emocjonalną, a poprawa trwa z czasem.';

  @override
  String get cocaineReferenceDay1 =>
      'Kokaina Withdrawal- pierwsze 24 godziny\n\nŹródło: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nKokaina i mózg\nKokaina blokuje wychwyt dopaminy i innych monoaminotyków ) w obwodach nagrody mózgowej, powodując gromadzenie dopaminy i generowanie intensywnej euforii i energii. z regularnym wykorzystaniem mózgu dostosowuje się poprzez obniżenie regulacji tego systemu, tak, że bez leków, normalne działania czują się płaskie.\n\nThe Crash\nStatPearls opisuje pobudzające odstawienie leku jako początek od ustąpienia po przerwaniu stosowania leku, charakteryzującego się wyraźną depresją, nadmiernym śpiochem, głodem, słabym samopoczuciem oraz ciężkim spowolnieniem ruchu i myślenia. W ciągu pierwszych 24 godzin zazwyczaj obejmuje to:\n• Ekstremalne zmęczenie i zwiększone zapotrzebowanie na sen\n• Upośledzony nastrój, wolniejszy ruch i myślenie\n• Zwiększenie apetytu Kokaina hamuje apetyt )\n\nRzeźby, drażliwość, i niepokój są również bardzo często zgłaszane w tym oknie w szerszym literaturze uzależnienia, nawet jeśli StatPearls nie cementuje ich jako część specyfiki katastrofy.\n\nW przeciwieństwie do innych leków\nStatPearls zauważa, że leczenie odstawienia stymulantu jest prowadzone z obserwacją i opieką wspomagającą; w przeciwieństwie do alkoholu lub benzodiazepiny z drawal.Głównym zagrożeniem jest depresja psychiczna, a u pacjentów ciężkich, myśli samobójcze mogą wystąpić w trakcie przyjmowania, więc wsparcie i monitorowanie są wskazane.\n\nBrak zatwierdzonych leków\nObecnie nie ma żadnych leków zatwierdzonych do leczenia kokainy z drawalem; zarządzanie jest popierane, a podejścia niezwiązane z narkotykami, takie jak zarządzanie sytuacjami awaryjnymi są oparte na dowodach leczenia w przypadku choroby podstawowej.';

  @override
  String get cocaineReferenceDay3 =>
      'Trzy dni bez kokainy: Nawigacja Peak Challenge\n\nŹródło: \"Cocaine Toxicity,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nJak Kokaina wpływa na ciało\nStatPearls dokumentuje, że kokaina blokuje ponowne wychwyt dopaminy, noradrenaliny i serotoniny, przedłużając stymulację współczującą. To jest to, co napędza zarówno jego euforii i jej niebezpieczeństwo może wpływać na prawie każdy system narządów.\n\nDni 2x4: Najwyższe psychologiczne wycofanie\nW trzecim dniu ostrej katastrofy ustąpił najbardziej intensywny psychologiczny z drawall:\n• Niski nastrój i depresyjny nastrój w ich najbardziej intensywne\n• Utrata przyjemności\n• Mocne, wywołane cue- pragnienia\n• Lęk i niepokój\n• Zaburzenia snu Nadmierne uczucie bezsenności u niektórych, bezsenność u innych\n\nNiebezpieczeństwo sercowo – naczyniowe powraca\nStatPearls identyfikuje toksyczność sercowo – naczyniową jako działanie najbardziej śmiertelne: zwiększenie częstości akcji serca i ciśnienia krwi, zwiększenie stężenia tlenu w mięśniach mięśnia sercowego, naczynie wieńcowe i aktywacja płytek krwi powodują ryzyko zaburzeń rytmu serca, ubytku i udaru, nawet u młodych użytkowników. Cocaines ma krótki okres półtrwania, około jednej godziny, a do dnia trzeciego sam lek w pełni oczyścił organizm, chociaż StatPearls zauważa, że jego metabolity mogą powodować zwężenie naczyń krwionośnych przez kilka godzin po użyciu, a jeden metabolit może utrzymywać się w ciągu tygodnia, tak więc niektóre pozostałe szczepy sercowo – naczyniowe mogą przetrzymać lek.\n\nThe Road Ahead\nFaza ostra jest intensywna, ale to objawy psychologiczne depresja, rzemiosło, utrata przyjemności wymagają największego wsparcia i utrzymują się przez dłuższy czas.';

  @override
  String get cocaineReferenceDay7 =>
      'Tydzień bez kokainy: Fizyczna regeneracja zaczyna się\n\nŹródło: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nOstra faza kończy się\nStatPearls opisuje wycofanie kokainy jako przejście z początkowej fazy katastrofy do dłuższego fazy regeneracji. Do końca pierwszego tygodnia, najgorsze objawy są zwykle złagodzenie podczas systemu dopaminy kontynuuje rekultywację.\n\nFizyczny odzysk w dół\nKiedy kokaineza przestaje być pobudzana, jej kardiowaskularny, apetyt, senność i zaburzenia dróg oddechowych zaczynają się cofać w ciągu kolejnych dni i tygodni:\n• Tętno i ciśnienie krwi wracają do normy.\n• Apetyt stopniowo zwraca kokainę mocno tłumi ją )\n• Wzory snu zaczynają się stabilizować\n• Przejścia nosowe zaczynają zdrowieć, jeśli kokaina została wciągnięta\n\nObjawy psychologiczne Kontynuuj\nStatPearls zauważa, że depresja i utrata przyjemności są charakterystyczne dla pobudzającego wycofania i przetrwa objawy fizyczne:\n• Nastroje pozostają niskie, choć mniej dotkliwe niż na szczycie\n• Zachcianki wywołane cue- pozostają silne\n• Koncentracja i motywacja są nadal osłabione\n\nOkres po- ostry\nWycofanie się następnie przesuwa się na tygodnie lub miesiące trwalszej poprawy w moodach, rzemiosłach i jasnym myśleniu. wiedząc, że wzór ten sprawia, że wolniejsza część odzysku łatwiej sobie radzić.';

  @override
  String get cocaineReferenceDay14 =>
      'Dwa tygodnie bez kokainy: znalezienie stabilności\n\nŹródło: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nDwa tygodnie w\nW ciągu dwóch tygodni, poważne objawy awarii, głęboka depresja, spanie dużo, i spowolnić ruch i myślenie ogólnie ustąpiły.\n\nStan nastrojów i emocji\nW ciągu dwóch tygodni, nastrój może być nadal poniżej normy, podczas gdy system dopaminy odzyskuje. W porównaniu z pierwszym tygodniem, głęboka utrata przyjemności jest złagodzenie i prawdziwe momenty dobrego samopoczucia powracają.\n\nZachcianki i trygony\nNa tym etapie znaczne wyzwanie stanowią żądze wywołane przez kokainę. Mózg utworzył silne powiązania między zażywaniem kokainy a specyficznymi środowiskami, ludźmi, emocjami i aktywnością. Narażenie na te czynniki może wywołać intensywne pragnienie nawet wtedy, gdy ogólny nastrój jest improwizowany.Unikanie środowisk wysokiego ryzyka i budowanie nowych stowarzyszeń jest ważne.\n\nPoprawa snu\nSen jest zwykle bardziej stabilny i regenerujący w ciągu dwóch tygodni niż podczas ostrej fazy odstawienne. Ulepszony sen ma znaczący pozytywny wpływ na nastrój, jasne myślenie, i zdolność do zarządzania rzemiosł.\n\nBudowa Fundacji\nPonieważ oparte na dowodach metody leczenia zaburzeń stymulacji są behawioralne zarządzanie awaryjne, terapia, a wzajemna pomoc jest ważnym czasem na zaangażowanie się w struktury wsparcia, które będą stanowić podstawę długotrwałego odzyskiwania.';

  @override
  String get cocaineReferenceDay60 =>
      'Dwa miesiące bez kokainy: Nastrój i nagroda zaczynają się odzyskać\n\nŹródło: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations,\" Neuroscience & Biobehavioral Reviews (2013), on PubMed Central\n\nCo robi mózg\nPrzegląd ten syntezuje badania ludzi i zwierząt na temat tego, co dzieje się z mózgiem, gdy kokaina przestaje zażywać. przewlekła kokaina zmienia układ dopaminy i zmniejsza aktywność w korze czołowej; odzyskiwanie tych systemów jest substratem dla nastroju i motywacji poprawia ludzi zauważyć we wczesnym abstynencji.\n\nPostęp systemu nagradzania\nW badaniach na zwierzętach, związane z kokainą zmiany w receptorach dopaminy i białkach recyclingu wróciły do zdrowych poziomów z trwałym abstynencją.\n\nSygnał odzyskiwania\nPrzez dwa miesiące, nastrój się poprawia i sen jest bardziej stabilny, podczas gdy systemy dopaminy i kory czołowej w dalszym ciągu się odbudowują. Badania naczelnych pokazują, że związane z kokainą receptory D1 i transporter zmiany z powrotem do poziomu kontroli z trwałym abstynencji.';

  @override
  String get cocaineReferenceDay90 =>
      'Trzy miesiące bez kokainy: Markery dopaminy Rebound\n\nŹródło: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations,\" Neuroscience & Biobehavioral Reviews (2013), on PubMed Central\n\nDlaczego 90 Dni jest punktem orientacyjnym\nW nieludzkich prymatach, receptory dopaminy D1 i transportery, które podniosły ilość kokainy, wykazały, że po około 90 dniach abstynencji powróciły do poziomu kontroli.\n\nFront mózgu\nAutorzy podkreślają, że odzyskiwanie w przedniej części mózgu jest jednym z najważniejszych oznak rozszerzonego abstynencji.\n\nCo 90 dni pokazuje\nW 90 dniach, badania naczelnych wykazały D1, D2, i gęstość transportera dopaminy nie różni się już znacząco od kontroli non – Drug. Nawet po długiej ekspozycji, znaczna regeneracja systemu dopaminowego jest już widoczne w tym punkcie i nadal z abstynencją.';

  @override
  String get cocaineReferenceDay180 =>
      'Sześć miesięcy bez kokainy: Czystsze myślenie\n\nŹródło: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies,\" on PubMed Central\n\nOdzyskiwanie można obrazek\nTen przegląd łączy podłużne badania obrazowe mózgu, które skanują tych samych ludzi wielokrotnie jak ich abstynencja wydłuża się. Dla kokainy, informuje, że aktywność funkcjonalna poprawia się w sposób mierzalny z trwałym abstynencji.\n\nDowody obrazowania mózgu\nW jednym z nich, po około sześciu miesiącach abstynencji, model aktywacji mózgu był porównywalny do wzorca nieuzależnionej zdrowej kontroli. W różnych substancjach, przegląd zauważa, że wyniki obrazowania nuclear- wskazują na regenerację dopaminergiczną z abstynencją.\n\nCo to oznacza w 6 miesięcy?\nTe funkcjonalne korzyści są zgodne z poprawą obserwowaną na tym etapie:\n• Lepsza uwaga i pamięć robocza\n• Rozstrzyganie decyzji i kontrola impulsowa\n• Nastroje Steadier i regulacja emocjonalna\n\nSygnał odzyskiwania\nW ciągu około sześciu miesięcy, jedna podłużna kohorta fMRI wykazała wzorzec aktywacji porównywalny do nieuzależnionych zdrowych kontroli, podczas gdy aktywacja mózgu i głębokiego mózgu poprawiła się wraz z wydłużeniem abstynencji.';

  @override
  String get cocaineReferenceDay365 =>
      'Rok bez kokainy: Kardiochirurgiczne rozszczepienie usunięte\n\nŹródło: \"Cocaine Toxicity,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nDlaczego serce jest w centrum\nStatPearls identyfikuje toksyczność układu sercowo – naczyniowego jako kokaineza najbardziej zabójcze efektu. każde zastosowanie podnosi ratę serca, ciśnienie krwi, i zapotrzebowania na tlen mięśnia sercowego, jednocześnie powodując skurcz naczyń wieńcowych i promowanie tworzenia skrzepów, co powoduje połączenie, które powoduje atak serca, arytmię, i udar nawet u młodych ludzi.\n\nCo roku abstynencji usuwa\nKażdego dnia bez kokainy jest dzień wolny od tych ostrych insulina. przez rok, powtarzające się nasilenie ciśnienia krwi i częstości akcji serca są nieaktualne, ryzyko skurczu wieńcowego wywołanego kokainą i ostrego zawału jest usuwany, a serce nie jest już napędzane do niedopasowania tlenu.\n\nSygnał odzyskiwania\nZatrzymanie kokainy powstrzymuje powtarzające się naczynie wieńcowe, tachykardia, zwiększenie napięcia, promotion skrzepu, i niedopasowanie tlenu, które napędzają ostre serce. Istniejące zwłóknienie lub zapalenie mięśnia sercowego pozostaje problemem medycznym, ale powtarzające się zniewagi wywołane kokainą nie jest.\n\nOdzyskiwanie mózgu również\nW ciągu jednego roku systemy nagradzania i samokontroli miały wydłużony czas na odzyskanie, wspieranie lepszej kontroli impulsowej, twardszy nastrój i silniejsza odpowiedź na codzienne nagrody.';

  @override
  String get cocaineReferenceDay730 =>
      'Dwa lata bez kokainy: Trwała poprawa\n\nŹródło: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations,\" Neuroscience & Biobehavioral Reviews (2013), on PubMed Central\n\nDługi widok\nW przeglądzie tym zebrano wyniki badań na ludziach i zwierzętach na temat rozszerzonej abstynencji kokainowej. Jej głównym wnioskiem jest to, że zachowanie i odzyskanie funkcji kory czołowej jest najważniejszym wskaźnikiem długotrwałej abstynencji, a także długotrwałych abstynencji ( 10 + miesiące ) wykazały większą aktywność kory czołowej niż krótkotrwałe abstynencje.\n\nCo trwa do uzdrowienia\n• Znaczniki dopaminy zmienione przez kokainę nadal zmierzają do normy z trwałą abstynencją\n• Zmniejszona integralność substancji ziele- i biało- obserwowana u aktywnych i silnie abstynentnych osób może odwrócić się w dłuższym okresie abstynencji, prawdopodobnie poprzez dalsze dojrzewanie mieliny.\n• Obwody kontroli frontalnej Kontrola impulsów, osądy, Umacnianie regulacji emocjonalnych\n\nSygnał odzyskiwania\nAutorzy podnoszą prawdziwą uwagę naukową: niektóre z różnic w długoterminowych wstrzymujących się od głosu mogą odzwierciedlać skutki dla osób, które rozpoczęły się z większą integralnością mózgu może być łatwiej pozostać abstynentem niż samotnym. Co jest jasne, że dwa lata bez kokainy wspiera mózg funkcjonujący znacznie bliżej nieużytkowników, a życie, które nie jest tylko abstynentem, ale znacznie odbudowywać.';

  @override
  String get ghbReferenceDay1 =>
      'GHB Withdrawal: pierwsze godziny\n\nŹródło: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nTo jest nagły wypadek medyczny.\nGHB jest jednym z najbardziej niebezpiecznych substancji z drawals, niwelowanie ciężkiego alkoholu i benzodiazepiny z drala. nieleczone. może to postępować do majaczenia w ponad połowie przypadków, z niebezpiecznymi wahaniami częstości akcji serca i ciśnienia krwi i drgaw. każdy, kto zależny od GHB, GBL, lub 1,4 – butanodiol powinien szukać nadzoru detox pacjentów, a nie zatrzymywać się sam.\n\nDlaczego zaczyna się tak szybko?\nOkres półtrwania GHBZREX wynosi tylko 30% 60 minut, a użytkownicy zależni zazwyczaj muszą ponownie podawać co 2 godziny, aby uniknąć odstawienia leku znacznie szybciej niż alkohol lub benzodiazepiny.\n\nWczesne objawy\nZmęczenie, niedociśnienie, drżenie, drżenie, przyspieszone bicie serca i wzrost ciśnienia krwi.';

  @override
  String get ghbReferenceDay3 =>
      'GHB Withdrawal: Najtrudniejsze dni\n\nŹródło: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nNajtrudniejszy odcinek\nBadanie to wykazało kilka rdzeniowych objawów odstawiennych nasilają bóle mięśni, drgania mięśni, napięte i zestresowane uczucie, szybkie skurcze serca, i skurcze brzucha były w najgorszym w pierwszych trzech dniach, z więcej niż 70% spadek ciężkości dla wielu objawów w ciągu czwartego dnia. To wczesne okno jest zazwyczaj najwyższy okres ryzyka, gdy nieleczona wycofanie jest najbardziej prawdopodobne eskalacji w kierunku delirium, wysięk, lub niebezpieczne wahania częstości akcji serca i ciśnienia krwi.\n\nCiężkie cechy\n• Ciężkie pobudzenie i lęk\n• Omamy słuchowe i wzrokowe, paranoja\n• Drżenie, dreszcze, wyścigi serca, i wysokie ciśnienie krwi\n• Ryzyko napadów padaczkowych\n\nZarządzanie\nW badaniu opisano zmniejszanie dawki benzodiazepiny i stosowanie leków GHB zmniejszające się, jako dwa powszechnie stosowane metody detoksykacji, odnotowując pewne dowody, że stożek GHB może kontrolować objawy skuteczniej niż tylko benzodiazepiny. Każde podejście wymaga ścisłego monitorowania, nie jest to bezpieczne w domu.';

  @override
  String get ghbReferenceDay7 =>
      'Jeden tydzień Off GHB\n\nŹródło: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nWiększość objawów słabnie\nKilka podstawowych objawów odstawiennych zmniejszyło się o ponad 70% w ciągu pierwszych czterech dni. W ramach nadzorowanego zwężania sama faza zwężania trwała 11 dni średnio, a następnie faza regeneracji około sześciu dni, więc o jeden tydzień wiele osób jest dobrze w tej poprawie, nawet jeśli proces jest w pełni zakończona.\n\nCo może Linger\n• Pocenie się, drżenie i drżenie rąk\n• Spanie na locie, lub odwrotnie bezsenność i niepokój\n• Zachcianki\n\nW badaniu stwierdzono, że te szczególne objawy zmieniły się stosunkowo niewiele nawet do 11 dni, więc wytrwałość w tym tygodniu jest nietypowa. Kontynuacja nadzoru medycznego pozostaje ważne, dopóki zespół wyraźnie ustalił.';

  @override
  String get ghbReferenceDay14 =>
      'Dwa tygodnie przed GHB\n\nŹródło: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nPrzeszłość zespołu ostrego\nW ciągu dwóch tygodni, ostry zespół fizyczny opisany w tym badaniu, którego fazy zwężania i regeneracji razem średnio około 17 dni pod nadzorem leczenia ogólnie ustąpił lub jest bardzo blisko tego.\n\nCo Lingers\nBadanie wyraźnie wskazuje na pragnienie i bezsenność, jak nadal obecny przy absolutorium dla niektórych pacjentów, zauważając, że mogą one przyczynić się do nawrotu ryzyka. Wsparcie i struktura ma teraz znaczenie, nawet jak niebezpieczna wczesna faza jest za tobą.';

  @override
  String get ghbReferenceDay30 =>
      'Miesiąc wolny GHB\n\nŹródło: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nGdzie jest jeden miesiąc\nAcute, niebezpieczna faza opisana w tym badaniu jest dawno min. o jeden miesiąc, ostra niebezpieczna faza skoncentrowana w pierwszych dniach, a następnie nadzorowany taper – and – recovery okres średnio dwa i pół tygodnia.Pragnienie i bezsenność są kluczowe pozostałości ryzyka nawrotu zidentyfikowane w dysCharge.\n\nDlaczego wsparcie nadal pomaga\nJeśli problemy z humorem, słabym samopoczuciem lub snem są nadal obecne w jednym miesiącu, to zgadza się z tym, co badacze autorzy oznaczone jako czynniki ryzyka nawrotu, co dokładnie dlatego stałe wsparcie i struktura Matter.';

  @override
  String get ghbReferenceDay90 =>
      'Trzy miesiące Off GHB\n\nŹródło: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nTrzy miesiące odzyskiwania\nW ciągu trzech miesięcy, ostry zespół odstawienia GHB jest długo rozwiązany. Pozostałych zagrożeń stwierdzonych przy wydzielaniu są pragnienie i niedogodności, więc trzy miesiące abstynencji daje senność, autonomiczny stabilizacja i nawracające rutyny prewencyjne znaczny czas do konsolidacji.\n\nCo ludzie zgłaszają\n• Uspokoić zwykle nastrój\n• Bardziej niezawodny sen\n• Czystsze myślenie i mniej pragnień\n\nJeśli niepokój, niepokój lub niski nastrój są nadal widoczne w trzech miesiącach, że warto dyskutować z lekarzem, zamiast zakładając, że będzie rozwiązać na własną rękę.';

  @override
  String get ghbReferenceDay180 =>
      'Sześć miesięcy Off GHB\n\nŹródło: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nPół roku\nPrzez sześć miesięcy ostry zespół odstawienny GHB jest długo rozwiązany, a regeneracja całkowicie zmieniła się z detoksykacji do stabilnego snu, pragnienie kontroli i zapobiegania nawrotom.\n\nWiększy obraz\nUzyskanie przez GHB wycofanie bezpiecznie i trzymać off na pół roku jest głównym osiągnięciem biorąc pod uwagę, jak niebezpieczne jest wczesna faza, i jak prawdziwe ryzyko nawrotu spowodowane częściowo przez utrzymujące się pragnienie i bezsenność może być. Rutyny i wsparcie, które dostał się tutaj są warte zachowania.';

  @override
  String get inhalantsReferenceDay1 =>
      'Zatrzymanie inhalatorów: dzień pierwszy\n\nŹródło: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse,\" The Permanente Journal (2023), on PubMed Central\n\nDlaczego odstawienie się zdarza\nPrzewlekłe stosowanie inhalatorów powoduje neuroadaptację, układ nerwowy przychodzi oczekiwać substancji. Wiele inhalatorów wpływa na te same obwody mózgu jak alkohol, więc zatrzymuje pozostawia mózg tymczasowo niebalansowane. chemikalia oczyścić krew szybko, ale są przechowywane w tłuszcz ciała, co może sprawić, że czas odstawienia nieprzewidywalne.\n\nWczesne objawy\nW niniejszym przeglądzie opisano wycofanie inhalatorów jako podobne do alkoholu lub benzodiazepiny z drawalą, z objawami, które mogą być zgłaszane:\n• Nudności, wymioty i pocenie się\n• Drżenie i przyspieszone bicie serca\n• Bezsenność i zaburzenia snu\n• Lęk i drażliwość\n\nNota bezpieczeństwa\nW cięższych przypadkach, przegląd zawiera również listę halucynacji, złudzeń i napadów wśród zgłaszanych objawów, chociaż nie określa dokładnego harmonogramu dnia – dzień traktować je jako objawy, które mogą wystąpić, nie określony czas. Nadzór medyczny jest mądry podczas detoxu, zwłaszcza dla ciężkich, długoterminowych użytkowników.';

  @override
  String get inhalantsReferenceDay7 =>
      'Tydzień bez inhalantów\n\nŹródło: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse,\" The Permanente Journal (2023), on PubMed Central\n\nOstre okno\nWdychanie odstawienia leku jest opisane w literaturze klinicznej jako podobne do alkoholu lub benzodiazepiny z drawal. ale jest to powszechnie rozumiane jako skrócone życia. do końca pierwszego tygodnia ostre objawy fizyczne występują u większości osób, drżenie, dreszcze, dreszcze, bezsenność zwykle ustępują.\n\nCo pozostało\n• Zmęczenie i mgła mózgowa\n• Niski lub niestabilny nastrój\n• Zachcianki\n\nUwaga: Wczesna abstynencja\nMgła mózgowa na tym etapie nie oznacza trwałych uszkodzeń, a mózg jest wciąż dostosowywany. Badania na temat tego, jak myślenie i pamięć konkretnie odzyskać w ciągu następnych tygodni i miesięcy jest pokryte w późniejszych etapach.';

  @override
  String get inhalantsReferenceDay14 =>
      'Dwa tygodnie bez inhalantów\n\nŹródło: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse,\" The Permanente Journal (2023), on PubMed Central\n\nW fazie ostrej\nOpinie kliniczne opisują odstawienie inhalatorów jako podobne do odstawiania alkoholu lub benzodiazepiny, ale skrócone.\n\nThe Road Ahead\nUwaga, zapamiętanie, poruszanie się i koordynacja coraz bardziej stopniowo powracają w ciągu następujących miesięcy. Kontynuacja abstynencji daje wszystkim tym systemom czas na poprawę. Dobre odżywianie inhalator może zmniejszyć witaminę B12 ) i abstynencja ustawić etap na to.';

  @override
  String get inhalantsReferenceDay30 =>
      'Miesiąc bez inhalantów\n\nŹródło: Dingwall et al., \"Cognitive recovery during and after treatment for volatile solvent abuse,\" Drug and Alcohol Dependence (2011), on PubMed\n\nGdzie jest jeden miesiąc\nW tym badaniu niektóre umiejętności uczenia się poprawiły się w ciągu sześciu tygodni, podczas gdy koordynacja wizualna, zapamiętywanie, planowanie i podejmowanie decyzji poprawiały się stopniowo w ciągu kolejnych miesięcy.\n\nCo może poprawić\n• Uwaga i niektóre zadania edukacyjne\n• Nastroje i senność, jak ciało stabilizuje się\n• Prędkość silnika, stopniowo\n\nSygnał odzyskiwania\nWnioski z badań są jasne: zapamiętanie, planowanie i podejmowanie decyzji stopniowo ulegają poprawie w ciągu miesięcy do lat abstynencji.';

  @override
  String get inhalantsReferenceDay90 =>
      'Trzy miesiące bez inhalantów\n\nŹródło: Dingwall et al., \"Cognitive recovery during and after treatment for volatile solvent abuse,\" Drug and Alcohol Dependence (2011), on PubMed\n\nNieznany, dłuższy proces\nBadanie to było kontynuacją działań osób poza ośmiotygodniowym programem leczenia i sprawdziło niektóre z nich ponownie około roku później. Niektóre umiejętności uczenia się poprawiły się w ciągu sześciu tygodni, podczas gdy koordynacja wizualna, zapamiętywanie, planowanie i podejmowanie decyzji w dłuższym okresie.\n\nPozostawanie w kursie\nBadanie pokazuje, że wolniejsze umiejętności ulegają stopniowej poprawie w ciągu kilku miesięcy. W ciągu trzech miesięcy, kontynuacja abstynencji jest najsilniejszą dźwignią do zwiększenia odzysku miesiąc po miesiącu.';

  @override
  String get inhalantsReferenceDay365 =>
      'Rok bez inhalantów\n\nŹródło: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse,\" on PubMed\n\nReal- Wymierne odzyskiwanie\nW długotrwałym badaniu stwierdzono znaczne ożywienie z powodu przewlekłych zaburzeń mózgu związanych z inhalacją i myślenia po dwóch latach abstynencji.\n\nCo to znaczy?\nPamięć, uwaga i motoryka nadal poprawiają się. Długoterminowa abstynencja powoduje regenerację mózgu: przez dwa lata, większość mózgów, pamięci i myślenia wyniki powróciły do normy u przewlekłych użytkowników, którzy nie mieli uszkodzenia mózgu z ołowiu.';

  @override
  String get inhalantsReferenceDay730 =>
      'Dwa lata bez inhalantów\n\nŹródło: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse,\" on PubMed\n\nDwuletni znak\nJest to kluczowy kamień milowy w badaniach: deficyty odzwierciedlające uszkodzenia mózgu spowodowane długotrwałym stosowaniem rozpuszczalników wykazały znaczny wzrost po dwóch latach abstynencji. Autorzy doszli do wniosku, że w przypadku braku uszkodzenia mózgu przez petrol ołowiany, długotrwałe abstynencje mogą umożliwić przywrócenie prawidłowej funkcji mózgu.\n\nSygnał odzyskiwania\nGłównym wyjątkiem jest uszkodzenie benzyny ołowianej, które może powodować trwałe zanieczyszczenia. Otherwise, dwa lata abstynencji reprezentuje mózgi najlepiej udokumentowane możliwość leczenia wraz z życia odbudowane wokół.';

  @override
  String get ketamineReferenceDay1 =>
      'Zatrzymanie Ketaminy: dzień pierwszy\n\nŹródło: \"Ketamine-Induced Cystitis: A Comprehensive Review of the Urologic Effects of This Psychoactive Drug,\" on PubMed Central\n\nWycofanie jest głównie psychologiczne.\nW przeciwieństwie do opioidów lub alkoholi, ketamina rzadko wytwarza ciężkie fizyczne z drawa. zaprzestanie jest na ogół bezpieczne; ludzie częściej zmagają się z pragnieniami i uzależnieniem psychicznym niż choroby fizyczne.\n\nCo możesz czuć\n• Huśtawki nastrojów i niski nastrój\n• Zachcianki\n• Sporadyczne pocenie się lub kołatanie serca\n\nEtap kluczowy\nDla każdego, kto ma objawy pęcherza moczowego, natychmiastowe i całkowite zaprzestanie jest obowiązkowym punktem wyjścia do powrotu do zdrowia, więc pierwszy dzień jest najważniejszą decyzją wszystkich.';

  @override
  String get ketamineReferenceDay7 =>
      'Tydzień bez ketaminy\n\nŹródło: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nFaza psychologiczna\nGłównym wyzwaniem we wczesnym zaprzestaniu podawania ketaminy jest psychologia: zgryzy, zmiany lub niski nastrój, a niektóre mózgi zanikają.\n\nMgła mózgowa jest na tym etapie powszechna: koncentracja jest trudna, czas reakcji jest wolniejszy, a pamięć krótkookresowa może czuć się nieniezawodna. Te efekty na myślenie i pamięć poprawiają się z abstynencją: badanie podłużne 114 użytkowników ketaminy wykazało znaczące korzyści w pamięci słownej, pamięci wizualnej, szybkości przetwarzania, planowania, skupienia i podejmowania decyzji po 12 tygodniach bez ketaminy.\n\nObjawy pęcherza\nJeśli masz zapalenie pęcherza moczowego wywołane ketaminą moczowego, częste, ból, lub krew w moczu, zatrzymanie teraz daje pęcherz jest najlepszą szansą na uzdrowienie. Ból może kusić ludzi z powrotem do ketaminy do samoleczenia się cyklu wartego złamania z odpowiedniego wsparcia bólu.';

  @override
  String get ketamineReferenceDay14 =>
      'Dwa tygodnie poza Ketaminą\n\nŹródło: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nCzystsze myślenie\nZ leku w pełni czyste, umysłowa mgła i rozłączony myślenia związane z regularnym stosowaniu ketaminy zaczynają się rozwijać. Pamięć i koncentracja poprawy i nastrój stabilny.\n\nRozpoczęcie odzyskiwania pęcherza\nW przypadku cystyzmu na początku badania, przegląd podkreśla, że po prostu zatrzymanie ketaminy jest jednym z najważniejszych kroków w kierunku odwrócenia objawów, a wcześniejsze zaprzestanie daje najlepsze szanse na powrót do zdrowia, zanim uszkodzenia staną się trwałe. Dwa tygodnie abstynencji jest początkiem tego procesu.';

  @override
  String get ketamineReferenceDay30 =>
      'Miesiąc bez ketaminy\n\nŹródło: \"Prevalence and Natural History of Urinary Symptoms Among Recreational Ketamine Users,\" Winstock et al., BJU International (2012)\n\nOdzyskiwanie pęcherza\nNajistotniejszym leczeniem zapalenia pęcherza wywołanego ketaminą jest zatrzymanie ketaminy. Badanie z udziałem rekreacyjnych użytkowników ketaminy wykazało, że 51% pacjentów z objawami moczu zgłosiło poprawę po zaprzestaniu stosowania, podczas gdy poniżej 4% się pogorszyło.\n\nUmysł i nastroje\nPogłębianie i nastrój nadal oczyszczają się w ciągu jednego miesiąca. Wsparcie psychologiczne i społeczne znacząco zwiększa szanse na pozostanie zatrzymane, najlepiej działa, gdy jest popierana.';

  @override
  String get ketamineReferenceDay90 =>
      'Trzy miesiące poza Ketaminą\n\nŹródło: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nKontynuacja odzyskiwania\nOdzysk pęcherza po ketaminie jest często stopniowy; przegląd opisuje nasilenie objawów poprawy po cessation, choć może być wydłużony i zmienny. Trzy miesiące daje dróg moczowych utrzymujący się czas do gojenia w przypadkach, które mają na celu odpowiedź.\n\nUmysł\nWyraźne myślenie i nastrój są wyraźnie jaśniejsze niż we wczesnym abstynencji, a apetyty są mniej część. trwałe lub ciężkie objawy pęcherza moczowego powinny być oceniane przez urologa.';

  @override
  String get ketamineReferenceDay180 =>
      'Sześć miesięcy poza Ketaminą\n\nŹródło: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nPół roku\nZ utrzymującym się abstynencji, objawy pęcherza moczowego nadal się poprawia w przypadkach, które reagują na cessation, a myślenie i pamięć i nastrój są stabilne. nałogu do stosowania osłabił troskliwie.\n\nSygnał odzyskiwania\nOdzyskiwanie ustalonych uszkodzeń pęcherza może być niekompletny, dlatego wczesne zaprzestanie ma znaczenie tak wiele. Jakikolwiek etap zatrzymałeś się, pozostając poza daje pęcherza jego najlepszy możliwy outcome.';

  @override
  String get ketamineReferenceDay365 =>
      'Rok bez ketaminy\n\nŹródło: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nRok\nDwanaście miesięcy abstynencji daje bladder, w przypadkach ciężko złowionych, najpełniejszą szansę na odzyskanie, i pozostawia myślenie i pamięć i nastrój stabilny i jasne. Psychologiczne uzależnienie, które uczyniło zatrzymanie trudne w dużej mierze zanikła.\n\nWiększy obraz\nRok wolny to głęboka zmiana w zdrowiu fizycznym, klarowności i samokierowaniu.';

  @override
  String get kratomReferenceDay1 =>
      'Kratom Withdrawall: pierwszy dzień\n\nŹródło: Swogger et al. (2022), \"Understanding Kratom Use: A Guide for Healthcare Providers,\" Frontiers in Pharmacology\n\nDlaczego odstawienie się zdarza\nW związku z tym zaprzestanie stosowania opioidów powoduje powstanie opioidów podobnych do opioidów. Ten przewodnik kliniczny opisuje uzależnienie i wycofanie leku jako uznane ryzyko regularnego stosowania kratomu.\n\nCo dowód pokazuje o Onset\nBadania na zwierzętach wymienione w przewodniku wykazują somatyczne objawy odstawienne pojawiające się w ciągu około 12 godzin, o skutkach podobnych do tych, które występują po 24 godzinach; dokładny czas wystąpienia u człowieka jest mniejszy, ale wczesne objawy często zgłaszane obejmują:\n• Niepokój, niepokój i drażliwość\n• Ból mięśni i katar nosa\n• Pocenie i łzawienie oczu\n• Zachcianki\n\nNotatka na temat ciężkości\nPrzewodnik zwraca uwagę, że dłuższy czas stosowania i większe dawki są związane z bardziej poważnymi, dłuższymi dawkami. Należy szukać nadzorowanego wsparcia medycznego, szczególnie jeśli kratom stosowano w dużych dawkach lub równolegle z opioidami.';

  @override
  String get kratomReferenceDay3 =>
      'Kratom Withdrawall: Najtrudniejsze dni\n\nŹródło: Singh et al. (2014), Drug and Alcohol Dependence — survey of 293 regular kratom users in Malaysia\n\nCo dowód pokazuje\nZamiast jednego określonego szczytowego dnia w tym badaniu znalazł ślady ciężkości wycofania, jak dużo i jak długo ktoś używany: ludzie pijący trzy lub więcej szklanek kratomu codziennie miał znacznie większe szanse na poważne uzależnienie i trudniejsze z drawa. dla większości ludzi, pierwsze kilka dni po zatrzymaniu są trudne.\n\nCzęsto zgłaszane objawy\n• Ból mięśni i stawów, niespokojne nogi\n• Bezsenność pomimo wyczerpania\n• Nudności, skurcze żołądka i biegunka\n• Zmęczenie, niski nastrój i drażliwość\n• Silne pragnienia\n\nPrzebrnięcie przez to\nHydraulika, odpoczynek, i objawowe wsparcie. Jeśli wycofanie czuł się tak daleko tak poważne, że łączy się z cięższe lub dłuższe użycie, a nie coś jest niezwykle złe i ma tendencję do ułatwienia stąd.';

  @override
  String get kratomReferenceDay7 =>
      'Tydzień poza Kratomem\n\nŹródło: Swogger et al. (2022), \"Understanding Kratom Use: A Guide for Healthcare Providers,\" Frontiers in Pharmacology\n\nPrzeszłość fazy ostrej\nDane dotyczące samozgłoszenia się człowieka przytoczone w niniejszym przewodniku wskazują na to, że objawy odstawienne ustępują w ciągu około jednego do trzech dni u większości osób, które się zatrzymały. W ciągu jednego tygodnia ostre objawy fizyczne nasilają bóle mięśni, drżenie, nudności zwykle ustępują dla większości.\n\nPrawdziwe ryzyko\nPrzewodnik zauważa również, że niewielka liczba osób uważa, że kratom jest bardzo trudny do odrzucenia, z bardziej dotkliwym i długotrwałym wycofaniem zgłaszanym wśród osób zażywających opiaty w dłuższej perspektywie. Ten tydzień jest powszechnym punktem dla nawrotów, a tolerancja szybko spada wracając do poprzedniej dawki, zwłaszcza jeśli opioidy są zaangażowane, jest teraz naprawdę niebezpieczne.';

  @override
  String get kratomReferenceDay14 =>
      'Dwa tygodnie przed Kratomem\n\nŹródło: National Institute on Drug Abuse (NIDA), \"Kratom\"\n\nZa studiowanym oknem\nKontrolowane dane dotyczące czasu odstawienia kratomu obejmują zazwyczaj tylko kilka pierwszych dni, dlatego też istnieją dobrze ustalone badania, które wskazują na konkretny dwutygodniowy okres. Co udokumentowane jest szerszy wzór: kratom działa na te same receptory opioidowe co opioidy klasyczne, a ponieważ regularne stosowanie zatrzymuje te receptory stopniowo przywracając ich wrażliwość na znaki własne ciał.\n\nCo ludzie zgłaszają\n• Apetyt i energia często się poprawiają\n• Sen staje się bardziej niezawodny.\n• Nastrój jest zazwyczaj stały, choć nadal zmienny\n\nPragnienia są nadal wywoływane przez stres i znajome kostki, więc posiadanie planu dla nich pozostaje przydatne.';

  @override
  String get kratomReferenceDay30 =>
      'Miesiąc poza Kratomem\n\nŹródło: National Institute on Drug Abuse (NIDA), \"Kratom\"\n\nOdzyskiwanie systemu nagród\nNIDA opisuje kratom jako działanie na receptory opioidowe, z uzależnieniem i wycofaniem się jako uznane ryzyko regularnego użycia. Nie ma specjalnego badania, które oznaczałoby jeden miesiąc fazy regeneracji, ale ogólny wzór uzależnienia od opioidów opiera się na tym, że reakcja mózgu na codzienne przyjemności stopniowo normalizuje się z trwałym abstynencją.\n\nCo miesiąc off może zbudować\nMiesiąc bez kratomu jest miesiącem konsekwentnych snu, pokarmów i rutynowych zastępowania czasu i wysiłku użycia wymagane. Pragnienia zazwyczaj przybywają rzadziej i czują się bardziej zarządzane, choć momenty wysokiego stresu pozostają najbardziej narażone.';

  @override
  String get kratomReferenceDay90 =>
      'Trzy miesiące od Kratom\n\nŹródło: National Institute on Drug Abuse (NIDA), \"Kratom\"\n\nA Steadier Day – to – Day State\nKratom działa na receptorów opioidowych, więc trzy miesiące bez tego daje nagrody mózgów i systemy stresu trwały czas do ustalenia. Wiele osób zgłaszają jaśniejsze myślenie i bardziej stanowcze motywacja im dalej z aktywnego wykorzystania.\n\nDlaczego to ma znaczenie?\nIm mniej niedawne użycie, tym bardziej dzień do dnia ciągnięcie kratom ma tendencję do zanikania, czyniąc ten kamień milowy solidnym fundamentem do trwałego odzyskania.';

  @override
  String get kratomReferenceDay365 =>
      'Rok poza Kratomem\n\nŹródło: National Institute on Drug Abuse (NIDA), \"Kratom\"\n\nPrzeszłe ostre wycofanie\nNIDA nie opublikuje określonego jednorocznego czasu regeneracji kratomu, ale rok trwałej abstynencji jest znacznie powyżej ostrego i wczesnego okna wycofania psychologicznego udokumentowanego w badaniach kratomu. Dla większości ludzi, którzy osiągają ten punkt, pragnienia są rzadkie i znacznie łatwiejsze do zarządzania.\n\nWiększy obraz\nRok abstynencji stanowi istotną zmianę w zdrowiu, finansach i samokierowaniu.';

  @override
  String get maoiReferenceDay3 =>
      'Przerwanie stosowania MAOI: Faza wysokiego ryzyka\n\nŹródło: Dilsaver (1988), research on MAOI withdrawal reactions\n\nOstrzeżenie o bezpieczeństwie krytycznym\nMAOIS niesie ze sobą najpoważniejsze ryzyko przerwania stosowania leków przeciwdepresyjnych. Nagłe zaprzestanie stosowania fenelzyny i tranylcyprominy może powodować ciężkie reakcje, w tym:\n• Ciężki lęk i pobudzenie\n• Nacisk na mowę i niepokój\n• Bezsenność lub senność\n• Omamy\n• Delirium i psychoza paranoidalna\n\nJeśli u pacjenta występują takie objawy, należy natychmiast zwrócić się o pomoc lekarską.\n\nJak działa MAOIs\nMAOIs działa poprzez nieodwracalne wiązanie się z enzymami monoaminooksydazy IMAOA i MAO- Bhagen. Enzymy te zwykle rozkładają serotoninę, noradrenalinę, dopaminę i tyraminę w mózgu i rynnie. Ponieważ sam enzym jest niszczone, a nie tylko blokowane, regeneracja zależy od organizmu produkującego świeży enzym, a nie od tego, jak szybko lek oczyszcza krew.';

  @override
  String get maoiReferenceDay7 =>
      'Tydzień po MAOISS: MAO Synteza enzymowa w trakcie\n\nŹródło: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nProces odzyskiwania enzymów\nW odróżnieniu od SSRIs, SNRIss i TCAs, które hamują wychwyt zwrotny substancji chemicznych mózgu nieodwracalne MAOIs fixenelzine, tranylcypromine. trwale zniszczyć monoaminooksydazy enzym.\n\nCo się dzieje w jednym tygodniu?\n• Synteza enzymu MAOA i MAO- B jest w połowie drogi przez okno resynchronizacji dwutygodniowej.\n• Faza ostrego ryzyka opisana w dniu 3 jest już przechodząca, choć nadal ważna jest ścisła kontrola lekarska.\n\nDietetyczne łapówki\nLeczenie MAOI wymaga diety niskotyraminy, ponieważ enzymy te zwykle rozkładają tyraminy i zapobiec jej wywoływania nadciśnienia. Wskazówki są, aby zachować przestrzeganie ograniczeń dietetycznych przez to okno resyntezy, lekarz prowadzący doradzi, kiedy jest bezpiecznie je zrelaksować.';

  @override
  String get maoiReferenceDay14 =>
      'Dwa tygodnie po MAOIS-: aktywność enzymu MAO znacząco odzyskane\n\nŹródło: Fritz et al. (1983), Biological Psychiatry\n\nZnacznik krytycznego dwutygodniowego tygodnia\nDwa tygodnie to standardowy okres klinicznego wymywania w celu odzyskania enzymu MAO po zaprzestaniu nieodwracalnego MAOI, takiego jak tranylcypromina lub fenelzyna. Badania te wykazały, że aktywność katalityczna płytek MAO – B znacznie zmniejszyła się w ciągu jednego dnia od podania leku, a w ciągu około dwóch tygodni organizm zastępuje płytki krwi o działaniu farmakologicznym świeżymi, przenoszącymi aktywne enzymy, nawet jeśli całkowity poziom białka MAO – B nigdy się nie zmienił.\n\nOdzysk MAO z enzymów\n• Do tego punktu aktywność płytek krwi MAO- B znacznie się poprawiła.\n• Mózg MAOA i MAO- B, które podążają za zasadniczo podobnym harmonogramem resyntezy, są również w dużej mierze przywrócone\n• Normalny metabolizm tyraminy jest ponowne ustalenie MAOI ograniczeń diety może być zwykle zrelaksowany w konsultacji z lekarzem\n\nBrain- Chemical Balance Returns\nPo odzyskaniu aktywności enzymu MAO, układy chemiczne mózgu, na które wpływa MAOI, zaczynają podlegać naturalnemu regulacjom:\n• Serotonina, noradrenalina i dopamina nie są już podwyższone przez hamowanie MAO\n• Nadwrażliwość receptorów monoaminowych powodowana przez przewlekłe zwiększenie stężenia związków chemicznych MAOI) zaczyna ustępować.\n• Nastrój naturalny i regulacja energii powraca';

  @override
  String get maoiReferenceDay30 =>
      'Miesiąc po MAOIs- Rebalansowanie systemów brain- chemicznych\n\nŹródło: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nOcena miesięczna\nMiesiąc po zaprzestaniu stosowania produktu MAOI znacznie minął około 2 – tygodniowe okno resyntezy enzymu MAO opisane w tym źródle, więc w tym punkcie aktywność enzymu MAO została całkowicie odzyskana, a systemy chemiczne mózgu są w pełni naturalne.\n\nCo odzyskał przez jeden miesiąc\n• Całkowita aktywność enzymu MAO: zarówno MAOA, jak i MAO- B są w pełni sprawne\n• Ograniczenia dietetyczne rozwiązane: normalna dieta bez ograniczeń tyraminy\n• Naturalna degradacja serotoniny: przywrócony normalny cykl obrotu serotoniny\n• Regulacja naturalna katecholaminy: stężenie dopaminy i noradrenaliny regulowane naturalną aktywnością MAO\n\nZaburzenia układu nerwowego\nMAOIs są związane z zagrażającymi życiu interakcjami z lekami serotoninowymi. Ryzyko wystąpienia interakcji ustąpiło w ciągu jednego miesiąca.';

  @override
  String get maoiReferenceDay90 =>
      'Trzy miesiące po MAOIs: Przeszłość cofnięcia\n\nŹródło: \"Antidepressant Withdrawal Syndrome,\" Therapeutics Letter 112 (2018), Therapeutics Initiative, on the NCBI Bookshelf\n\nWycofanie się z klas antydepresyjnych\nNiniejszy przegląd dowodów traktuje odstawienie leków przeciwdepresyjnych jako rzeczywiste zjawisko tolerancji i uzależnienia od leków przeciwdepresyjnych podawanych jednocześnie z opioidami i benzodiazepinami. Jego szczegółowe ośrodki dowodowe na SSRIs i SNRIZs, ale reakcje odstawienne są rozpoznawane w różnych grupach leków przeciwdepresyjnych, w tym po zaprzestaniu stosowania MAOIZ. Objawy zwykle pojawiają się w ciągu kilku dni od zatrzymania i zaprzestania leczenia w ciągu 2 tygodni, choć niektóre z ostatnich lat.\n\nGdzie jest trzy miesiące.\nW ciągu trzech miesięcy ostra faza wycofywania jest znacznie za znaczną większością osób, a organizm od dawna dostosowuje się do regulacji monoamin bez zakłóceń MAO.\n\nSygnał odzyskiwania na Receptorze Resensytyfikacyjny\nPewny siebie twierdzi, że serotonina, noradrenalina i receptory dopaminowe mają wszystkie wartości uwydatniające się przez trzy miesiące wykraczają poza to, co wskazują dowody. Co jest pewne: faza wycofania zazwyczaj została rozwiązana do teraz, a dla większości ludzi moode, energia, i zakres emocjonalny stabilizują się na naturalnej, samoregulowanej sygnalizacji mózgu.\n\nCzasy odstawienne Nawrót\nList podkreśla, że mówi o wycofaniu poza prawdziwym zwrotem podstawowych uwarunkowań. jeśli objawy utrzymują się w trzech miesiącach, należy je przejrzeć z przepisującym zamiast zakładając, że są one tylko z drawall.';

  @override
  String get maoiReferenceDay180 =>
      'Sześć miesięcy po MAOIs- długotrwały odzysk\n\nŹródło: Zwiebel & Viguera (2022), Cleveland Clinic Journal of Medicine\n\nOcena szóstego miesiąca\nPrzegląd ten wyjaśnia, że leki przeciwdepresyjne działają częściowo poprzez powodowanie, że receptory monoaminowe z czasem się zmniejszają, a redukcja ta wymaga tygodni lub miesięcy, aby odwrócić leczenie, gdy lek przestanie działać wolniej niż około dwutygodniowa resynteza enzymu MAO.\n\nGdzie siedzi sześć miesięcy\nSześć miesięcy bezproblemowo przechodzi przez to tygodniowe, do miesięcznych, ponowne dostosowanie receptorów dla znacznej większości ludzi, obok aktywności enzymów, które w pełni znormalizowały się w ciągu pierwszego miesiąca. Sygnał regeneracji: dokładne terminy dla pełnej serotoniny, noradrenaliny i resensytyzacji receptorów dopaminy nie są ustalone z dzienną pewnością w literaturze, co jest pewne, że przez sześć miesięcy, większość ludzi działa na naturalnej, samoregulacji sygnalizacji mózgu.\n\nUwaga dotycząca fenoetyloaminy\nMAOI hamuje również degradację fenotyloaminy PEADER, śladowej aminy związanej z nastrojem i energią. jej metabolizm ma się normalizować wraz z ogólnym odzyskiem enzymu MAO, jednak z rezensyfikacją receptorów jest precyzyjny czas określony dla PEA- określony w literaturze badawczej.';

  @override
  String get maoiReferenceDay365 =>
      'Rok po MAOIs- odzyskanie\n\nŹródło: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nJeden rok: Niezwykłe osiągnięcie\nUkończenie jednego roku po przerwaniu MAOI jest naprawdę znaczącym etapem. MAOI są jednymi z najbardziej uzależnionych leków wymagających antydepresantów, z nieodwracalnym mechanizmem, ścisłą dietą niskotyraminową i środkami ostrożności interakcji leków, które są niepodobne do innych leków przeciwdepresyjnych klasy.\n\nCo ten rok reprezentuje\n• Pełny rok naturalnej, samoregulowanej aktywności monoaminooksydazy, zbudowanej na enzymatycznej resyntezie, która zakończyła się w ciągu pierwszego miesiąca\n• Wykazana zdolność utrzymania dobrego samopoczucia bez hamowania MAO wywołanego narkotykami\n• Na tyle długo, aby mieć pewność, że ryzyko ostrego przerwania leczenia w dniu 3 jest zdecydowanie za tobą.\n\nUwaga dotycząca MAOI\nMAOIs pozostają wyjątkowo skuteczne w pewnych warunkach leczenia i nietypowych depresji. Udane zaprzestanie leczenia nie zmniejsza ich wartości, ponieważ leki wykazują zdolność mózgu do odzysku i pacjent jest w stanie nawigować wyjątkowo wymagający proces medyczny. Jedno trwałe stwierdzenie: nadal mówić każdemu nowemu przepisującemu lub anestezjolog o przeszłości ZT0ZZ użycia, ponieważ niektóre zagrożenia interakcji leków są warte flagging nieokreślony.';

  @override
  String get marijuanaReferenceDay1 =>
      'Marihuana Withdrawal: dzień pierwszy\n\nŹródło: \"The cannabis withdrawal syndrome: current insights,\" Substance Abuse and Rehabilitation (2017), on PubMed Central\n\nWycofanie konopi jest prawdziwe\nW ramach tego przeglądu stwierdzono, że zespół odstawienny konopi indyjskich CWS) jest dobrze potwierdzoną chorobą kliniczną, występującą u około 90% osób zdiagnozowanych uzależnienia od konopi indyjskich po ich przerwaniu.\n\nDlaczego odstawienie się zdarza\nTHC działa na układ endocannabinoidowy, co powoduje, że receptory CB1 biorą udział w moodach, apetycie, śpiochach, pamięci i stresach. Z przewlekłym użyciem mózg zmniejsza ten system; kiedy cannabis przestaje być tymczasowo nieaktywne. Receptory CB1 powracają do normalnego funkcjonowania w ciągu około czterech tygodni abstynencji.\n\nPoczątek pierwszego dnia\nDokumenty przeglądowe, że objawy fizyczne wydają się być pierwsze w ciągu 1: 3 dni od ostatniego zastosowania, a objawy psychologiczne pojawiają się w ciągu 2: 10 dni. Wczesne objawy obejmują:\n• Niepokój, niepokój i niepokój\n• Trudności ze snem\n• Zmniejszenie apetytu\n• Napięcie fizyczne, dreszcze lub dreszcze\n• Nastrój depresyjny\n\nStopień ciężkości\nCWS nie jest zagrożeniem medycznym, a objawy są zazwyczaj łagodne do umiarkowanego, ale notatki recenzji mogą być wystarczająco niepokojące, aby prowadzić nawrotu, co jest powodem zrozumienia czasu matter.';

  @override
  String get marijuanaReferenceDay3 =>
      'Czas wycofania konopi: Wczesne dni\n\nŹródło: \"Time-course of the DSM-5 cannabis withdrawal symptoms in poly-substance abusers,\" BMC Psychiatry (2013), on PubMed Central\n\nZmierzony czas\nBadanie to wykazało, że u 90 pacjentów w ciągu czterech tygodni stwierdzono objawy odstawienne DSM- 5, co jest jednym z najwyraźniejszych obrazów na temat wzrostu i upadku objawów.\n\nCo szczytuje wcześnie\nKilka z najbardziej fizycznie zaburzających objawów szczytowych w ciągu pierwszych kilku dni zatrzymania:\n• Bezsenność szczyty wokół dnia 1\n• Nerwowość wznosi się około 4 dnia\n• Upośledzony nastrój i objawy fizyczne są szczytowe w piątym dniu\n• Niepokój szczyty wokół dnia 6\n\nCo później?\nW badaniu stwierdzono, że niektóre objawy pojawiają się, a szczyt występuje później niż w pierwszym tygodniu:\n• Vivid, nieprzyjemne sny szczytowe wokół dnia 11\n• Narażalność i gniew szczytowy szczyt około dnia 14\n\nSen i konopie indyjskie\nOpóźnione, żywe sny odzwierciedlają rebound REM: cannabis tłumi REM sen podczas użytkowania, a mózg przewyższa kompensację, gdy przestaje. Autorzy twierdzą, że ten objaw jest na tyle powszechne, aby należeć do formalnych kryteriów wycofania.\n\nPodróż na trzeci dzień\nW trzecim dniu jesteś w grubej części wczesnego fizycznego szczytu, nerwowość, i niepokój są blisko ich najgorszego. Konsekwentna, przewidywalna krzywa jest samo przywracanie: te objawy mają znany przebieg i spada stąd.';

  @override
  String get marijuanaReferenceDay7 =>
      'Jeden tydzień bez Cannabis: Przez najgorsze\n\nŹródło: \"The cannabis withdrawal syndrome: current insights,\" Substance Abuse and Rehabilitation (2017), on PubMed Central\n\nGdzie jeden tydzień siedzi w zespole\nTen przegląd dokumentów, że zespół odstawienia konopi zazwyczaj trwa do około trzech tygodni, z najbardziej niepokojący okres spada między pierwszym i trzecim tygodnie. w jednym tygodniu, najwcześniejsze objawy fizyczne są niekorzystne, utrata apetytu, niepokój zwykle minął ich szczyt i są łatwe.\n\nCo jest nadal ustawianiem\nW przeglądzie wyróżnia się najostrzejsze objawy fizyczne od późniejszych psychologicznych.\n• Fizyczny dyskomfort i apetyt znacznie się poprawiają\n• Sen jest nadal zakłócony dla wielu, z żywych marzeń Remorem rebound ) często upatruje się teraz\n• Narażalność i nastrój mogą pozostać podniesione, ponieważ mają one tendencję do osiągnięcia szczytowego poziomu w ciągu pierwszych dwóch tygodni\n\nNeurobiologia regeneracji\nPod tymi zmianami w przeglądzie stwierdzono, że w ciągu około czterech tygodni abstynencji obniżone receptory CB1 powracają do normalnego funkcjonowania.\n\nWniosek\nOsiągnięcie jednego tygodnia oznacza, że ostry szczyt fizyczny jest za Tobą. Pozostałe objawy snu i nastroju są częścią zespołu z wiedzą, skończonym kursem, który nadal ustępuje w ciągu najbliższych kilku tygodni.';

  @override
  String get marijuanaReferenceDay14 =>
      'Dwa tygodnie bez Cannabisa: ostre zakończenie wycofywania\n\nŹródło: Budney, AJ et al. (2003) — peer-reviewed study on cannabis withdrawal time course\n\nWyniki badań naukowych\nWyniki wykazały, że ostry zespół odstawienny osiąga szczytowy poziom w ciągu pierwszego tygodnia i w znacznym stopniu ustępuje w ciągu 2 tygodni od zatrzymania się na większość objawów.\n\nCo rozwiązuje przez 2 tygodnie\nW badaniu udokumentowano, że do 14 dni następujące objawy w znacznym stopniu ustąpiły w uczestnikach badania:\n• Dyskomfort fizyczny i objawy ciała\n• Zaburzenia apetytu\n• Większość zaburzeń snu\n• Największa drażliwość i lęk\n\nCo może Persist po 2 tygodniach\nBadania wykazały również objawy, które utrzymywały się po dwutygodniowym oznaczeniu u niektórych użytkowników:\n• Nastrój depresyjny\n• Trudności ze koncentracją\n• Jakość snu, choć improwizacja )\n\nZnaczenie znaku 2 – tygodniowego\nPrzechodzenie przez znak dwutygodniowy jest istotne, ponieważ oznacza, że zespół ostrego odstawienia jest w dużej mierze kompletny. Wyzwania wykraczające poza ten punkt są głównie związane z długotrwałym odzyskiwaniem mózgu i zarządzaniem podstawowymi przyczynami używania konopi indyjskich, a nie ostrą odpowiedzią fizjologiczną na przerwanie leczenia.';

  @override
  String get marijuanaReferenceDay30 =>
      'Miesiąc bez Cannabisa: Poprawia funkcję pamięci\n\nŹródło: Pope et al. (2001), Archives of General Psychiatry\n\nCannabis i pamięci: Problem\nBadanie to było kontynuacją ciężkich, długotrwałych osób zażywających konopie indyjskie przez 28 dni potwierdzonej abstynencji i porównywało ich wyniki w zakresie myślenia i testu pamięci z osobami używającymi światła i nieużytkownikami. Na początku abstynencji, a także ponownie w dniach 1 i 7, ciężcy użytkownicy osiągali gorsze wyniki niż kontrole dotyczące wycofywania wyrazów, co spowodowało deficyt, który śledził ich poziom metabolitów THC w moczu, odzwierciedlający niedawne narażenie na lek, a nie jego dożywotnie użycie.\n\nDobre wiadomości: Odzyskanie do dnia 28\nDo 28. dnia, ciężkie użytkowników, lekkich użytkowników, i nie – użytkowników wykonywały praktycznie takie same w badaniach myślenia i pamięci testów. Nie było również znaczący związek między całkowitym dożywotnim zażywania konopi indyjskich i wyników testów w tym momencie.\n\nCo to oznacza w 30 dni\n• Nauka słowna i pamiętanie powróciły do poziomów grupy kontrolnej\n• Pozostałe deficyty odnotowane w pierwszym tygodniu zostały rozwiązane\n• Pozostały deficyt związany był z niedawnym ujawnieniem, a nie trwałymi szkodami.\n\nCo dowód pokazuje\nDo 28. dnia, ciężcy użytkownicy byli praktycznie nie do odróżnienia od użytkowników światła i nie – użytkowników w całej studyjnych pełny zestaw myśli i testów pamięci. Verbal- learning i pamięci deficyty widoczne w pierwszym tygodniu odzyskał do poziomu kontroli grupy.';

  @override
  String get marijuanaReferenceDay60 =>
      'Dwa miesiące bez Cannabis: Sharpens koncentracji\n\nŹródło: Roten et al. (2015), Addictive Behaviors\n\nPytanie dotyczące badań naukowych\nW tym badaniu nad zaprzestaniem stosowania konopi młodocianych, w ciągu około dwóch miesięcy, wyniki testów pamięci i myślenia były porównywane z wynikami badań moczu, porównując pacjentów, którzy w ostatnim czasie przerwali leczenie lub pozostawali abstynentami.\n\nKluczowe ustalenia\nSpójna abstynencja wiązała się ze znamienną poprawą:\n• Złożony wynik pamięci\n• Pamięć werbalna jest wyraźnie najbardziej dotkniętą domeną\n• Wydajność ruchu i prędkości reakcji\n\nW dwa miesiące\nW ciągu około ośmiu tygodni ciągłego abstynencji, pamięci i ruchu i reakcji – szybkość wyniki osiągane były znacznie powyżej, gdzie siedzieli podczas aktywnego użytkowania, śledząc ściśle z potwierdzonym non – use raczej niż sam czas.\n\nCo pokazuje badanie\nU młodzieży i młodych osób dorosłych z uzależnieniem od konopi indyjskich konsekwentna abstynencja spowodowała znaczące korzyści w zakresie pamięci złożonej, pamięci słownej oraz sprawności ruchowej i szybkości reakcji w oknach leczenia trwającego około dwóch miesięcy.';

  @override
  String get marijuanaReferenceDay90 =>
      'Trzy miesiące bez Cannabis: Nastrojowa stabilność powraca\n\nŹródło: Connor et al. (2022), Addiction — a clinical review of cannabis withdrawal\n\nJak właściwie wyglądał termin wycofania?\nPrzegląd ten opisuje objawy odstawienia konopi indyjskich zwykle rozpoczynające się 24h po zaprzestaniu leczenia i szczytujące się około dni 2x6. Anger, agresywne i depresyjny nastrój może pojawić się już w ciągu jednego tygodnia, ale zazwyczaj szczyt po około dwóch tygodniach abstynencji; zaburzenia snu w szczególności mogą trwać dłużej niż inne objawy.\n\nGdzie jest trzy miesiące.\nPrzez trzy miesiące, jesteś daleko poza udokumentowanym course wycofania: objawy zazwyczaj zaczynają się w ciągu 24 godziny48, szczyt około dni 2x6, a nawet wolniejsze nastrojów i objawów snu szczyt w ciągu następnych tygodń. dziewięćdziesiąt dni daje tych z drawal- napędzany nastroju i efektów snu miesięcy, aby ustalać.\n\nNota do systemu endocannabinoidowego\nBadania dotyczące wycofania z organizmu wykazały również, że w ciągu około czterech tygodni abstynencji, w których dochodzi do powrotu do normalnego funkcjonowania, zmniejszone normy CB1 powracają do normalnego. po 90 dniach, jesteś znacznie poza tym okienkiem regeneracyjnym.\n\nPatrząc przed siebie\nW przeglądzie omówiono również prognozę post – detoksykacji i zapobieganie nawrotom, podkreślając, że bieżące strategie wsparcia i radzenia sobie z nimi znacznie wykraczają poza ostre okno wycofania.';

  @override
  String get marijuanaReferenceDay180 =>
      'Sześć miesięcy bez Cannabis: Planowanie i decyzja - Recover\n\nŹródło: Crean, Crane & Mason (2011), Journal of Addiction Medicine\n\nPlanowanie i podejmowanie decyzji po Cannabis\nW przeglądzie tym przeanalizowano uwagę, podejmowanie decyzji, samokontrolę, zapamiętywanie pracy i płynność werbalną od pierwszych godzin po zastosowaniu przez długotrwałą abstynencję. Przez sześć miesięcy, jesteś daleko poza krótkoterminowymi skutkami i głęboko w okresie zdrowienia.\n\nCo odkryto w badaniach\nKilka problemów związanych z intensywnym stosowaniem ustępuje z trwałym abstynencją, przy czym niektóre badania wykazują poprawę do 28 dni. Najwolniejsze obszary do poprawy po ciężkim, wczesnym zastosowaniu obejmują:\n• Decyzja o podejmowaniu decyzji i podejmowanie ryzyka w sposób szczególny oznaczony jako dziedziny, w których deficyty mogą utrzymywać się w długim okresie u poważnych, przewlekłych użytkowników\n• Abstrakcyjne rozumowanie i umiejętności słowne są szczególnie osłabione u dorosłych, którzy zaczęli zażywać przed ukończeniem 17 roku życia\n\nOdzyskiwanie energii w trybie awaryjnym\nSześć miesięcy jest znacznie poza krótkoterminowymi skutkami w tej przeglądzie. Planowanie, podejmowanie decyzji, i rozumowanie nadal poprawiają się z trwałym abstynencji, czyniąc ciągłą abstynencję najsilniejszą drogą do dalszego odzyskania.\n\nSzeroki obraz\nDla cudzołóstwa, lżejsze wykorzystanie, perspektywy są bardziej korzystne dla wielu ludzi w sześć miesięcy raportować jaśniejsze myśli, bardziej zdecydowane podejmowania decyzji, i silniejsze poczucie samokierowania. największe zyski pochodzą z pozostania abstynent, zwłaszcza po ciężkim lub gorącym początku użytkowania.';

  @override
  String get marijuanaReferenceDay365 =>
      'Rok bez Cannabis: Odzyskiwanie struktury mózgu\n\nŹródło: \"Hippocampal harms, protection and recovery following regular cannabis use,\" Translational Psychiatry (2016), on PubMed Central\n\nZmiany strukturalne w wyniku stosowania konopi indyjskich\nBadanie to zbadało hipokampus, obszar mózgu centralny do zapamiętania, w obecnych użytkowników, byłych użytkowników i nieużytkowników. Obecni użytkownicy nienarażeni na CBD miał hipokamp o 11% mniejszy i marker zdrowia komórek mózgowych o 15% niższy niż kontrole. a obecnie nie są narażeni na działanie CBD.\n\nKluczowe spostrzeżenie: Odzyskanie z abstynencją\nAnaliza Curve- fishing wspierała model ochrony i odzysku. Co najważniejsze, byli użytkownicy abstynent przez średnio około 29 miesięcy nie różnili się od niestosowania kontroli w zakresie wszelkich środków integralności.Autorzy wnioskują, że związane z THC obszary pamięci szkodzą mogą być odzyskiwane z wydłużonymi okresami abstynencji.\n\nOdzyskiwanie mózgu przez rok i dłużej\nW ciągu jednego roku kanibis- wolny, system pamięci mózgów jest dobrze odzyskać: rozmiar hipocampusu i zdrowie komórek mózgowych wracają do normalnego, wspierającego pamięci i kontroli emocjonalnej.\n\nSygnał odzyskiwania\nByli użytkownicy abstynent przez około 29 miesięcy dopasowane nie – użytkowników na studys hipocampus środków zdrowotnych. W jednym roku, system pamięci już porusza się wzdłuż tej udokumentowanej ścieżki odzyskiwania w kierunku normy.';

  @override
  String get mdmaReferenceDay1 =>
      'Po MDMA: zejście\n\nŹródło: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nDlaczego czujesz się nisko?\nMDMA działa poprzez prowadzenie dużego uwalniania serotoniny z niektórymi dopaminergi. następnie mózg jest tymczasowo wyczerpany serotoniny. Przegląd ten opisuje obniżenie nastroju w tzw niebieski tydzień, że badacze zmierzyli zarówno nowicjuszy i doświadczonych użytkowników 2 do 5 dni po użyciu.\n\nCo pomaga\n• Nawodnienie i pożywna żywność\n• Śpij.\n• Cierpliwość, a dip jest wyczerpaniem, a nie trwałym stanem.\n\nZjawisko to po jednym użyciu różni się od zależności od projektu, który ten sam przegląd opisuje jako związany z pragnieniami, ale nie z istotnymi objawami fizycznymi.';

  @override
  String get mdmaReferenceDay3 =>
      'Kilka dni po MDMA\n\nŹródło: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nThe Midweek Blues\nJest to mniej więcej okno, które przegląd ten opisuje, gdy omawia midweek bluesweek Disk w nastroju mierzone 2 do 5 dni po zastosowaniu zarówno u początkujących i doświadczonych użytkowników, związane z krótkoterminowym niedoboru serotoniny, a nie długoterminowe zmiany.\n\nCo poprawia\n• Nastroje zazwyczaj podnoszą się z najniższego punktu wokół teraz\n• Zwroty energii\n• Sen zaczyna się normalizować';

  @override
  String get mdmaReferenceDay7 =>
      'Tydzień po MDMA\n\nŹródło: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nMinął półtygodniowy Blues\nDla większości ludzi, tydzień minął od 2 do 5 – dniowego okna ta recenzja kojarzy się z ostrym comedown, więc nastrój powinien być z powrotem do normalny. w recenzji zwraca uwagę, że dla osób, które używają intensywnie lub wielokrotnie, pragnienie może trwać jako część wzorca zależności, choć nie opisuje tego jako związane ze znacznymi fizycznymi objawami wycofania.\n\nKiedy szukać pomocy\nJeśli niski nastrój, niepokój, lub problemy ze snem utrzymuje się w ciągu tygodnia, to może być więcej niż comedown lub warto porozmawiać z profesjonalistą.';

  @override
  String get mdmaReferenceDay14 =>
      'Dwa tygodnie przed MDMA\n\nŹródło: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nTerminy odzyskiwania\nW przypadku jednokrotnego użycia, dwa tygodnie jest znacznie za dwu- do – 5 – dniowy dip ten przegląd dokumenty, więc mood, sen, i koncentracja powinny być stałe. Po cięższe lub powtarzające się wykorzystanie, odzyskiwanie nadal poza comedown, a abstynencyjne badania obrazowe pokazują zdolność do recyklingu serotoniny wzrasta wraz z trwałym abstynencji.\n\nCo to dla ciebie znaczy?\nJeśli twoje użycie było przypadkowe, prawdopodobnie przechodzisz przez najgorsze z nich. Jeśli było częste lub ciężkie, bądź cierpliwy, a następnie pełne odzyskanie sygnalizacji serotoninowej jest procesem dłuższym niż dwa tygodnie, objęte w następnych etapach.';

  @override
  String get mdmaReferenceDay30 =>
      'Miesiąc wolny MDMA\n\nŹródło: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" on PubMed\n\nGdzie jest jeden miesiąc\nOstre zejście i wycofanie się są dobrze za tobą, a nastrój i myślenie i pamięć są stałe. Imaging badań pokazuje MDMA zmniejsza zdolność mózgu do przetwarzania serotoniny, i że zdolność ta odzyskuje z trwałym abstynencji.\n\nSygnał odzyskiwania\nTe same badania pokazują, że zdolność do odzysku serotoniny przy długotrwałym abstynencji poprawia się w pierwszej kolejności, podczas gdy pamięć kontynuuje swoją linię czasową odzysku, a kontynuacja abstynencji podtrzymuje.';

  @override
  String get mdmaReferenceDay90 =>
      'Trzy miesiące Off MDMA\n\nŹródło: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" on PubMed\n\nKontynuacja odzyskiwania\nPrzy długotrwałej abstynencji, system serotoniny mózgu nadal odzyskuje, zwłaszcza w głębszych regionach mózgowych. nastroje i sen są zazwyczaj stabilne w tym punkcie.\n\nSygnał odzyskiwania\nTrwała abstynencja napędza kontynuację regeneracji transportera serotoniny w obrębie regionów mózgu, podczas gdy nastrój i sen pozostają stabilne, a odzysk myśli i pamięci trwa.';

  @override
  String get mdmaReferenceDay365 =>
      'Rok bez MDMA\n\nŹródło: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" on PubMed\n\nRok\nZ rok abstynencji, mózg serotoniny przetwarzania znacznie odzyskał i nastrój jest stabilny.\n\nSygnał odzyskiwania\nPełny rok abstynencji daje systemowi serotoninowemu długotrwałe okienko odzysku. Badania obrazowe pokazują, że zdolność do recyklingu serotoniny wzrasta z abstynencją, co sprawia, że znaczna regeneracja serotoniny jest najczystszym sygnałem biologicznym na tym etapie.';

  @override
  String get methReferenceDay1 =>
      'Metamfetamina Withdrawall: Pierwsze 24 godziny\n\nŹródło: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), on PubMed\n\nThe Crash\nMetamfetamina powoduje duże uwalnianie dopaminy; po zaprzestaniu stosowania, system pozostaje wyczerpany. Badanie to śledziło objawy odstawienia codziennie w ciągu pierwszych trzech tygodni abstynencji i okazało się, że ogólne nasilenie było na najwyższym poziomie w ciągu 24 godzin od ostatniego zastosowania, co spowodowało gwałtowny huśtawka od ekstremalnej stymulacji do fizycznej i psychologicznej.\n\nDzień pierwszy Objawy\nW badaniu udokumentowano funkcje wycofania, które są najbardziej intensywne teraz:\n• Nadmierne zmęczenie i wzmożony sen nadciśnienie )\n• Zwiększony apetyt amfetamina silnie hamuje apetyt )\n• Upośledzony nastrój i utrata przyjemności\n• Silne pragnienia\n• Lęk i drażliwość\n\nBezpieczeństwo fizyczne\nSam zespół odstawienia metamfetaminy nie jest zwykle zagrażający życiu, ale objawy związane z depresją mierzone w tym badaniu mogą być ciężkie i mogą obejmować myśli samobójcze.\n\nZaczyna się podnosić\nZachęcające odkrycie z tego badania: ciężkość jest najwyższa na samym początku, a następnie spada. Z tego 24 – godzinnego szczytu, objawy maleją stale w ciągu następnych dni, a najgorszym punktem jest początek.';

  @override
  String get methReferenceDay3 =>
      'Meth Withdrawall: Dzień trzeci Nadal w ostrej fazie\n\nŹródło: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), on PubMed\n\nSchodzi z szczytu\nBadanie to wykazało, że całkowita ciężkość odstawienia szczytuje się w ciągu pierwszych 24 godzin, a następnie zmniejsza się w przybliżeniu liniowy wzór w ostrej fazie około 7th 10 dni. Do dnia trzeciego jesteś poza najwyższym punktem, ale nadal mocno w ostrej fazie objawy objawy nadal widoczne, nawet gdy tendencja jest obniżona.\n\nDzień 3 Objawy\nCechy badania, które są nadal znaczące teraz:\n• Depresja i utrata przyjemności\n• Silne pragnienia\n• Trudności z koncentracją i jasne myślenie\n• Zaburzenia snu Bezsenność naprzemiennie z nadmierną senność\n• Ciągłe zmęczenie\n\nDlaczego tak się czujesz?\nNasilenie objawów związanych z depresją jest najbardziej widoczne we wczesnych dniach, ale istotne, w badaniu stwierdzono, że ogólne nasilenie odstawienia zmniejsza się do poziomu zbliżonego do poziomu kontroli do końca pierwszego tygodnia abstynencji.\n\nTo przejdzie.\nNajtrudniejszy odcinek jest pierwsze kilka dni, a dane pokazują stały spadek z tutaj. Zrozumienie tego stanu jako tymczasowy i mózg i nerw nie jest trwałe stan pomaga w przedostaniu się.';

  @override
  String get methReferenceDay7 =>
      'Tydzień bez metotreksatu: Ostra faza kończy się\n\nŹródło: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), on PubMed\n\nKoniec fazy ostrej\nJest to jeden z najbardziej zachęcających odkryć w badaniach. W badaniu stwierdzono, że ogólne nasilenie odstawienia, w tym objawy związane z depresją, które śledził znacznie obniżony do poziomu kontroli blisko końca pierwszego tygodnia abstynence.Oznaczając koniec ostrej fazy. Największa część wspinaczki jest za tobą.\n\nDwa fazy wycofania\nAutorzy opisali wycofanie mety jako:\n• Ostra faza trwająca około 7 dni, w której nasilenie objawów spada stopniowo od początku szczytu\n• Faza podostra trwająca co najmniej dwa tygodnie, z łagodnymi, utrzymującymi się objawami\n\nCo pozostało w dniu 7\nWchodząc w fazę podostrą, dominujące wyzwania mają obecnie charakter psychologiczny, a nie krytyczny:\n• Niski nastrój, choć znacznie poprawił się od pierwszych dni\n• Rzemiosła, zwłaszcza w odpowiedzi na sygnały\n• Koncentracja i pamięć wciąż się odzyskują\n• Sen wciąż usadowiony\n\nFizyczny odzysk w dół\nWraz z ostrą fazą nadwyżek apetyt powrócił, a energia powoli się buduje, gdy organizm odzyskuje działanie methor na sen, odżywianie i układ sercowo – naczyniowy.';

  @override
  String get methReferenceDay30 =>
      'Jeden miesiąc bez metamfetaminy: nastrój się stabilizuje, głód pozostaje\n\nŹródło: Zorick et al., \"Withdrawal symptoms in abstinent methamphetamine-dependent subjects,\" Addiction (2010), on PubMed Central\n\nŚledzenie pierwszych pięciu tygodni\nBadanie to było kontynuacją metamfetaminy zależnej od uczestników, którzy pozostawali abstynentami przez okres do pięciu tygodni, porównując je ze zdrowymi kontrolami, co daje niezwykle jasny obraz miejsca, w którym znajduje się ocena jednomiesięczna.\n\nCo poprawiło się przez jeden miesiąc\n• Objawy depresyjne znacznie się zmniejszyły w ciągu pierwszych 2 tygodni abstynencji do stabilnego niskiego poziomu, a do końca czterech tygodni były zbliżone, choć nie były jeszcze statystycznie dopasowane, poziom kontroli zdrowia w konsekwencji różnica zmniejszyła się do poziomu granicznego, nieistotnego trendu ).\n• Objawy psychiczne i psychotyczne osiągnęły niski poziom początkowy do końca drugiego tygodnia\nWięc w 30 dni, ciężka depresja wczesnego wycofania w dużej mierze podniosła improwizację.\n\nCo nadal się utrzymuje\nBadanie było jasne, że jeden objaw przewyższa inne: pragnienie nadal utrzymuje się na zmniejszonym poziomie przez 5 tygodni abstynencji.\n\nWniosek\nPrzez miesiąc, maszyny nastrojów mózgowych odzyskały wystarczająco, że uczucie dzień na dzień jest o wiele lepsze niż we wczesnym okresie odstawienia, podczas gdy uporczywe pragnienia są normalną częścią tej sceny, a nie oznaką niepowodzenia.';

  @override
  String get methReferenceDay90 =>
      'Trzy miesiące bez metotreksatu: Uzdrowienie rozpoczęło się jako pacjent\n\nŹródło: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nO tych badaniach\nTo przełomowe badanie mózgu śledził użytkowników metamfetaminy dwukrotnie około trzech miesięcy off amfetaminy i ponownie około 14 miesięcy, aby zobaczyć, jak system dopaminy odzyskuje.\n\nGdzie jest trzy miesiące.\nW ciągu trzech miesięcy, wczesny okres odstawienia jest długi i głębszy powrót dopaminy jest w trakcie. W tym samym badaniu później stwierdzono, że białka, które recycling dopaminy w nagrodzie mózgów i obszary ruchu wzrosła o około 16% do 19% po 12. miesiącu wolnego od met. a.\n\nCo to dla ciebie znaczy?\nPrzez 90 dni ostry odstawienie jest daleko za tobą, nastrój i sen poprawiły, a zaangażowanie w terapię staje się znacznie bardziej produktywne. Ale głębszy powrót dopaminy jest dłuższym projektem, który rozwija się w następnym roku. Jeśli motywacja i przyjemność nadal czuć się uciśnione w trzech miesiącach, to jest oczekiwane, a nie oznaki niepowodzenia w tym badaniu trajektoria jest wyraźnie w górę z tego miejsca.\n\nDlaczego to jest warte czekania\nTo samo badanie wykazało, że pozostawanie abstynentem jest tym, co napędza regenerację: im dłużej abstynencja, tym większy jest wskaźnik regeneracji DAT.';

  @override
  String get methReferenceDay180 =>
      'Sześć miesięcy bez Methol: Serce może odzyskać\n\nŹródło: \"Stopping Drug Abuse Can Reverse Related Heart Damage,\" American College of Cardiology (2017), reporting a study in JACC: Heart Failure\n\nMeta i serce\nMetamfetamina jest jednym z najbardziej kardiotoksycznych leków rekreacyjnych. może prowadzić do ciężkiego nadciśnienia tętniczego i arytmii i, z czasem, metamfetaminy związane kardiomiopatii zaostrzenie osłabienie mięśnia sercowego, które prowadzi do niewydolności serca.\n\nCo badania znaleziono\nACC zgłaszał u pacjentów z kardiomiopatią związaną z metą, u których występuje znaczne zmniejszenie funkcji pompowania serca. Centralne, pełne nadziei stwierdzenie: odstawienie leku może odwrócić uszkodzenie serca i poprawić czynność serca. Pacjenci, którzy zaprzestali leczenia, mieli znacznie lepsze wyniki niż ci, którzy kontynuowali jego stosowanie, a autorzy podkreślili, że złapanie go wcześnie może zapobiec dalszemu pogorszeniu się kardiomiopatii.\n\nDlaczego sześć miesięcy ma znaczenie\nKażdego miesiąca abstynencji usuwa trwający stres toksyczny na sercu i daje mięśniom szansę na odzyskanie. W ciągu sześciu miesięcy dałeś układ sercowo – naczyniowy zasadniczy, trwałe oderwanie od tego uszkodzenia, dokładnie stan, w którym to badanie widział poprawę.\n\nSygnał odzyskiwania\nRezultat potwierdzony dowodami jest silny: zatrzymanie mety może odwrócić uszkodzenia serca związane z metamfetaminą i poprawić funkcje serca. Sześć miesięcy bez powtarzających się stymulantów obraża serce znaczne okno rekonwalescencji.';

  @override
  String get methReferenceDay365 =>
      'Jeden rok bez method: Pomiar odzysku mózgu\n\nŹródło: Wang et al., \"Partial Recovery of Brain Metabolism in Methamphetamine Abusers After Protracted Abstinence,\" American Journal of Psychiatry (2004), on PubMed\n\nCo obrazowanie pokazuje\nW tym badaniu sprawdzono użytkowników metamfetaminy wcześnie w abstynencji i ponownie po 12. miesiącach.\n\nDobre wiadomości: Deep- Mózg i Myślenie Odzyskiwanie\nTalamuż, głęboki przekaźnik mózgu, zaczął używać energii bardziej normalnie z długotrwałym abstynencją.\n\nNagroda Circuits Odzyskiwanie wolniej\nW ciągu 12 miesięcy, głębokie centrum przekaźników mózgu odzyskał mocno i że zysk śledził z lepszym ruchu i pamięci werbalnych. Nagroda i systemy motywacyjne nadal wzmacniają się, co jednoroczny obraz jeden z głównych ożywienia w myśleniu i pamięci.\n\nCo to oznacza w ciągu jednego roku?\nW roku oczekuj mózgu, który myśli i pamięta znacznie lepiej niż we wczesnej rekonwalescencji wyraźne, wymierne uzdrowienie. Ale jeśli motywacja lub zdolność do odczuwania przyjemności nadal opóźnia się w czasie, to jest zgodne z nauką, a nie z osobistą wadą: w tym badaniu okazało się, że te obwody nagrody mogą odzyskać wolniej, z niektórych deficytów nadal występują znacznie ponad rok.';

  @override
  String get methReferenceDay420 =>
      '14 miesięcy bez metotreksatu: Zboczeńcy z markera dopaminy\n\nŹródło: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nZnalezienie nagłówka\nTo przełomowe badanie mózgu sprawdziło użytkowników mety wcześnie w abstynencji i ponownie po około 12 miesięcy. Białka, które recyklingu dopaminy wzrosła w przybliżeniu 16% do 19% w obszarach nagrody mózgów i ruchu i osiągnął poziomy, które nie różniły się znacznie od zdrowych kontroli. Dłuższa abstynencja oznaczała większą rekonwalescencję.\n\nDlaczego DAT ma znaczenie\nTe białka recyrkulują dopaminę po jej uwolnieniu. Meth ich wyczerpuje, pozostawiając układ dopaminy słabo uregulowany. Ich odbicie o około 14 miesięcy jest sensownym, mierzalnym objawem uzdrowienia.\n\nSygnał odzyskiwania\nPo upływie 12 miesięcy, białka pochodzące z recyklingu dopaminy w obszarach nagrody i ruchu wzrosły o około 16% do 19% i osiągnęły poziom kontroli zdrowia. System dopaminy jest w znacznym stopniu zmodernizowany w kierunku normy, podczas gdy myślenie, zapamiętywanie i ruch nadal się poprawiają.\n\nCo to oznacza w 14 Miesiącach\nSprzęt do układania dopaminy w sposób wymierny odzyskuje się w kierunku prawidłowej rzeczywistej przyczyny optymalizacji. Ale pełne funkcjonalne odzyskiwanie pamięci, motywacja, dobra kontrola motoryczna ) może opóźnić się za obrazem i nadal się poprawiać wraz z trwającym abstynencją.';

  @override
  String get methReferenceDay730 =>
      'Dwa lata bez method: Myślenie i nastrojenie utrzymać poprawę\n\nŹródło: Iudicello et al., \"Longer Term Improvement in Neurocognitive Functioning and Affective Distress Among Methamphetamine Users Who Achieve Stable Abstinence,\" Journal of Clinical and Experimental Neuropsychology (2010), on PubMed Central\n\nOdzyskanie, które trwa przez rok\nBadanie to było kontynuowane przez użytkowników metamfetaminy przez około 13 miesięcy i porównywano stabilne osoby wstrzymujące się od głosu z trwałymi użytkownikami i zdrowymi kontrolami. Stabilne abstynencje poprawiły ogólne myślenie i zmniejszyły rozpad emocjonalny, a zyski utrzymywały się po roku.\n\nCo poprawia\n• Ogólne myślenie u osób wstrzymujących się od głosu, które dostały się do zdrowych kontroli, podczas gdy pacjenci kontynuujący leczenie pozostawali w znacznym stopniu upośledzeni\n• Największe korzyści odnotowano w szybkości przetwarzania i zdolności motorycznej, zwłaszcza dla osób najbardziej upośledzonych na początku\n• Nastroje uległy poprawie: tylko osoby wstrzymujące się od głosu wykazały znaczącą poprawę depresji i ogólnego nastroju.\n\nSygnał odzyskiwania\nStabilni wstrzymujący się od głosu, którzy doszli do zdrowych kontroli nad ogólnym myśleniem i zgłosili mniejsze problemy emocjonalne. Uczenie się werbalne, pamięć robocza, planowanie i skupienie mogą się nadal poprawiać po pierwszym roku, tak więc tendencja regeneracji utrzymuje się w drugim roku.\n\nDwa lata w\nWiadomość oparta na dowodach: długotrwała abstynencja opłaca się w ostatnim roku, znacznie ostrzejsze myślenie, lepszy nastrój i stale poprawiająca się funkcja, nawet jeśli kilka obszarów zajmie więcej czasu, aby powrócić.';

  @override
  String get nitrousOxideReferenceDay1 =>
      'Dzień pierwszy: Gaz zniknął, ale oglądaj B12\n\nŹródło: Knuf & Maani, \"Nitrous Oxide,\" StatPearls (NCBI Bookshelf)\n\nJak szybko się rozmywa.\nPodtlenek azotu ma szybki początek działania od 2 do 5 minut i wydostaje się z organizmu tak szybko, jak tylko przestaniesz wdychać.\n\nThe Real Risk Isnreatt the Gas\nCo ważne po zaprzestaniu jest to, co powtarzające się narażenie może już zrobić. Podtlenek azotu inaktywuje syntazę metioniny, enzym, który zależy od witaminy B12. StatPearls zauważa, że wielokrotne narażenie na działanie substancji czynnej lub rekreacyjnej może prowadzić do anemii megaloblastycznej oraz zaburzeń czynności mózgu i nerwów, a w rzadkich przypadkach, degeneracji rdzenia kręgowego.\n\nJeśli używasz mocno lub często\nPodtlenek azotu jest udokumentowany, aby spowodować zespół fizycznego wycofania się, jak opioidy lub alkohol zrobić, więc dzień jeden jest o organizmie domagając się narkotyk. Itgets o rozpoczęciu zwracać uwagę na objawy związane z B12, które obejmują w najbliższych kilku etapach i sprawdzanie, czy jakiekolwiek odwołania.';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72 Gory: Brak fizycznych Poatdrawall, ale uważaj na objawy nerwów\n\nŹródło: Knuf & Maani, StatPearls; Tikaria et al. (2026), Cureus\n\nW przeciwieństwie do opioidów lub alkoholi, podtlenek azotu jest udokumentowany, aby spowodować fizyczny zespół odstawienny.\n\nUważaj na te.\nSystematyczny przegląd 1.809 rekreacyjnych przypadków podtlenku azotu Relactive Tikaria et al., 2026) stwierdzono objawy mózgu i nerwów, szczególnie mrowienie lub drętwienie obwodów ) były najczęstszym objawem szkodliwości B12, często pojawiające się nawet, gdy standardowe badania krwi wyglądają normalnie.\n\nJeśli zauważysz któreś z nich\nTen sam przegląd wykazał, że standardowe badania krwi thankhophalin, surowicy B12 ) pominęła znaczący udział chorych pacjentów badania na obecność kwasu metylmalonowego i homocysteiny są bardziej wrażliwe i należy zwrócić się specjalnie, jeśli ujawniają użycie podtlenku azotu.';

  @override
  String get nitrousOxideReferenceDay7 =>
      'Jeden tydzień: Przetestuj, jeśli używasz ciężkogłowo\n\nŹródło: Tikaria et al. (2026), \"The Toxic Legacy of Recreational Nitrous Oxide Use,\" Cureus\n\nCo dowód pokazuje\nTen systematyczny przegląd stwierdził, że niedobór witaminy B12 od podtlenku azotu jest często funkcje B12 wyglądać normalnie w przybliżeniu połowa chorych pacjentów, nawet gdy mieli prawdziwy mózg i uszkodzenia nerwów. Homocysteina i MMA były znacznie częściej anormalne 84% i 73% badanych pacjentów z szacunkiem ) i są bardziej niezawodni markerami.\n\nCo robić\nJeśli Twoje użycie było ciężkie lub częste, jeden tydzień wolnego jest rozsądnym czasem, aby zobaczyć się z lekarzem i poprosić o homocysteinę i MMA testy specjalnie nie tylko standardowy poziom B12, zwłaszcza jeśli masz jakiekolwiek mrowienie, drętwienie, problemy równowagi, lub niewyjaśnione niedociągnięcia.\n\nOdzyskiwanie mózgu jest częste po zaprzestaniu leczenia azotanami i witaminą B12: w dużych seriach klinicznych odnotowano częściową lub całkowitą poprawę w większości pacjentów, u których w ciągu pierwszych miesięcy leczenia następuje poprawa stanu zdrowia.';

  @override
  String get nitrousOxideReferenceDay14 =>
      'Dwa tygodnie: Objawy mózgowe i nerwowe Deserve Follow- Up\n\nŹródło: Tikaria et al. (2026), Cureus; Knuf & Maani, StatPearls\n\nCo zostało zgłoszone\nRaporty przypadków i serii zweryfikowane przez Tikaria et al. opisać uszkodzenia układu nerwowego związane z tlenkiem azotu przedstawiające jako straty sensoryczne, gait ataxia. i czasami osłabienie wpływające na chodzenie ustalenia, które mogą przypominać inne warunki mózgu i nerwów i są czasami pominięte, jeśli podtlenek azotu używać jest wymienione do kliniki.\n\nSygnał odzyskiwania w czasie\nAni źródło donosi, jak długo odzysk zwykle trwa po zakończeniu stosowania i wszelkie braki są traktowane. Raporty przypadków opisują szeroki zakres wyników, od pełnego odzyskania do trwałego deficytu, w zależności od tego, ile szkód miało miejsce przed diagnozą.\n\nJeśli nie miałeś pewności, że ktoś sprawdził\nDwa tygodnie wolnego jest nadal dobry czas, aby zrobić badania krwi, nawet bez objawów, szczególnie homocysteiny i MMA, a nie surowicy B12 sam.';

  @override
  String get nitrousOxideReferenceDay30 =>
      'Jeden miesiąc: Habit i Craving, Nie Fizyczna zależność\n\nŹródło: Knuf & Maani, \"Nitrous Oxide,\" StatPearls (NCBI Bookshelf)\n\nGdzie stoisz\nStatPearls nie opisuje podtlenku azotu jako produkującego syndrom uzależnienia fizycznego, więc miesiąc wolny oznacza, że wszelkie utrzymujące się potrzeby dotyczą mieszkania, spraw społecznych lub nudy, a nie ciała nadal dostosowującego się do nieobecności narkotyków.\n\nPytanie B12\nJeśli pacjent był badany i leczony z powodu niedoboru B12, jeden miesiąc jest rozsądnym punktem dla lekarza, aby sprawdzić, czy jego poziom i jakiekolwiek objawy ustąpiły.\n\nCo jest chronione?\nCo miesiąc nie używasz jest miesiąc nie dodajesz do żadnej istniejącej syntazy metioninowej inaktywacji lub ryzyko mózgu i nerwów, które pochodzi z.';

  @override
  String get nitrousOxideReferenceDay90 =>
      'Trzy miesiące: czas do Rechecky. jeśli chcesz\n\nŹródło: Tikaria et al. (2026), \"The Toxic Legacy of Recreational Nitrous Oxide Use,\" Cureus\n\nTo, co wiemy, jest jasne i bezpodstawne.\nTa baza badawcza jest zbudowana z raportów i seriali przypadków, niekontrolowanych badań odzysku, więc nie ma wiarygodnej opublikowanej linii czasowej dla tego, jak objawy rozwiązać o trzy miesiące specyficzne. co dowody pokazują, że wyniki różnią się znacznie u niektórych pacjentów z łagodnym, ciężko złapany niedobór odzyskać w pełni, podczas gdy ci z opóźnioną diagnozą lub bardziej poważne uszkodzenie nerwów może mieć trwałe powikłania.\n\nCzęść aktywna\nJeśli masz jakiekolwiek objawy mózgu i nerwów i haventect miał śledzenie badania krwi lub specjalistycznego przeglądu, trzy miesiące wolnego jest rozsądny punkt, aby to zrobić. Jeśli były leczone i improwizacji, jest to rozsądny czas, aby potwierdzić trend jest kontynuacja z lekarzem.\n\nTrzymanie się z dala od spraw\nPrzegląd jest spójny o jednej rzeczy: ciągłe narażenie utrzymuje inaktywację B12 i dodanie do ryzyka. nie używanie jest jednym największym czynnikiem w Twojej ulubionej.';

  @override
  String get nitrousOxideReferenceDay365 =>
      'Jeden rok: Najlepsza ochrona jest kontynuowana abstynencja\n\nŹródło: Knuf & Maani, StatPearls; Tikaria et al. (2026), Cureus\n\nGdzie dowody faktycznie ląduje\nŻadne źródło nie obiecuje konkretnego czasu regeneracji, a że warto być szczerym na temat literatury na temat podtlenku azotu i niedoboru B12 jest zbudowany prawie całkowicie z indywidualnych raportów przypadków, a nie długoterminowych badań następczych. Co jest dobrze ustalone jest mechanizmem: podtlenek azotu inaktywuje witaminę B12 za każdym razem, gdy jest używany, i zatrzymuje się, że trwa szkody.\n\nJeśli u pacjenta występowały objawy związane z chorobą\nRaporty przypadków opisują szeroki wachlarz wyników, od pełnego powrotu do zdrowia do trwałych objawów nerwów, w dużej mierze związanych z tym, jak wiele uszkodzeń doszło do i jak wcześnie został uleczony. Jeśli nadal doświadczasz objawów w ciągu roku, że jest to powód, aby kontynuować pracę z neurologiem, a nie znak nic nie może być zrobione, co może być kontynuowane w dłuższym okresie.\n\nCo jest pewne?\nRok bez podtlenku azotu to rok bez dalszej deaktywacji syntazy metioninowej.';

  @override
  String get opioidReferenceDay1 =>
      'Opioidalny wylot: dzień pierwszy\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nUwaga dotycząca bezpieczeństwa\nWycofanie opioidów jest rzadko śmiertelne u zdrowych osobników, ale powoduje poważne problemy fizyczne i niesie duże ryzyko nawrotu. nawrót po okresie abstynencji jest szczególnie niebezpieczny, ponieważ tolerancja spada gwałtownie przy użyciu tej samej dawki co przed abstynencją może spowodować śmiertelne przedawkowanie.\n\nPo zakończeniu leczenia\nHarmonogram wycofania WHO określa czas według typów opioidów:\n• Krótkodziałające opioidy są heroiną, oksykodonem: pojawiają się 8 godzin po ostatnim użyciu, czas trwania 4 dni\n• Długotrwałe stosowanie opioidów: początek 12- godzinny 48 godzin, czas trwania 10- dniowy 20 dni\n\nDzień pierwszy Objawy\nW wytycznych WHO wymieniono wczesne cechy opioidu z drawalem:\n• Lęk i pobudzenie\n• Skurcze mięśni i bóle mięśni\n• Wydzielina z oczu i nosa\n• Ziewanie i pocenie się\n• Insomnia, z gorącymi i zimnymi uderzeniami\n• Wczesne nudności\n\nDlaczego to takie złe?\nSystem opioidów reguluje ból, stres, samopoczucie emocjonalne, i podstawowe wygody.Długoterminowe stosowanie opioidów hamuje ciała własnej produkcji opioidów endorfinsendorfindendorfindendorfiny. Kiedy opioidy są usuwane, organizm pozostaje bez normalnego systemu komfortu doświadczając bólu, niestabilności i niepokoju na poziomie, który odzwierciedla głębokość tego tłumienia. Wytyczne WHO doradzają opiekę wspomagającą, w tym picie 2zi3 litry wody dziennie i monitorowanie 3zi4 razy dziennie.';

  @override
  String get opioidReferenceDay7 =>
      'Tydzień bez opioidów: Największe objawy zmniejszające się\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nSzczyt i spadek\nHarmonogram WHO przewiduje, że krótkotrwałe wycofanie opioidów następuje po upływie 10 dni, a objawy rozwijają się wcześnie, a następnie ustępują w całym oknie.\n• Wymioty i biegunka w znacznym stopniu ustąpiły\n• Skurcze mięśni są mniej ciężkie.\n• Strach fizyczny jest znacząco zmniejszony.\n\nCo pozostało w dniu 7\nPodczas gdy ostre objawy fizyczne ulegają poprawie, nadal istnieją istotne wyzwania:\n• Bezsenność zaburzenia snu jest jednym z najbardziej trwałych objawów odstawienia opioidów\n• Upośledzony nastrój i emocjonalne wzdęcia\n• Zmęczenie i osłabienie\n• Zachcianki\n• Lęk\n\nOstre odstawienie leku\nPo pierwszym okresie odstawienia, problemy ze snem, zmiana nastroju i fale pożądania mogą trwać tygodniami lub miesiącami.\n\nLeczenie opioidowe agonistyczne\nWytyczne WHO opisują metadon i buprenorfinę jako skuteczne leczenie zmniejszające nasilenie odstawienia i wspomagające odzyskiwanie. Leki te również zmniejszają śmiertelność z powodu zaburzeń związanych z zażywaniem opioidów, a wiele osób w długotrwałym, udanym leczeniu, stosuje je przez cały okres wczesnego powrotu do zdrowia.';

  @override
  String get opioidReferenceDay14 =>
      'Dwa tygodnie poza opioidami: Wzory snu zaczynają poprawiać\n\nŹródło: Peer-reviewed pharmacology research on opioids and sleep\n\nPołączenie opioid- Sleep\nDokument ten bada dwukierunkowy związek między zażywaniem opiatów a zaburzeniami snu.\n• Tłumienie spowalniającej się fali głębokości ) snu\n• Zakłócenie snu REM\n• Powodując zaburzenia snu oddychanie\n• Zakłócanie regulacji rytmu okołokręgowego\n\nA Vicious Cycle\nBadania uwydatniają dwukierunkowy charakter problemu: zażywanie opioidów zakłóca sen, a słaby sen zwiększa wrażliwość na ból i pragnienie, prowadząc do dalszego zażywania opioidów. Łamanie uzależnienia od opioidów oznacza również przerwanie cyklu zakłócania snu.\n\nSen w dwóch tygodniach\nDo 14 dni abstynencji opioidowej, sen zaczyna się normalizować:\n• Środkowy bezdech senny, jeśli występuje ) ustępuje w ciągu dni\n• Deep slow – wave sen zaczyna odzyskiwać\n• REM sen wraca do normalnego proporcji\n• Początek snu staje się bardziej niezawodny\n\nSen pozostaje istotnym wyzwaniem dla wielu osób w ciągu dwóch tygodni, ale trajektoria jest wyraźnie poprawiająca. Lepszy sen bezpośrednio poprawia nastrój, zmniejsza strach i wspiera jasne myślenie potrzebne do odzyskania.';

  @override
  String get opioidReferenceDay30 =>
      'Miesiąc Off Opioids: Myślenie i pamięć Rozpoczynają rekonwalescencję\n\nŹródło: Mayo Clinic\n\nZrozumienie zaburzenia stosowania opioidów\nKlinika Mayo wyjaśnia, że opioidy łączą się z receptorami w całym mózgu i ciele, wytwarzając leki przeciwbólowe, euforię i senność.\n\nMyślenie i pamięć w jednym miesiącu\nW ciągu 30 dni nastąpiła znacząca regeneracja myślenia i pamięci. Najgorsza mgła mózgu została oczyszczona, a przednia część mózgu, która zajmuje się planowaniem i samokontrolą odzyskuje:\n• Poprawia się proces podejmowania decyzji\n• Pamięć robocza odzyskuje pamięć.\n• Zwiększenie prędkości przetwarzania\n• Koncentracja bardziej niezawodna\n\nSystem Endorphin\nW ciągu jednego miesiąca naturalny system endorfiny mózgu aktywnie odzyskuje się: produkuje więcej własnych substancji chemicznych opioidowych i reaguje bardziej normalnie.\n\nZapobieganie nawrotom\nKlinika Mayo podkreśla, że jeden miesiąc trzeźwości nie oznacza, że ryzyko nawrotu ustąpiło. Tolerancja znacznie spadła, co oznacza, że nawrót przy użyciu poprzednich dawek niesie ze sobą poważne ryzyko przedawkowania.';

  @override
  String get opioidReferenceDay60 =>
      'Dwa miesiące poza opioidami: Brainhates Stress Circuits zaczynają się uspokajać\n\nŹródło: \"Neuroplasticity of the extended amygdala in opioid withdrawal and prolonged opioid abstinence,\" Frontiers in Pharmacology (2023)\n\nGdzie negatywne uczucia pochodzą z\nW przeglądzie przedstawiono, w jaki sposób długotrwałe zażywanie opioidów zmienia stres mózgu i obwody lękowe. W trakcie drawalskiego działania obwody te stają się nadpobudliwe, podczas gdy dopaminowe sygnalizacja w obwodach nagrody spada.\n\nDlaczego dwa miesiące przynosi ulgę\nW szczególności, przegląd dokumentuje, że niektóre z tych zmian są odwracalne. W modelach zwierzęcych utrata gęstości kręgosłupa w powłoce akumulatora jest opisana jako trwałe, ale odwracalne, powrót do wartości pre- lek w ciągu kilku tygodń. jak te obwody stresu i nagrody reregulator, mechanistyczna podstawa do intensywnego odzyskiwania zaburzeń emocjonalnych współzależności ze zmniejszoną reaktywności i stabilniejszy nastrój wielu ludzi raportować przez około dwóch miesięcy.\n\nSygnał odzyskiwania\nOdwracalne zmiany gęstości i obwodu stresowego udokumentowane w niniejszej literaturze pokazują prawdziwy proces biologicznego odzysku: obwody prowadzące do negatywnego stanu uzależnienia emocjonalnego wracają do stanu przednarkotykowego podczas abstynencji.';

  @override
  String get opioidReferenceDay90 =>
      'Trzy miesiące Off Opioids: Chemia nagrodzona zaczyna odzyskać\n\nŹródło: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies,\" Drug and Alcohol Dependence (2022), on PubMed Central\n\nDopamina i opioidy\nOpioidy powodują uwalnianie dopaminy w systemie nagród mózgowych. Długotrwałe stosowanie pozostawia wyczerpany system: w jednym badaniu skanowania mózgu, białka, które recycling dopaminy były o 30% poniżej zdrowych poziomów na początku. To pomaga wyjaśnić utratę przyjemności obserwowaną w zaburzeniach zażywania opioidów i wczesnego odzyskiwania.\n\nOdzyskanie jest stopniowe\nW tym przeglądzie zebrano badania podłużne, które ponownie przeskanowały tych samych ludzi nad abstynencją. Deficyt transportera dopaminy odzyskany o około 20% w ciągu 6 miesięcy abstynencji, a niektóre nieprawidłowości w stosunku do materii szarej i białej widoczne we wczesnym odstawieniu nie były już wykrywalne po około miesiącu. W trzech miesiącach jesteś na początku tej krzywej regeneracji: nagrody i przednich układów są wymiernie prawidłowe, ale nie zostały zakończone.\n\nCo ludzie doświadczają\nGdy te obwody odzyskują się, wiele osób w około 90 dni zauważą:\n• Bardziej prawdziwe korzystanie z działalności, żywności i relacji\n• Zmniejszone pragnienie w porównaniu z wczesną regeneracją\n• Jasniejsze myślenie i lepsze podejmowanie decyzji\n\nSygnał odzyskiwania\nLongitudinal ludzkiego obrazowania pokazuje dostępność transportera dopaminy rośnie w ciągu 6 miesięcy abstynencji, podczas gdy przedni - i biało- nieprawidłowości materii zaczyna normalizować dużo wcześniej. W 90 dni, mierzalne odzyskanie mózgu jest już ustalone.';

  @override
  String get opioidReferenceDay180 =>
      'Sześć miesięcy Off opioids: System immunologiczny zaczyna odzyskać\n\nŹródło: \"Effects of opioid tolerance and withdrawal on the immune system,\" Journal of Neuroimmune Pharmacology (2006), on PubMed\n\nOpioidy i układ immunologiczny\nPrzegląd ten pokazuje, że długotrwałe zażywanie opioidów osłabia układ odpornościowy na kilka sposobów:\n• Bezpośrednie działanie opioidów na komórki immunologiczne\n• Uszkodzone chemikalia sygnalizacji immunologicznej\n• Przerwanie osi HPA- hipogłębokowodnego nadnercza\n• Zwiększona wrażliwość na zakażenia\n\nSygnał odzyskiwania\nDługoterminowe opioidy tłumią kilka części układu immunologicznego. W ciągu sześciu miesięcy od podania opioidów, że stała tłumienie nie było przez pół roku i funkcje immunologiczne aktywnie odbudowuje się w kierunku normy.\n\nCo oznacza sześć miesięcy\nSześć miesięcy bez opioidów daje komórki odpornościowe, sygnalizacja immunologiczna, a organizm system stresu utrzymywał czas do powrotu do normy.\n\nDlaczego to wciąż ma znaczenie?\nMa to szczególne znaczenie dla osób, które wstrzyknęły opiaty, które borykają się z dodatkowym ryzykiem zakażenia, takim jak HIV i wirusowe zapalenie wątroby typu C. Usuwanie opiatów, poprawa odżywiania oraz utrzymanie abstynencji, co daje systemowi odpornościowemu warunki, które muszą być utrzymane.';

  @override
  String get opioidReferenceDay365 =>
      'Rok Off Opioids: Struktura mózgu i chemia Odzyskiwanie\n\nŹródło: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies,\" Drug and Alcohol Dependence (2022), on PubMed Central\n\nCo pokazuje ludzki obraz\nW przeglądzie tym zebrano badania, w których więcej niż jeden raz przebadano te same osoby z zaburzeniami zażywania opioidów w całej abstynencji.\n• Białko pochodzące z recyklingu dopaminy w obszarach wynagradzania i przemieszczania, o około 30% poniżej normy na początku, wzrosło o około 20% w ciągu 6 miesięcy w przypadku opioidów.\n• Po około miesiącu abstynencji, u których wystąpiły nieprawidłowości w stosunku do przedniego układu grejpfrutowego, nie wykrywano już wcześniej nieprawidłowości w zakresie przedniego układu grejpfrutowego występującego we wczesnym okresie odstawienia.\n• Biała materia przednia i kłykciowa ) i restygująca aktywność czołowa również zaczęły się ponownie normalizować w ciągu pierwszego miesiąca\n\nGdzie siedzi jeden rok\nW ciągu dwunastu miesięcy jesteś w najdłuższym oknie tych badań. układ dopaminy miał najwięcej czasu do odzyskania, a obwody czołowe, które wspierają samokontrolę i osąd są naprawiane od miesięcy w biologicznym odpowiedniku jaśniejszych myśli, słabszych rzemiosła i bardziej stabilnych ludzi nastroju opisują w roku.\n\nSygnał odzyskiwania\nW ciągu roku, ludzki sygnał obrazowania jest silnie regenerowany: dostępność transportera dopaminy wzrosła w ciągu 6 – miesięcznego okna, podczas gdy zmiany struktury czołowej i funkcjonalnej miały wiele miesięcy do normalizacji.';

  @override
  String get opioidReferenceDay730 =>
      'Dwa lata Off Opioids: stabilna Fundacja\n\nŹródło: \"Treatment of Opioid Use Disorder,\" Centers for Disease Control and Prevention (CDC)\n\nPrzewlekłe warunki, zarządzane dobrze\nCDC opisuje zaburzenia zażywania opioidów jako przewlekłą chorobę, która może wpływać na jakiekolwiek schorzenie, a nie na moralne niepowodzenie. Osiągnięcie dwóch lat trwałej rehabilitacji oznacza, że z powodzeniem zarządzałeś tym schorzeniem przez jeden z jego najbardziej wrażliwych okresów.\n\nCo CDC mówi, że działa\nOśrodki naprowadzania CDCZRED na zabiegi, które utrzymują stabilność odzysku w długim okresie:\n• Leki stosowane w leczeniu zaburzeń opioidowych: buprenorfina, metadon i naltrekson, które to leki są szczególnie skuteczne\n• Łączenie leków z terapią behawioralną i doradztwem\n• Leczenie, które trwa przez różne długości czasu, dostosowane do osoby\nCDC zauważa, że te leki pomagają poprawić chemię mózgu i łagodzić pragnienia, co chemia, która czuła się porwana w aktywnych uzależnień działa z tobą ponownie.\n\nPozostawanie bezpieczne\nCDC zachęca ludzi w rekonwalescencji, aby zapytali lekarza o ryzyko powrotu do stosowania i przedawkowania, i aby utrzymać nalokson w ręku. Tolerancja spada podczas abstynencji, więc powrót do opioidów po tak długim czasie jest szczególnie niebezpieczny wiedząc, że jest to część ochrony tego, co ty budujesz.\n\nDwa lata w\nCDC jest jasne, że ożywienie jest często procesem długoterminowym, a nie metą. Dwa lata nie jest końcem podróży, jest to stabilna, zdrowa fundacja i mocne dowody, że podejście używasz pracy.';

  @override
  String get pornographyReferenceDay1 =>
      'Dzień pierwszy: Odzyskiwanie kontroli\n\nŹródło: Kraus et al., Compulsive sexual behaviour disorder in the ICD-11, World Psychiatry (2018).\n\nProblemem o znaczeniu klinicznym nie jest samo korzystanie z pornografii. Kompulsywne zaburzenia zachowania seksualnego jest definiowane wokół trwałych trudności w kontrolowaniu powtarzających się zachowań seksualnych, gdy ten wzór powoduje znaczne problemy lub upośledzenie.\n\nTo sprawia, że dzień jeden konkretny, a nie mistyczny: przerwałeś zachowanie, które zdecydowałeś, że jest poza kontrolą. Jeden zakończony dzień nie udowadnia przesiedlenia mózgu i nerwów, ale daje pierwszą rzeczywistą obserwację, kiedy apel, jakie sytuacje je wywołują i co można zrobić.\n\nJeśli Twoje użycie nie było uciążliwe, osłabione lub trudne do kontrolowania, kliniczne ramy CSBD mogą nie mieć zastosowania do Ciebie. Te kamienie milowe są skierowane do ludzi, którzy celowo zmieniają problematyczne lub kompulsywne wykorzystanie.';

  @override
  String get pornographyReferenceDay3 =>
      'Dzień trzeci: Wiesz, jak może wyglądać urga\n\nŹródło: Lewczuk et al., Withdrawal and tolerance as related to compulsive sexual behavior disorder and problematic pornography use, Journal of Behavioral Addictions (2022).\n\nW uprzednio zarejestrowanej, reprezentatywnej na poziomie krajowym próbie 1541 dorosłych, silniejsza samoocena z podobnymi do drawali doświadczeniami wiązała się z większą odpowiedzialnością CSBD i brakiem bezpieczeństwa, brakiem pornografii. Wśród uczestników problematycznych zastosowań pornografii, powszechnie opisywane doświadczenia obejmowały trudności z zatrzymaniem seksualnych myśli, trudną do kontrolowania potrzeb, zwiększoną pobudzającą, drażliwą, zmiany nastroju i problemy ze snem.\n\nRestlessess, natrętne myśli seksualne, silne urgesy i drażliwość są udokumentowane u osób z cięższymi problematycznych użytkowników. jeśli pojawiają się około dnia trzy, traktować je jako prawdziwy z drawal- podobny wzór i zarządzać wyzwalania.\n\nNapisz, które potrzeby są rzeczywiście dzieje, co ich poprzedziło, a co im pomogło. Odzyskiwanie łatwiej sterować, gdy wyzwalacz jest nazwany, a nie traktowane jako tajemniczy przypadek mózgu.';

  @override
  String get pornographyReferenceDay7 =>
      'Jeden tydzień: Co randomizowane badanie abstynencji znaleziono\n\nŹródło: Effects of a 7-Day Pornography Abstinence Period on Withdrawal-Related Symptoms in Regular Pornography Users, Archives of Sexual Behavior (2023).\n\nNaukowcy randomizowali 176 regularnych użytkowników pornografii, aby spróbować 7 dni abstynencji lub kontynuować jak zwykle. W całym zestawieniu abstynencja nie spowodowała znaczącego ogólnego wzrostu rzeźni, negatywnego nastroju lub objawów odstawienności. abstynencja nie powodowała znaczącego ogólnego wzrostu rzeźni, negatywnych zachowań lub objawów abstynencji.\n\nAnaliza rozpoznawcza wykazała zwiększone pragnienie wśród osób, które łączyły wysokie wyniki z wykorzystaniem problemów z codziennym wykorzystaniem pornografii przed badaniem. Ten wynik wymaga powielania, ale jest to przydatne: trudny pierwszy tydzień może być prawdziwy dla cięższych użytkowników problematycznych, podczas gdy uniwersalny syndrom wycofania pornografii nie jest wspierany przez ten proces.\n\nJeśli przeżyłeś tydzień, masz teraz lepsze dowody na swój własny wzór, niż jakikolwiek ogólny harmonogram internetowy może zapewnić.';

  @override
  String get pornographyReferenceDay14 =>
      'Dwa tygodnie: Mapa Triggers, które faktycznie ważne\n\nŹródło: Biopsychosocial Determinants of Problematic Pornography Use: A Systematic Review (2023).\n\nPrzegląd ten zsyntetyzował 66 badań i stwierdził, że problematyczne korzystanie z pornografii wiąże się z mieszanką czynników, a nie jednego prostego mechanizmu dopaminowego. Wielokrotnie zidentyfikowane czynniki psychologiczne i społeczne obejmowały rzemiosło, stres, unikanie, samotność, samotność, negatywne przekonania i styl radzenia sobie.\n\nDwa tygodnie daje powtarzające się narażenie na dni tygodniowe, tygodniowe, boredom, stres, prywatne, urządzenia, i inne konteksty, które mogły przykuć stare zachowania. użyj, że data. Jeśli stres jest wyzwalaczem, projektować reakcję na stres. Jeśli samotność jest wyzwalaczem, dodać stykact. Jeśli łatwy dostęp jest wyzwalaczem, zmienić środowisko.\n\nDowody wspierają pracę nad czynnikami problematycznego wykorzystania; nie wymaga to udawania, że każda osoba podąża za tym samym biologicznym odliczeniem.';

  @override
  String get pornographyReferenceDay30 =>
      'Jeden miesiąc: Sterowanie ma więcej znaczenia niż prosta liczba częstotliwości\n\nŹródło: Bőthe et al., Are sexual functioning problems associated with frequent pornography use and/or problematic pornography use?, Addictive Behaviors (2021).\n\nW próbie 14 581 dorosłych, problematyczne korzystanie z pornografii miało umiarkowany pozytywny związek z seksualnie funkcjonującymi problemami zarówno u mężczyzn, jak i u kobiet. Częstotliwość stosowania pornograficznego sama w sobie wykazywała słabe negatywne powiązanie z tymi problemami.\n\nTo rozróżnienie ma znaczenie. Dowody nie potwierdzają, że każdy użytkownik pornografii, że tylko oglądanie częstotliwości niszczy funkcje seksualne. Bardziej klinicznie istotnym celem jest utrata kontroli i problemy wokół tego wzorca.\n\nW jednym miesiącu, porównać życie teraz, gdy rozpoczęliście: zajęcia, czas utracony, zdolność do zatrzymania, funkcje seksualne, konflikty relacji i trudności. Te zmiany mają znaczenie więcej niż czekanie na mityczny dzień – 30 przesiedlenia mózgu.';

  @override
  String get pornographyReferenceDay90 =>
      'Trzy miesiące: trwała zmiana jest możliwa\n\nŹródło: Crosby & Twohig, Acceptance and Commitment Therapy for Problematic Internet Pornography Use: A Randomized Trial, Behavior Therapy (2016).\n\nTen mały randomizowany test porównał 12 – sesyjny program ACT z listy oczekujących w 28 dorosłych mę. pornograficzne oglądanie spadła znacznie więcej w grupie ACT pod koniec leczenia, a znaczne redukcje pozostały na trzy miesiące po -up.\n\nBadanie nie dowodzi, że 90 dni abstynencji powoduje te same wyniki, a jego próbka była niewielka i demograficzna wąsko. co pokazuje jest istotne: problematyczne stosowanie pornografii jest modyfikowalne, a ustrukturyzowane umiejętności mogą powodować zmiany, które utrzymują się poza okresem natychmiastowego leczenia.\n\nJeśli twój postęp nadal zależy głównie od białych – knuckling, trzy miesiące jest dobrym punktem, aby wzmocnić system wokół niego: plany aktywacji, akceptacja impulsów bez działania, szczelina środowiska, rozliczalność, i terapia, gdy potrzebne.';

  @override
  String get pornographyReferenceDay180 =>
      'Sześć miesięcy: Długoterminowa kontrola objawów może utrzymać\n\nŹródło: Hallberg et al., A Randomized Controlled Study of Group-Administered Cognitive Behavioral Therapy for Hypersexual Disorder in Men, Journal of Sexual Medicine (2019).\n\nU 137 mężczyzn z niekontrolowanym zachowaniem seksualnym, siedem tygodni w grupie CBT powodowało większe zmniejszenie objawów hiperseksualnych i kompulsywności seksualnej niż kelnera, wraz z poprawą samopoczucia psychicznego. Zyski z leczenia pozostawały na stałym poziomie zarówno po trzech, jak i sześciu miesiącach.\n\nBadanie to obejmowało zaburzenia hiperseksualne, a nie abstynencję pornograficzną, dlatego nie powinno się przekształcać w twierdzenie, że każda osoba jest biologicznie odzyskiwana w ciągu sześciu miesięcy.\n\nSześć miesięcy jest więc kamień milowy konserwacji. Zachować procedury, które ułatwiły kontrolę zamiast traktować datę jako pozwolenie na demontaż ich.';

  @override
  String get pornographyReferenceDay365 =>
      'Jeden rok: Dowody na trwałą zmianę zachowania\n\nŹródło: One-year follow-up effects of an acceptance-based treatment for hypersexuality (2026).\n\nPo upływie roku uczestnicy tego badania nie powrócili do poziomu hiperseksualności przed leczeniem. Autorzy opisali wyniki jako wstępne dowody trwałych, klinicznie istotnych korzyści, z postrzeganą kontrolą nad pożądaniem wśród procesów, które następują z upływem czasu.\n\nJest to dowód na kontynuację leczenia, a nie dowód jednorocznego przesiedlenia mózgów. Znaczne twierdzenie jest lepsze w każdym razie: klinicznie istotna kontrola może trwać przez rok, a nie znikać jak tylko skończy się pierwsza interwencja.\n\nRok własnych utrzymanych zmian jest również dużą osobistą dataset. Porównaj bieżące kontrole, stres, funkcje, relacje, i wykorzystanie czasu tam, gdzie rozpoczął; są to wyniki, które mają znaczenie klinicznie.';

  @override
  String get pornographyReferenceDay1825 =>
      'Pięć lat: Długoterminowa kontrola jest wynikiem\n\nŹródło: Compulsive sexual behavior disorder and problematic pornography use: a comprehensive interdisciplinary expert-informed review (2026).\n\nNowoczesne recenzje traktują CSBD i problematyczne pornografię jako złożone problemy z kontrolą, depresją, funkcjami, context i indywidualnymi różnicami.\n\nAle pięć lat nie jest pusty kamień milowy. To 1825 dni utrzymania kierunku behawioralnego, który wybrałeś. Ponieważ problem kliniczny jest uporczywa utrata kontroli z niepokoju lub upośledzenia, trwała kontrola i przywrócone funkcjonowanie przez lata są znaczące wyniki w ich własnym zakresie.\n\nNa tym etapie, przydatne pytanie nie jest już, czy twój mózg osiągnął fikcyjny procent rewirowania. To jest, czy stary wzór nadal kontroluje swoje wybory lub zakłóca życie chcesz. Jeśli nie, to jest to istotny sukces długoterminowy.';

  @override
  String get smokingReferenceDay1 =>
      'Dzień pierwszy: Korzyści zaczynają się teraz\n\nŹródło: NHS Better Health\n\nKorzyści zaczynają się w ciągu kilku minut.\n\nCo się dzisiaj stanie?\n• 20 minut: Puls zaczyna powracać do normy\n• 8 godzin: tlenek węgla we krwi spada o połowę; poziom tlenu odzyskuje\n• 48 godzin: tlenek węgla spadł do poziomu niepalącego\n\nTlenek węgla wiąże się z czerwonymi krwinkami silniej niż tlen, usuwając go z krwi.\n\nWycofanie rozpoczyna się pierwszego dnia\n• Zachcianki zaostrzające każdy zwykle trwający 3zaostrzenia 5 minut\n• Narażalność i trudności z koncentracją\n• Zwiększony apetyt\n\nProgram NHS Better Health oferuje bezpłatne wsparcie, w tym aplikacje i doradztwo farmaceutyczne.';

  @override
  String get smokingReferenceDay3 =>
      'Dzień trzeci: Wycofanie się na szczyt\n\nŹródło: McLaughlin, Dani & De Biasi\n\nW ciągu 72 godzin, nikotyna zniknęła z ciała. Mózg zbudował dodatkowe receptory nikotyny w czasie palenia lat; teraz są one niedostymulowane, powodując zespół odstawienia.\n\nObjawy szczytowe\n• Pragnienia najbardziej intensywne teraz\n• Niepokój, frustracja, niepokój\n• Trudności z koncentracją\n• Lęk\n• Bóle głowy\n• Zwiększony apetyt\n• Kaszlowanie dróg oddechowych oczyszczajacych dobre znaki )\n\nTo najtrudniejszy dzień.\n\nNRT, wareniklinen i bupropion znacząco zmniejszają nasilenie odstawiennictwa w tym stadium.';

  @override
  String get smokingReferenceDay7 =>
      'Jeden tydzień: smak i zapach powrót\n\nŹródło: NHS Better Health\n\nOsiągnięcie jednego tygodnia wolnego od dymu jest silnym przewidywaczem długotrwałego sukcesu ludzi, którzy przechodzą przez pierwszy tydzień są o wiele bardziej prawdopodobne, aby zrezygnować na dobre.\n\nCo odzyskano?\n• Jedzenie smakuje bardziej smakowicie\n• Pachnie bardziej żywo.\n• Oddech jest łatwiejszy, a drogi oddechowe są czyste.\n• Krążenie się poprawia\n• Skóra jest lepiej nawodniona.\n\nUszkodzenia dymne bezpośrednio wywołują smak i zapach receptorów; w ciągu kilku dni od zatrzymania, zaczynają się odzyskiwać.\n\nOstre wycofywanie nikotyny jest łatwe. Zachcianki fizyczne są krótsze i mniej częste. Zachcianki oparte na wyzwalaniu może być nadal obecny, ale najgorsze z fizycznej pilności jest za tobą.';

  @override
  String get smokingReferenceDay14 =>
      'Dwa tygodnie: Poprawa cyrkulacji\n\nŹródło: NHS Better Health\n\nW ciągu 2 tygodni od zatrzymania, krążenie krwi poprawia. Nikotyna zawęża naczynia krwionośne z każdym lekiem; bez niego, naczynia rozkurczają się i krew płynie bardziej niezależnie.\n\nCo to znaczy?\n• Przepływ krwi do rąk, stóp i tkanek obwodowych poprawia\n• Wiele osób zauważa cieplejsze ręce i stopy\n• Spacery i wspinaczki zaczynają czuć się łatwiej\n\nZ tlenku węgla już oczyszczone z krwi w pierwszym dniu i poprawa krążenia teraz, tlen dociera do mięśni bardziej efektywnie.\n\nCilia podszewka dróg oddechowych są rekonwalescencji i wypychanie z built- up śluzu. Jeśli jesteś kaszel więcej niż zwykle, to jest oznaką rekonwalescencji, a nie setback.';

  @override
  String get smokingReferenceDay30 =>
      'Jeden miesiąc: Wspinaczka funkcji płuc\n\nŹródło: NHS Better Health\n\nOddychanie staje się łatwiejsze i funkcje płuc poprawia się do 10% w ciągu 3 do 9 miesięcy okna. W jednym miesiącu, dobrze do tego powrotu krzywej.\n\nCo dzieje się w płucach\n• Cilia odrasta się i czyści śluz bardziej skutecznie\n• Zapalenie dróg oddechowych ustępuje.\n• Uporczywy kaszel z wędzarni zanika.\n• Tolerancja ćwiczeń poprawia się\n\nKażdy kaszel, świszczący oddech i problemy z oddychaniem poprawiają się wraz ze wzrostem czynności płuc.';

  @override
  String get smokingReferenceDay90 =>
      'Trzy miesiące: Zrzut ryzyka ataku serca\n\nŹródło: PMC — Cardiovascular Effects of Smoking and Cessation (2024)\n\nPalenie szkodzi sercu i tętnicom w wielu sposobów: przyspiesza nagromadzenie tętnicy, promuje zatkanie krwi, podnosi ciśnienie krwi, i uszkodzenia błony tętniczej. Prokoagulant, efekt promulant – promocyjne odwrócenie w ciągu kilku dni od zatrzymania, i ten przegląd donosi o znaczącym spadku zawału serca i udarów w ciągu pierwszego roku quitting.\n\nCo poprawiło się do tej pory\n• Czynniki krzepnięcia krwi normalizują się\n• Ciśnienie krwi i tętno stabilizują się\n• Najostrzejszy wczesny spadek ryzyka ostrych zdarzeń sercowo – naczyniowych jest w dobrej formie.\n\nKorzyści powolne działania cofania lat nagromadzenia płytki tętniczej trwa dłużej i są pokryte w późniejszych kamieni milowych. każdy wolny od dymu miesiąc dodaje do odzyskiwania.';

  @override
  String get smokingReferenceDay180 =>
      'Sześć miesięcy: komórki odpornościowe płuc wracają do formy\n\nŹródło: Smoke-free period and recovery of alveolar immune-cell function (PubMed)\n\nPalenie może osłabiać makrofagi pęcherzykowe — komórki odpornościowe głęboko w płucach, które pochłaniają i zabijają bakterie.\n\nCo mierzono\nBadacze porównali 15 osób nigdy niepalących, 15 aktualnych palaczy i 41 byłych palaczy, którzy w czasie znieczulenia ogólnego nie palili od 2 miesięcy, 3–5 miesięcy lub 6–12 miesięcy.\n\nKonkretny sygnał regeneracji\nPodczas znieczulenia spadek fagocytozy i aktywności bakteriobójczej makrofagów pęcherzykowych był 1,5–3 razy większy u aktualnych palaczy i osób po dwóch miesiącach bez palenia niż u osób nigdy niepalących. Po 3–12 miesiącach bez palenia odpowiedzi przeciwdrobnoustrojowe były bliższe wzorcowi osób nigdy niepalących niż po dwóch miesiącach.\n\nSygnalizacja zapalna wracała do normy wolniej; różnice w odpowiedziach cytokin były widoczne do sześciu miesięcy. Sześć miesięcy to prawdziwy etap regeneracji odporności płuc, a poprawa trwa dalej.';

  @override
  String get smokingReferenceDay365 =>
      'Jeden rok: Atak serca ryzyko spada Sharply\n\nŹródło: PMC — Smoking Cessation and Stroke Outcome; CDC, Benefits of Quitting Smoking\n\nPalenie z grubsza podwaja ryzyko udaru poprzez promowanie budowy tętnic, zwiększenie zatkania krwi, zwiększenie ciśnienia krwi, i uszkodzenia mózgu wessels. CDCREY własne quitting- korzyści osi czasu stawia ostry spadek ryzyka ataku serca na 1 – do – 2 – rok znak rozpoznawczy yougeure na przedniej krawędzi tego okna.\n\nTerminy odzyskiwania\nPełna normalizacja ryzyka wystąpienia udaru trwa dłużej: w cytowanym badaniu dotyczącym udaru nastąpiło ustąpienie objawów średnio przez prawie pięć lat, aby wykazać znacznie niższy wskaźnik udaru niż w przypadku palenia w dalszym ciągu, a dane CDC wskazują na zmniejszenie o połowę ryzyka choroby wieńcowej o 3 do 6 lat, przy czym ryzyko udaru mózgu spadło w okresie od 5 do 10 lat.\n\nRok to wciąż prawdziwy medyczny kamień milowy, a najsilniejsza część spadku ryzyka jest za tobą, mimo że długoterminowe korzyści z chorób układu krążenia i raka nadal rosną przez lata.';

  @override
  String get smokingReferenceDay1825 =>
      'Pięć lat: zaczynają się wielkie korzyści dotyczące ryzyka nowotworów\n\nŹródło: CDC, Benefits of Quitting Smoking\n\nPięć lat oznacza wejście w ważny okres wyraźnego spadku ryzyka.\n\nKamienie milowe 5–10 lat\n• Dodatkowe ryzyko nowotworów jamy ustnej, gardła i krtani: spada o połowę\n• Ryzyko udaru: maleje\n\nJeszcze przed Tobą\n• Około 10 lat: maleje ryzyko raka pęcherza, przełyku i nerki\n• 10–15 lat: dodatkowe ryzyko raka płuca spada o połowę\n• 15 lat: ryzyko choroby wieńcowej zbliża się do poziomu osoby niepalącej\n• 20 lat: ryzyko nowotworów jamy ustnej, gardła i krtani zbliża się do poziomu osoby niepalącej; dodatkowe ryzyko raka szyjki macicy spada mniej więcej o połowę\n\nPięć lat bez palenia to ogromny kamień milowy — docierasz do okresu, w którym zaczynają się duże spadki ryzyka nowotworów i udaru, a kolejne wielkie korzyści są jeszcze przed Tobą.';

  @override
  String get snriReferenceDay3 =>
      'Przerwanie stosowania SNRI: pierwsze dni\n\nŹródło: Harvard Health Publishing\n\nWażna uwaga dotycząca bezpieczeństwa\nSNRI należy zaprzestać tylko pod nadzorem lekarza po stopniowym zmniejszaniu. Venlafaxine Effexor ) w szczególności ma bardzo krótki okres półtrwania w przybliżeniu 5 godzin, co oznacza, że lek ustępuje z organizmu bardzo szybko i objawy przerwania może być ciężka i nagle.\n\nDlaczego SNRI są trudniejsze do zatrzymania niż SSRI\nSNRIs wpływają na dwa leki mózgowe regulujące mooding serotonina i noradrenalina, co oznacza, że zarówno trzeba ponownie po zatrzymaniu. Objawy odstawienia są często bardziej intensywne z SNRIZ niż SSRIs:\n• Objawy podobne do fluorescencji, zaburzenia rytmu serca, bóle mięśni )\n• Bezsenność i zaburzenia snu\n• Nudności często bardziej wyraźne niż w przypadku SSRI\n• Zaburzenia równowagi i zawroty głowy\n• Zaburzenia czuciowe Zaburzenia w mózgu mogą być bardzo intensywne z wenlafaksyną\n• Nadwrażliwość, drażliwość i niepokój\n\nPorównanie SNRI\nVenlafaksyna ma najtrudniejszy profil przerwania leczenia ze względu na krótki okres półtrwania. Duloxetine Cymbalta ) wydaje się być nieco łatwiejsze ze względu na dłuższy okres półtrwania 12 godziny. Desvenlafaksyna spada między dwunastym.';

  @override
  String get snriReferenceDay7 =>
      'Tydzień po SNRIS- Dwa systemy Brain- Chemical Dostrajanie\n\nŹródło: NHS — Stopping or coming off antidepressants (general antidepressant guidance; the noradrenaline-specific mechanisms below reflect general SNRI pharmacology rather than SNRI-specific detail from the NHS page itself)\n\nDual- System Challenge\nW przeciwieństwie do większości leków przeciwdepresyjnych, które wpływają na jeden system, SNRI wpływają zarówno serotoniny i noradrenaliny.\n\nDziałania systemu noradrenaliny\nSystem noradrenaliny reguluje reakcje organizmu na loty, regulację ciśnienia krwi i poziom energii.\n• Mogą wystąpić wahania ciśnienia tętniczego krwi\n• Lęk może odczuwać bardziej fizyczne serce wyścigowe, dreszcze )\n• Poziomy energii mogą być niespójne\n\nDziałanie na układ serotoninowy\nRównolegle, system serotoninowy dostosowuje się do objawów odstawiennych typowych dla zatrzymania antydepresantów. Połączenie obu systemów dostosowywania może sprawić, że pierwszy tydzień szczególnie trudne.\n\nFizycznie to często pokazuje, jak poprawia stabilność ciśnienia krwi i mniej epizodów zawrotów głowy na postoju. Emocjonalnie, nastrój jest bardziej zmienny niż będzie w 30 dni, ale już nie w wolnym czasie.';

  @override
  String get snriReferenceDay14 =>
      'Dwa tygodnie po SNRIs: Objawy fizyczne słabną\n\nŹródło: Davies & Read (2019), Addictive Behaviors\n\nStatus dwutygodniowy\nDla większości osób po prawidłowym skraplaniu, ostra faza fizyczna jest w dużej mierze ustalana w ciągu dwóch tygodni:\n• Zapy mózgowe znacznie zmniejszone lub nieobecne\n• Ustępowały nudności i objawy podobne do grypopodobne\n• Zawroty głowy i poprawa równowagi\n• Ciśnienie tętnicze krwi i częstość akcji serca stabilizujące się w miarę rebilansowania noradrenaliny\n\nCo za majowy Persist\n• Wrażliwość emocjonalna i zmienność nastroju\n• Lęk, na który szczególnie wpływa system noradrenaliny\n• Zmęczenie, jak system noradrenaliny zapewnia czujność i energię\n\nKontekst badań\nAddictive Behaviors systematic review, Davies Read, 2019) potwierdziło, że efekt odstawienia produktu SNRI jest jednym z najcięższych leków przeciwdepresyjnych, podczas gdy wenlafaksyna wiąże się ze szczególnie wysokim wskaźnikiem istotnych objawów odstawiennych. zy';

  @override
  String get snriReferenceDay30 =>
      'Miesiąc po SNRIs- stabilizacja systemu\n\nŹródło: Davies & Read (2019), Addictive Behaviors — systematic review of antidepressant withdrawal incidence, severity, and duration\n\nFaza stabilizacji\nJeden miesiąc stanowi znaczący kamień milowy w odzyskiwaniu serotoniny i noradrenaliny. W tym przeglądzie stwierdzono, że podczas gdy znaczna mniejszość osób doświadcza efektów odstawiennych trwających dłużej niż kilka tygodni, większość ludzi jest już w bardzo ciężkiej fazie objawów fizycznego przerwania leczenia w tym momencie.\n\nCo zazwyczaj poprawia przez jeden miesiąc\n• Fizyczne objawy przerwania leczenia, zaburzenia czynności mózgu, znużenie, zawroty głowy ) ustąpiły dla większości\n• Ciśnienie krwi wraca do poziomu naturalnego\n• Jakość snu poprawiając REM wzorce snu przywracanie naturalnie\n• Poziomy energii zaczynają się stabilizować w miarę normalizacji regulacji noradrenaliny\n\nEmocjonalna rezolucja Blunchingu\nJednym z najczęściej zgłaszanych doświadczeń na tym etapie jest rozdzielczość emocjonalnego rozmycia wielu ludzi na SNRIs zauważyć załamane emocjonalne range. Jak lek oczyszcza i mózg ponownie, zakres emocjonalny i czułość zazwyczaj wraca.';

  @override
  String get snriReferenceDay90 =>
      'Trzy miesiące po SNRI: typowy okres odstawienia za Tobą\n\nŹródło: Fava i wsp. (2018), \"Withdrawal Symptoms after Serotonin-Noradrenaline Reuptake Inhibitor Discontinuation: Systematic Review\", Psychotherapy and Psychosomatics\n\nTypowy przebieg odstawienia SNRI\nW 61 publikacjach — w tym 22 podwójnie zaślepionych randomizowanych badaniach kontrolowanych — opisywano objawy odstawienne po każdym badanym typie SNRI. Zwykle zaczynały się w ciągu kilku dni od odstawienia i trwały kilka tygodni, także przy stopniowym zmniejszaniu dawki. W publikacjach większą częstość objawów odstawiennych obserwowano przy wenlafaksynie.\n\nDlaczego 90. dzień ma znaczenie\nDziewięćdziesiąt dni to znacznie dłużej niż typowy kilkutygodniowy przebieg. Osiągnięcie trzech miesięcy oznacza, że typowy okres odstawienia SNRI jest już za Tobą.\n\nMożliwy jest dłuższy przebieg\nPrzegląd odnotował też objawy pojawiające się później lub utrzymujące się dłużej. Jeśli po trzech miesiącach nadal występują istotne objawy, omów je z osobą prowadzącą leczenie.';

  @override
  String get snriReferenceDay180 =>
      'Sześć miesięcy po SNRIss: Odzysk mózgu i nerwów\n\nSygnał odzyskiwania danych na temat danych z sześciu miesięcy\nW ciągu sześciu miesięcy po zakończeniu, nadzorowany medycznie taper, ciężki wczesny okres karencji SNRI jest daleko za Tobą. Mood, lunatyk, funkcje seksualne i jasne myślenie miały miesiące do odzyskania:\n• Sposoby serotoninowe: zasadniczo przywrócone\n• Patryki noradrenaliny: normalizacja, z systemem reagowania na stres również osiagnięcie\n• Architektura snu: oczekuje się, że zostanie w pełni przywrócona\n• Funkcje seksualne: w dużej mierze przywrócone dla większości osób zaburzenia seksualne jest częstym efektem ubocznym SNRI, choć dla niektórych może utrzymywać się i warto omówić z receptorem )\n\nOdporność na stres\nWiele osób w ciągu sześciu miesięcy raportuje przede wszystkim poprawę odporności na stres codzienny, ponieważ noradrenalina odgrywa rolę w reakcji pobudzającej i stresowej, którą SNRI siłą moduluje z powrotem do swojego naturalnego poziomu.';

  @override
  String get snriReferenceDay365 =>
      'Rok po SNRIs- odzyskanie\n\nJeden rok: Kompletny Odzysk systemu dual-\nRok po zakończeniu badania SNRI, zarówno systemy serotoniny, jak i noradrenaliny miały pełny cykl adaptacji i stabilizacji.\n\nCo dowody faktycznie wspiera w jednym roku\nTen przegląd list terapeutyczny zauważa, że udokumentowane objawy odstawienne pojawiają się zwykle w ciągu kilku dni od zatrzymania i że najbardziej ustępują w ciągu około dwóch tygodni, a następnie nie ma kontrolowanych badań po ludziach dokładnie rok po zaprzestaniu SNRI. Co jest dobrze wspierane przez szerszy obraz kliniczny w tym zakresie:\n• Większość tych, którzy ukończyli prawidłową kroczniejszą i otrzymał wsparcie psychologiczne, pozostaje dobrze\n• Zawroty głowy i zaburzenia seksualne charakteryzujące SNRI zostały w pełni rozwiązane dla większości osób\n• Wyraźne myślenie, w tym korzyści z koncentracji, które SNRI może zapewnić, są utrzymywane przez naturalną funkcję mózgu\n\nZnaczenie tego milestone\nUdane przerwanie leczenia produktem SNRI, szczególnie wenlafaksyną, jest znaczącym osiągnięcie.Intensywność procesu przerwania leczenia oraz zaangażowanie wymagane do zarządzania nim pod nadzorem medycznym wykazują niezwykłą istotność.';

  @override
  String get socialMediaReferenceDay1 =>
      'Powrót z Social Media: dzień pierwszy\n\nŹródło: Lambert et al., \"Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial,\" Cyberpsychology, Behavior, and Social Networking (2022), on PubMed\n\nCo dowód pokazuje\nW tym silnym, kontrolowanym badaniu, ludzie zostali losowo przydzieleni albo do jednego tygodnia przerwy od Facebook, Instagram, Twitter i TikTok lub do dalszego korzystania z nich jak zwykle. Grupa przerw wykazała znaczącą poprawę samopoczucia i zmniejszenie depresji i anxiete. to jest really, kontrolowane dowody, że krok wstecz pomaga.\n\nCo dowód pokazuje\nKompulsywne wykorzystanie mediów społecznościowych jest silnie związane z niższym nastroju i większą niepokoju, a randomizowane badania pokazują, że umyślnie odcięcie może poprawić samopoczucie przy jednoczesnym zmniejszeniu depresji i lęku w ciągu tygodnia.\n\nDzień pierwszy: Czego się spodziewać\n• Niepokój i chęć sprawdzenia\n• / Widmo powiadomień, / / uczucie szumu, który się nie wydarzył. /\n• Nuda, jak dostosować się do mniej stałej stymulacji\nSą to normalne sensacje związane z mieszkaniami, i są one tymczasowe. Uznanie wzorca jest pierwszym krokiem w zmianie.';

  @override
  String get socialMediaReferenceDay3 =>
      'Trzy dni bez społecznych mediów: niepokój i nastroje\n\nŹródło: Lambert et al., \"Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial,\" Cyberpsychology, Behavior, and Social Networking (2022), on PubMed\n\nDlaczego przerwa pomaga nastrojowi\nW tym kontrolowanym procesie, ludzie losowo przypisani do jednotygodniowej przerwy od mediów społecznościowych zakończył się tydzień z mniejszym lękiem i depresją i wyższym samopoczuciem niż ci, którzy nadal scrolling. większość dnia – to – dniowy stres ciężkiego użytkowania pochodzi z porównania społecznego mierzenia prawdziwego życia wobec innych cenionych cechami wyróżniającymi i z niskiej klasy przyciągania strachu – o – nieobecność – out.\n\nCo się dzieje około 72 godzin\nNa początku przerwy, nawyk jest wciąż głośny:\n• Silne potrzeby do kontroli, często wywołane przez rutynowe momenty budzenia, czekając w kolejce )\n• Pewne drażliwość i niepokój\n• Dla niektórych ludzi, pierwsze złagodzenie lęku porównawczego\n• Zwoje przed snem zaczynają się luzować.\n\nPętla sieci porównawczej\nBez stałego karmienia innych ludzi wzwyż, porównanie, że napędza dużo społeczne – medialne niepokój ma mniej paliwa. Wyniki trialthres sugerują, że do końca pierwszego tygodnia te wczesne zmiany sumują się do wymiernej poprawy nastroju, więc dyskomfort w trzech dniach jest trudną częścią zmiany, która się opłaca.';

  @override
  String get socialMediaReferenceDay7 =>
      'Tydzień bez opieki społecznej: Zmierzona wypłata\n\nŹródło: Lambert et al., \"Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial,\" Cyberpsychology, Behavior, and Social Networking (2022), on PubMed\n\nDokładnie tydzień wcześniej i to zadziałało.\nJest to kamień milowy, który badania przemawiają najbardziej bezpośrednio: interwencja trialgis była jednotygodniową przerwą. W porównaniu z ludźmi, którzy nadal korzystali z mediów społecznych, grupa przerw wykazała znacznie wyższe samopoczucie i znacznie niższe depresja i niepokój po zaledwie siedmiu dniach. Osiągnięcie jednego tygodnia osiąga punkt, w którym kontrolowane badanie okazało się prawdziwe korzyści.\n\nCo ludzie zauważają\nOprócz mierzonych nastrojów, ludzie często zgłaszają:\n• Więcej odzyskanego czasu jest zaskoczony, jak dużo wydawali\n• Łatwiej skupić, jak nawyk stałej uwagi – przełączające luzy\n• Spokojne wieczory i łatwiejszy sen bez zwoju przedłóżkowego\nZyski te odpowiadają szerszej poprawie jakości pomiaru w procesie.\n\nKontynuuj\nJeden tydzień to ważny, potwierdzony przez dowody kamień milowy.';

  @override
  String get socialMediaReferenceDay14 =>
      'Dwa tygodnie bez socjalnego medium: dwutygodniowe zyski\n\nŹródło: Coyne & Woodruff, \"Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults,\" Behavioral Sciences (2023), on PubMed Central\n\nO tym badaniu\nMłodzi dorośli ograniczyli media społecznościowe do około 30 minut dziennie przez dwa tygodnie, z użyciem śledzone obiektywnie na swoich telefonach, a następnie spadła o około 78th. Uczestnicy cięcia korzystania z mediów społecznościowych o około 7800.000, dając ten kamień milowy bezpośredni real- world test tego, co dzieje się, gdy użycie jest gwałtownie zmniejszone przez dwa tygodnie.\n\nCo poprawiło\nW ciągu dwóch tygodni uczestnicy wykazali poprawę w zakresie:\n• Czas trwania i jakość snu\n• Zadowolenie z życia\n• Stres\n• Przyzwoity wellness\n• Wyniki na smartfonie i skali uzależnienia od mediów społecznościowych\nZmierzone zyski były konkretne: dłuższy i lepszy sen, niższe stres, większa satysfakcja życia i postrzegane dobre samopoczucie, i niższe smartphoneensmartphone społeczne – medialne wyniki uzależnienia.\n\nUważaj na przesuwanie\nNaukowcy zauważyli również, że używają skradania się w kierunku poprzednich poziomów po. Dwa tygodnie jest prawdziwym zarobkiem, ale podkreśla, dlaczego celowy plan nie tylko tymczasowa przerwa jest to, co utrzymuje korzyści.';

  @override
  String get socialMediaReferenceDay30 =>
      'Miesiąc bez społecznych mediów: prawdziwe połączenia\n\nŹródło: Coyne & Woodruff, \"Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults,\" Behavioral Sciences (2023), on PubMed Central\n\nPołączenie może poprawić, gdy krok w tył\nTo brzmi paradoksalnie, ale w tym badaniu, cięcie mediów społecznościowych z powrotem było związane z poprawą w stosunkach wspierających, wraz z lepszą satysfakcją życia i niższe stres. czas i uwaga, że poszedł do paszy stał się dostępny dla ludzi faktycznie w swoim życiu.\n\nCo jeden miesiąc może przynieść\nDo 30 dni, z automatycznym pociągnięciem sprawdzania dużo słabszych, wiele osób znajduje:\n• Rozmowy są bardziej obecne i mniej przerywane\n• Większe zainteresowanie działalnością i hobby w świecie rzeczywistym\n• Self – image opiera się mniej na likach, komentarzach i liczbach followerów\n\nSygnał odzyskiwania\nW ciągu jednego miesiąca, masz utrzymane zdrowszy wzór dla dwukrotnego studyjnego okna interwencji. Sen, stres, życia - zadowolenie, dobre samopoczucie, i korzyści w związku mierzone w dwóch tygodniach miały kolejne dwa tygodnie, aby skonsolidować się w rutyny.\n\nZrobić licznik czasu\nCelem jest wypełnienie wolnego czasu działaniami, które budują prawdziwe połączenie i zadowolenie, a nie po prostu wymiana jednego ekranu na inny.';

  @override
  String get socialMediaReferenceDay60 =>
      'Dwa miesiące bez społecznych Media- co dowody wspierają\n\nŹródło: Ramadhan et al., \"Impacts of digital social media detox for mental health: A systematic review and meta-analysis,\" Narra J (2024), on PubMed Central\n\nNajbardziej niezawodny obraz\nNaukowcy łącznie wyniki z 10 badań, w tym siedmiu kontrolowanych badań. Najwyraźniejszym wynikiem było znaczące zmniejszenie objawów depresyjnych po ustąpieniu ludzi z opieki społecznej.\n\nNajsilniejszy wynik\nPrzez dwa miesiące utrzymywałeś ten sam rodzaj mniejszego narażenia cyfrowego, który powodował te korzyści dla zdrowia psychicznego.\n\nJak wyglądają dwa miesiące?\nPrzy mniejszym porównaniu dziennym i mniejszym obciążeniu, obraz własny ma znacznie mniejszy powód, by polegać na liczbach, komentarzach lub krajach, w których następcy są zaangażowani, podczas gdy najsilniejsze zbiorcze dowody wskazują na zmniejszenie objawów depresyjnych.\n\nPraktyczne podejście\nDowody nagradzają intencjonalną, trwałą zmianę. Użyj dwumiesięcznego punktu, aby utrzymać zamierzone ograniczenia zamiast dryfować z powrotem, a także inwestować w offline źródła znaczenia i połączenia.';

  @override
  String get socialMediaReferenceDay90 =>
      'Trzy miesiące bez społecznych mediów: Nowy Normalny\n\nŹródło: Coyne & Woodruff, \"Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults,\" Behavioral Sciences (2023), on PubMed Central\n\nSleep Is the standout\nWśród tych badań najczystsze wyniki były lepsze sen i czas trwania i jakość, gdy uczestnicy cięcia mediów społecznościowych w prawo back. Przez trzy miesiące trwał zdrowszy wzór, późny zwój nocy, który spożywał do snu długo przestał konkurować z odpoczynku, a lepszy sen ma tendencję do podnoszenia mood, koncentracja, i energii z tym.\n\nCo jeszcze poprawiło\nW tym samym badaniu stwierdzono korzyści w stresie, satysfakcji życia, postrzegane dobre samopoczucie, i relacje wspierające. W trzech miesiącach nie są to już nowości, ponieważ mieli czas, aby osiedlić się w nowej normy.\n\nSygnał dotyczący odzyskania środków w ramach mechanizmu\nOdcięcie mediów społecznościowych znacznie poprawiło czas trwania snu i jakość snu w badaniu interwencyjnym. Trzy miesiące utrzymania tego wzorca zamienia redukcję późnej nocy w trwałe miejsce do spania.\n\nObecność i stosunki\nZ odruchem, aby wypełnić każdy spokojny moment z telefonu dużo słabsze, będąc obecne w konwersacjach, posiłków i przestojów przychodzi bardziej naturalny. i relacje, które zainwestowałeś w ponad trzy miesiące wydają się być silniejsze.';

  @override
  String get socialMediaReferenceDay180 =>
      'Sześć miesięcy bez społecznych mediów: Zmierzone ożywienie\n\nŹródło: Ramadhan et al., \"Impacts of digital social media detox for mental health: A systematic review and meta-analysis,\" Narra J (2024), on PubMed Central\n\nCo dodaje Meta- Analiza\nW połączeniu z 10 badaniami, w tym z siedmioma badaniami kontrolowanymi, badacze znaleźli wyraźne zmniejszenie objawów depresji po zmniejszeniu lub przerwaniu leczenia.\n\nCo właściwie znalazł\n• Depresja: statystycznie istotna redukcja, co jest najwyraźniejszym, najbardziej konsekwentnym korzyście)\n• Uznanie życia: brak znaczącego efektu\n• Stresowanie: brak istotnego efektu\n• Ogólny stan zdrowia psychicznego: brak istotnego wpływu\nNajsilniejszy zbiorczy wynik jest jasny: cyfrowy detox znacznie zmniejsza objawy depresyjne.\n\nDlaczego nadal możesz czuć szerokie korzyści\nSześć miesięcy zmniejszonej ekspozycji na paszę, a praktyczne korzyści widoczne w krótszych interwencjach: bardziej dostępny czas, mniej kompulsywne sprawdzanie i trwałe zmniejszenie narażenia cyfrowego związanego z objawami depresyjnymi.\n\nZachować kontrolę nad paszą\nNajwiększe zyski pochodzą z łamania ciężkiej, pasywnej, kompulsywne wykorzystanie. Przez sześć miesięcy, celowa kontrola nad mediów społecznościowych jest nowy domyślny, a nie paszy kontrolującej swoją uwagę.';

  @override
  String get socialMediaReferenceDay365 =>
      'Rok bez społecznych mediów: Odnowiony związek\n\nŹródło: Ramadhan et al., \"Impacts of digital social media detox for mental health: A systematic review and meta-analysis,\" Narra J (2024), on PubMed Central\n\nRok długotrwałych zmian\nNajsilniejsze połączone badania pokazują, że odchodzenie od mediów społecznych zmniejsza objawy depresyjne. Pełny rok oznacza, że niska ekspozycja wzór stał się normalny, a nie krótki przełom.\n\nCo rok buduje\nCały rok daje setki godzin z powrotem do prawdziwych relacji, hobbystów, umiejętności, refleksji, i kreatywności. Automatyczne sprawdzanie miał pełny rok, aby osłabić, podczas gdy te offline rutyny miały pełny rok do umocnienia.\n\nKorzyści trwałe\nNajwyraźniejszy mierzony przyrost mentalny- zdrowie jest niższe objawy depresyjne. Praktyczne zyski więcej czasu, mniej przerw, i mniej kompulsywne sprawdzanie związek każdego dnia zachować kontrolę paszy.\n\nCo będzie dalej\nRok zamierzonych zmian zresetował relacje. Niezależnie od tego, czy powrócisz do ograniczonego, zamierzonego użycia czy pozostania poza grupą, pętla kompulsywna została przerwana i to jest trwała wygrana.';

  @override
  String get ssriReferenceDay3 =>
      'Przerwanie stosowania SSRI: pierwsze dni\n\nŹródło: Harvard Health Publishing\n\nWażna uwaga dotycząca bezpieczeństwa\nSSRIs należy przerywać wyłącznie pod nadzorem lekarza po stopniowym zmniejszaniu dawki. Nagłe zaprzestanie stosowania produktu leczniczego, szczególnie po długotrwałym stosowaniu, znacznie zwiększa nasilenie objawów odstawiennych.\n\nCo to jest SSRI Syndrome przerwania leczenia?\nZespół odstawienny SSRI jest dobrze udokumentowanym zjawiskiem medycznym, które występuje po zaprzestaniu stosowania SSRI. Klinicy używają skrótu FINISH w celu opisania wspólnych objawów:\n• Objawy podobne do fluorescencji, zaburzenia rytmu serca, bóle mięśni )\n• Bezsenność i zaburzenia snu\n• nudności\n• Zaburzenia równowagi i zawroty głowy\n• Zaburzenia czuciowe, szczególnie zaburzenia w mózgu\n• Nadwrażliwość, drażliwość i niepokój\n\nHalf- Life Matters\nOkres półtrwania fluoksetyny w produkcie Prozac wynosi bardzo długo 4 tygodnie, więc skutecznie zmniejsza się i powoduje łagodniejsze skutki odstawienne. paroksetyna w produkcie Paxil ) ma najkrótszy okres półtrwania w przypadku wspólnego SSRIZ i wywołuje najintensywniejsze objawy odstawienne. sertralina, cytalopram i escytalopram ulegają zmniejszeniu.';

  @override
  String get ssriReferenceDay7 =>
      'Tydzień po SSRIs: Faza ostra\n\nŹródło: NHS — Stopping or coming off antidepressants\n\nFaza ostrego przerwania leczenia\nNHS dokumentuje, że większość objawów odstawienia leków przeciwdepresyjnych rozpoczyna się w ciągu pięciu dni od zatrzymania i trwa do sześciu tygodni w większości przypadków. W ciągu jednego tygodnia, ostre objawy fizyczne są zazwyczaj najbardziej wyraźne i zaczynają tendencję spadkową dla tych, którzy stopili stopni. w ciągu tygodnia, ostre objawy fizyczne są zazwyczaj najbardziej wyraźne i zaczynają tendencję spadkową dla tych, którzy stopniowane stopni. w ciągu tygodnia,\n\nCzego się spodziewać w jednym tygodniu\n• Fizyczne objawy, zaburzenia smaku, podobne do fluyings ) są najbardziej intensywne, ale powinny być coraz łatwiejsze\n• Często występują zaburzenia snu, w tym żywe sny lub bezsenność.\n• Labilność emocjonalna, szybkie zmiany nastroju, często na tym etapie\n• Zapy mózgu mogą być nadal obecne, ale zazwyczaj zaczynają zmniejszać częstotliwość\n\nRola Tapering\nNHS stanowczo zaleca powolne zmniejszanie dawki, czasami w ciągu miesięcy dla osób długotrwale zażywających lek, aby zminimalizować skutki zaprzestania leczenia. Royal College of Psychiatrics opracował wytyczne dotyczące stopniowego zmniejszania dawki, które sugerują bardzo stopniowe zmniejszanie dawki, często przy użyciu preparatów płynnych, dla osób, które przyjmowały SSRI przez dłuższy okres.';

  @override
  String get ssriReferenceDay14 =>
      'Dwa tygodnie po SSRIs: Fizyczne objawy\n\nŹródło: Davies & Read (2019), Addictive Behaviors — \'A systematic review into the incidence, severity and duration of antidepressant withdrawal effects\'\n\nCo odkryto w badaniach\nW tym znaczącym przeglądzie systematycznym stwierdzono, że około 56% osób, które zaprzestały stosowania leków przeciwdepresyjnych, odczuwa skutki odstawienne, a 46% z nich opisuje je jako poważne.\n• Zapy mózgowe znacznie zmniejszone lub nieobecne\n• Ustępowały nudności i objawy podobne do grypopodobne\n• Zawroty głowy i poprawa równowagi\n• Sen zaczyna się normalizować\n\nOdróżniające zaprzestanie nawrotu choroby\nObjawy, które pojawiają się w ciągu kilku dni od zatrzymania i dopasowania profilu FINISH są najprawdopodobniej syndrome zaprzestania. Objawy, które pojawiają się po 2 tygodni i podobne do pierwotnego stanu jest traktowane są bardziej prawdopodobne nawrotu. Monitorowanie tego rozróżnienia z przepisującym jest ważne.';

  @override
  String get ssriReferenceDay30 =>
      'Miesiąc po SSRIs: Stabilizacja\n\nŹródło: Haddad PM (2001), Drug Safety — \'Antidepressant Discontinuation Syndromes\'\n\nFaza stabilizacji\nPrzegląd ten opisuje wystąpienie przerwania leczenia jako gwałtowne, zazwyczaj w ciągu kilku dni od zatrzymania lub zmniejszenia leków przeciwdepresyjnych, i zauważa, że większość reakcji są łagodne i krótkotrwałe, ustępujące bez specyficznego leczenia. Jeden miesiąc oznacza przejście z ostrego okna do stabilizacji; dla większości osób, które ukończyły stopniowe zmniejszanie, ostre objawy przerwania leczenia są obecnie w dużej mierze rozwiązane.\n\nPejzaż emocjonalny w jednym miesiącu\nZmiany emocjonalne w ciągu jednego miesiąca są zmienne i ważne dla monitorowania:\n• Niektórzy ludzie czują się emocjonalnie płasko początkowo jak mózg dostosowuje się to zazwyczaj poprawia\n• Inni doświadczają emocjonalnej żywotności, której nie czuli od lat.\n• Poziom lęku znacznie się różni w zależności od stanu indywidualnego i podstawowego\n\nWartość wsparcia dla nielecznictwa\nBadania konsekwentnie pokazują, że terapia rozmowna, taka jak CBT ZZZZZ) i inne terapie psychologiczne oparte na dowodach są wysoce skuteczne w warunkach SSRIs leczenia. SSRIs jednomiesięczny znak jest doskonałym czasem, aby zapewnić, że te podpory są w miejscu.';

  @override
  String get ssriReferenceDay90 =>
      'Trzy miesiące: Przebieg odstawienia osiąga punkt zwrotny\n\nŹródło: Duffy i wsp., \"Antidepressant medication to prevent depression relapse in primary care: the ANTLER RCT,\" Health Technology Assessment (2021)\n\nPomiar po 12 tygodniach\nW badaniu ANTLER losowo przydzielono 478 pacjentów podstawowej opieki zdrowotnej, którzy przyjmowali leki przeciwdepresyjne przez co najmniej 9 miesięcy i czuli się na tyle dobrze, by rozważyć odstawienie. Przyjmowali citalopram, sertralinę, fluoksetynę lub mirtazapinę. Różnica w objawach odstawienia między grupą odstawiającą a grupą kontynuującą leczenie była największa po 12 tygodniach i mniejsza w późniejszych kontrolach.\n\nDlaczego to pasuje do kamienia milowego SSRI\nTrzy z czterech badanych leków — citalopram, sertralina i fluoksetyna — to SSRI. Proste podsumowanie badania wskazuje, że dodatkowe objawy odstawienia po przerwaniu leczenia koncentrowały się głównie w pierwszych 3–4 miesiącach.\n\nMocne trzy miesiące\nDzień 90 wypada dokładnie przy tym zmierzonym punkcie zwrotnym. Potem różnica w objawach odstawienia maleje, dzięki czemu trzy miesiące są konkretnym kamieniem milowym zdrowienia. Jeśli depresja lub lęk wyraźnie wracają, wcześnie skontaktuj się z osobą prowadzącą leczenie.';

  @override
  String get ssriReferenceDay180 =>
      'Sześć miesięcy po odstawieniu antydepresantów: 65% pozostało w dobrym stanie\n\nŹródło: Volkmann i wsp. (2026), European Archives of Psychiatry and Clinical Neuroscience\n\nKonkretny wynik po sześciu miesiącach\nBadanie obserwowało osoby, u których duża depresja była w remisji, podczas odstawiania leków przeciwdepresyjnych. Spośród 83 uczestników z danymi po sześciu miesiącach 54 — 65% — pozostało w dobrym stanie, a 29 miało nawrót.\n\nDlaczego ten kamień milowy ma znaczenie\nTen zmierzony wynik po sześciu miesiącach czyni ten moment realnym kamieniem milowym długoterminowej stabilności. Badanie oceniało również objawy odstawienne oddzielnie od nawrotu, pomagając rozróżnić oba zjawiska.\n\nJeśli objawy depresji wyraźnie wracają, skontaktuj się wcześnie z lekarzem prowadzącym.';

  @override
  String get ssriReferenceDay365 =>
      'Rok po długotrwałym stosowaniu leków przeciwdepresyjnych: co zmierzyło ANTLER\n\nŹródło: Duffy i wsp. (2021), Health Technology Assessment — badanie ANTLER\n\nCo naprawdę wykazało badanie\nANTLER objęło losowym przydziałem 478 dorosłych pacjentów podstawowej opieki zdrowotnej w Wielkiej Brytanii, którzy czuli się na tyle dobrze, by rozważyć odstawienie długotrwale stosowanych leków przeciwdepresyjnych. Do 52. tygodnia nawrót wystąpił u 56% osób w grupie odstawienia i u 39% w grupie leczenia podtrzymującego. Hazard nawrotu w czasie był około dwukrotnie wyższy (HR 2,06), ale obserwowane roczne odsetki nawrotów wynosiły 56% wobec 39% — nie dwa razy więcej.\n\nPełniejszy obraz\nOdstawienie nie było ślepą uliczką: 44% uczestników nie miało nawrotu w ciągu 52 tygodni badania. Średnio wyniki przemawiały jednak za leczeniem podtrzymującym: w grupie odstawienia było więcej objawów odstawiennych i mniej lat życia skorygowanych o jakość w ciągu 12 miesięcy. 39% osób przydzielonych do odstawienia wróciło do swojego pierwotnego leku przeciwdepresyjnego.\n\nTwój roczny kamień milowy\nJeśli masz za sobą rok bez leku i czujesz się dobrze, to ogromne osiągnięcie. ANTLER nie mówi, że każdy powinien pozostać na leku ani że każdy powinien go odstawić; pokazuje, dlaczego ryzyko nawrotu i decyzje o leczeniu wymagają indywidualnej kontroli. Powrót do leku, jeśli go potrzebujesz, jest decyzją kliniczną, a nie porażką.';

  @override
  String get steroidsReferenceDay1 =>
      'Zatrzymanie sterydów anabolicznych: pierwsze dni\n\nŹródło: \"Common symptoms associated with usage and cessation of anabolic androgenic steroids in men,\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nFaza ostra\nPrzegląd ten opisuje wycofanie AAS jako rozwijające się w dwóch fazach. Pierwszy, napędzany przez aktywację sympatycznego układu nerwowego, a nie poziom hormonów, pojawia się w ciągu 1 mniej 2 dni od zatrzymania i może obejmować:\n• Ból głowy\n• Drżenia\n• Kołatanie serca\n• nudności\n\nDlaczego pojawiają się objawy\nSterydy anaboliczne również tłumić ciała własnej produkcji testosteronu Wówczas mózg wykrywa sterydy i wyłącza sygnały hormonalne, które normalnie napędzają.\n\nNota bezpieczeństwa\nDepresja może pojawić się podczas wycofywania sterydów i stać się poważne. Poszukaj opieki medycznej, i pilnej pomocy dla myśli samoucznych. Klinicy. często przewodnik recovery; niektóre leki do wsparcia tego.';

  @override
  String get steroidsReferenceDay14 =>
      'Dwa tygodnie od Sterydy anaboliczne\n\nŹródło: \"Common symptoms associated with usage and cessation of anabolic androgenic steroids in men,\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nPrzewlekła faza ustawia się\nW ciągu dwóch tygodni, krótkie objawy współczulne pierwszych dni zazwyczaj mijają, a przeglądy drugiej fazy napędzane trwającym niedoborem testosteronu jest bardziej widoczne:\n• Zmęczenie i niski nastrój\n• Bóle mięśniowe ( Bethumyalgia )\n• Zmniejszone libido\n• Bezsenność i zachcianki\n\nNadal na niskim Ebb\nNaturalna produkcja testosteronu trwa znacznie dłużej niż dwa tygodnie, więc ta faza jest oczekiwana, niż znak, że coś jest nie tak.\n\nZnany pułapek\nNiektórzy mężczyźni wracają do używania specjalnie do ucieczki z tej luki, cykl, który resetuje zegar odzyskiwania zamiast zakończyć. Wsparcie od lekarza lub doradcy pomaga pokonać tę fazę, a nie leczenie go z większą ilością steroidów.';

  @override
  String get steroidsReferenceDay30 =>
      'Miesiąc od Sterydy anaboliczne\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" on PubMed\n\nOdzyskiwanie rozpoczyna się\nPo zatrzymaniu, sygnały hormonalne, które mówią jąder, aby testosteronu zacząć z powrotem na. Badania kładzie wiele z tego odzysku w trzy- do - sześciu miesięcy, więc w jednym miesiącu proces jest już pod.\n\nCzego się spodziewać\nNiski nastrój, libido, i energii powszechnie utrzymuje się podczas hormonów wspinać się z powrotem. Odzyskiwanie zależy od wieku i jak ciężkie i długotrwałe było stosowanie.';

  @override
  String get steroidsReferenceDay90 =>
      'Trzy miesiące poza Sterydy anaboliczne\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" on PubMed\n\nDobry czas na badanie krwi\nPrzez trzy miesiące, hormon miał czas, aby pokazać znaczące odzyskiwanie. to jest przydatny punkt, aby poprosić lekarza, aby sprawdzić testosteronu i hormonów, które kontrolują.\n\nCzego się spodziewać\nDla wielu mężczyzn w trzech miesiącach, poziomy są wspinaczki. ale nie w pełni normalizowany. nastroje i libido często poprawić przed testosteronu w pełni łapie się. Rozmiar jąder i produkcji nasienia odzyskać wolniej i może utrzymać poprawę w ciągu następnego roku. wzrost tkanki piersi gynaecomastias, gdzie to się zdarzało, jest mało prawdopodobne, aby odwrócić bez specyficznego leczenia.';

  @override
  String get steroidsReferenceDay180 =>
      'Sześć miesięcy poza Sterydy anaboliczne\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" on PubMed\n\nW przypadku gdy dowody wskazują\nW przeglądzie donosi, że LH i FSH zaburza hormony, które mówią jąder, aby testosteronu zwykle odzyskać w ciągu około trzech do sześciu miesięcy. Przez sześć miesięcy, testosteron sam jest dobrze na swojej ścieżce odzyskiwania również.\n\nJeśli jeszcze tam nie jesteś\nJeśli objawy niskiego testosteronu są nadal obecne w sześciu miesiącach, endokrynolog może sprawdzić, co się dzieje i dyskutować o leczeniu, a nie pozostawiając cię do oczekiwania.';

  @override
  String get steroidsReferenceDay365 =>
      'Rok bez sterydów anabolicznych\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nRok bez sterydów\nRegeneracja po AAS jest bardzo zróżnicowana. Przegląd opisuje niemal pełny powrót testosteronu w ciągu miesięcy, powrót gonadotropin w około trzy do sześciu miesięcy oraz regenerację wielkości jąder i produkcji plemników przez miesiące lub lata. Regeneracja psychiczna jest mniej przewidywalna.\n\nRok naprawdę się liczy\nPełny rok bez sterydów to ogromny kamień milowy, ale nie uniwersalny termin, do którego wszystkie hormony muszą się unormować. Jeśli objawy niskiego testosteronu nadal występują, specjalistyczna ocena może pokazać, na jakim etapie jest regeneracja.';

  @override
  String get steroidsReferenceDay730 =>
      'Dwa lata bez sterydów anabolicznych\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nDwa mocne lata\nDwa lata bez sterydów to długi okres bez ponownej ekspozycji. Regeneracja zależy między innymi od wieku i skali wcześniejszego używania androgenów; nie ma uniwersalnej granicy dwóch lat, po której hormony każdej osoby muszą być prawidłowe.\n\nDługi dystans\nPrzegląd opisuje regenerację testosteronu w ciągu miesięcy i gonadotropin w około trzy do sześciu miesięcy, a wielkość jąder i produkcja plemników mogą poprawiać się przez miesiące lub lata. Utrzymujące się objawy niskiego testosteronu wymagają oceny specjalisty, a nie kolejnego cyklu sterydów.';

  @override
  String get tcaReferenceDay3 =>
      'Odstawienie TCA: pierwsze dni — odbicie cholinergiczne\n\nŹródło: Dilsaver, Feinberg & Greden (1983), American Journal of Psychiatry — \'Antidepressant withdrawal symptoms treated with anticholinergic agents\' (opis 3 przypadków)\n\nDlaczego odstawienie TCA może być inne\nWiele TCA ma działanie antycholinergiczne obok wpływu na serotoninę i noradrenalinę. W trzech opublikowanych przypadkach objawy odstawienne po nagłym przerwaniu lub szybkim zmniejszeniu dawki ustąpiły po leczeniu antycholinergicznym, co skłoniło autorów do wskazania ośrodkowej nadaktywności cholinergicznej jako jednego z mechanizmów.\n\nOpisywane objawy odstawienia TCA\n• Nudności, wymioty, biegunka, ból brzucha i utrata apetytu\n• Bezsenność lub inne zaburzenia snu\n• Lęk, pobudzenie i drażliwość\n• Bóle głowy i inne objawy fizyczne\n\nTempo jest różne\nObjawy odstawienne mogą pojawić się wcześnie, zwłaszcza po nagłym przerwaniu lub szybkim zmniejszeniu dawki. Ten opis trzech przypadków wspiera odbicie cholinergiczne jako mechanizm. Badanie nie zostało zaprojektowane do ustalania stałego przebiegu dzień po dniu ani do porównywania poszczególnych TCA pod względem siły odbicia.';

  @override
  String get tcaReferenceDay7 =>
      'Tydzień po TCA: pierwszy etap za Tobą\n\nCo oznacza tydzień\nWedług NHS objawy odstawienia antydepresantów zwykle zaczynają się w ciągu kilku dni i trwają kilka tygodni. U części osób mogą być ciężkie albo utrzymywać się miesiącami lub dłużej.\n\nObjawy, które nadal mogą występować\n• Ból głowy i bóle mięśni\n• Nudności i pocenie się\n• Przyspieszone, trzepoczące, mocne lub nieregularne bicie serca\n• Zawroty głowy lub niestabilność\n• Problemy ze snem, dziwne sny i zmęczenie\n• Niepokój, drażliwość, lęk, obniżony nastrój lub trudności z myśleniem\n\nSiedem dni to postęp\nPełny tydzień bez TCA zasługuje na świętowanie. NHS opisuje odstawienie jako proces trwający od kilku dni do kilku tygodni, czasem dłużej, więc objawy związane z rytmem serca, trawieniem, snem i innymi funkcjami autonomicznymi mogą uspokajać się w różnym tempie.';

  @override
  String get tcaReferenceDay14 =>
      'Dwa tygodnie po TLPD: ostry etap odstawienia zwykle słabnie\n\nTypowe ostre okno\nPrzegląd kliniczny zespołu odstawienia leków przeciwdepresyjnych podaje, że typowe objawy — w tym objawy grypopodobne, bezsenność, nudności, zaburzenia równowagi, objawy czuciowe i nadmierne pobudzenie — zwykle trwają od jednego do dwóch tygodni.\n\nCo oznacza dzień 14\nPo dwóch tygodniach wiele osób dociera do końca klasycznej ostrej fazy odstawienia. Objawy pierwszej fali są często wyraźnie słabsze na tym etapie.\n\nCzternaście dni bez TLPD\nDzień 14 staje się więc realnym markerem zdrowienia: ostra fala odstawienia często zaczyna się załamywać, a najtrudniejszy początek zostaje z tyłu.';

  @override
  String get tcaReferenceDay30 =>
      'Miesiąc po odstawieniu TCA: ostry zespół odstawienny zwykle ustąpił\n\nTypowe ostre okno\nWarner i wsp. podają, że objawy odstawienia leków przeciwdepresyjnych są zwykle łagodne i trwają od jednego do dwóch tygodni. TCA są wyraźnie uwzględnione; po ich odstawieniu szczególnie charakterystyczne mogą być problemy z równowagą i ruchem.\n\nCo oznacza dzień 30\nPo miesiącu większość osób jest już daleko poza typową ostrą fazą. Objawy grypopodobne, nudności, zaburzenia równowagi, bezsenność, zaburzenia czucia i nadmierne pobudzenie zwykle wyraźnie słabną lub ustępują.\n\nTrzydzieści mocnych dni\nMiesiąc bez TCA to konkretny marker zdrowienia: klasyczne ostre okno odstawienia zwykle jest już za tobą.';

  @override
  String get tcaReferenceDay90 =>
      'Trzy miesiące po odstawieniu TCA: ostry zespół odstawienny daleko za tobą\n\nTypowe ostre okno\nWarner i wsp. podają, że objawy odstawienia leków przeciwdepresyjnych są zwykle łagodne i trwają od jednego do dwóch tygodni. TCA są wyraźnie uwzględnione; po ich odstawieniu szczególnie charakterystyczne mogą być problemy z równowagą i ruchem.\n\nCo oznacza 90. dzień\nPo 90 dniach jesteś ponad dziesięć tygodni za górną granicą tego typowego ostrego okna. Jeśli wystąpiły klasyczne objawy pierwszej fali—objawy grypopodobne, nudności, zaburzenia równowagi, bezsenność, zaburzenia czucia i nadmierne pobudzenie—zwykle dawno już osłabły lub ustąpiły.\n\nDziewięćdziesiąt mocnych dni\nTrzy miesiące bez TCA to konkretny marker zdrowienia: ostry zespół odstawienny zwykle jest już daleko za tobą. Jeśli wracają istotne objawy depresji, skontaktuj się wcześnie z lekarzem.';

  @override
  String get tcaReferenceDay180 =>
      'Sześć miesięcy po odstawieniu leków przeciwdepresyjnych: większość bez nawrotu\n\nSześciomiesięczny punkt kontrolny nawrotu\nMetaanaliza z 2024 roku połączyła 35 randomizowanych badań odstawiania leków przeciwdepresyjnych u osób leczonych z powodu dużej depresji. Łączny odsetek nawrotów po odstawieniu wyniósł 34,81% po sześciu miesiącach — czyli około 65% osób pozostawało wtedy bez nawrotu.\n\nRzeczywisty wynik długoterminowy\nTa sama analiza wykazała odsetek nawrotów 45,12% po 12 miesiącach. Sześć miesięcy to ważny punkt stabilności: większość uczestników połączonych badań nie doświadczyła do tego czasu nawrotu.\n\nChroń postęp\nJeśli objawy depresji zaczną wracać, wcześnie skontaktuj się z lekarzem. Sześć miesięcy to ogromny okres stabilności, który warto chronić.';

  @override
  String get tcaReferenceDay365 =>
      'Rok po odstawieniu leków przeciwdepresyjnych: większość pozostała bez nawrotu\n\nPunkt kontrolny po 12 miesiącach\nMetaanaliza z 2024 roku połączyła 35 randomizowanych badań dotyczących odstawiania leków przeciwdepresyjnych u osób leczonych z powodu dużej depresji. Łączny odsetek nawrotów po odstawieniu wyniósł 45,12% po 12 miesiącach — co odpowiada około 55% osób bez nawrotu w punkcie rocznym.\n\nPełny rok stabilności\nTa sama analiza wykazała odsetek nawrotów 34,81% po sześciu miesiącach. Po 12 miesiącach większość uczestników połączonych badań nadal nie miała nawrotu. Pełny rok bez nawrotu to ważny kamień milowy długoterminowej stabilności.\n\nChroń postęp\nJeśli objawy depresji zaczną wracać, skontaktuj się wcześnie ze swoim lekarzem lub terapeutą. Osiągnięcie pełnego roku to duży sukces, który warto chronić.';

